a"}, {"test": "cmp_extra", "why": "Assesses liver injury, nutrition, and synthetic function"}, {"test": "bmp", "why": "Checks electrolytes, glucose, and kidney function; hypomagnesemia and hypokalemia lower the seizure threshold"}, {"test": "mg", "why": "Hypomagnesemia is common and must be corrected to control withdrawal"}, {"test": "phos", "why": "Hypophosphatemia can worsen during refeeding"}, {"test": "lipase", "why": "Order when epigastric pain radiates to the back or vomiting is prominent", "only_if": "epigastric pain radiating to the back or persistent vomiting"}, {"test": "hcg", "why": "Rules out pregnancy before treatment planning and imaging", "only_if": "patient could be pregnant"}, {"test": "ua", "why": "Screens for urinary infection and ketonuria"}, {"test": "tsh", "why": "Thyroid disease can mimic anxiety, tremor, and palpitations", "only_if": "tremor, palpitations, or unexplained weight change"}, {"test": "ECG", "why": "Looks for tachycardia, QT prolongation, and arrhythmia in moderate to severe withdrawal", "only_if": "moderate or severe withdrawal, palpitations, or chest pain"}, {"test": "CIWA-Ar", "why": "Standard tool to grade withdrawal severity and guide treatment"}, {"test": "AUDIT-C", "why": "Brief validated screen that quantifies unhealthy drinking"}], "confirmatory": [], "supporting": [{"test": "ggt", "why": "Sensitive marker of recent heavy drinking"}, {"test": "folate", "why": "Low folate contributes to macrocytic anemia and neuropathy"}, {"test": "b12", "why": "Check before attributing macrocytosis to alcohol alone"}, {"test": "Right upper quadrant ultrasound", "why": "Assesses steatosis, cirrhosis, and portal hypertension", "only_if": "abnormal liver tests, right upper quadrant pain, or suspected cirrhosis"}, {"test": "CT head without contrast", "why": "Rules out intracranial bleeding or mass", "only_if": "head trauma, focal neurologic deficit, or new confusion"}, {"test": "Chest x-ray", "why": "Evaluates aspiration, pneumonia, or heart failure", "only_if": "cough, fever, hypoxemia, or suspected aspiration"}], "not_indicated": [{"test": "d_dimer", "why": "No role in the evaluation of alcohol use disorder"}, {"test": "procalcitonin", "why": "Not needed unless infection is suspected"}, {"test": "MRI brain without contrast", "why": "Reserved for suspected Wernicke encephalopathy or other structural disease"}, {"test": "CT head without contrast", "why": "Not routine; order only for trauma, focal deficit, or new confusion"}, {"test": "Chest x-ray", "why": "Not routine; order only for respiratory symptoms or suspected aspiration"}, {"test": "Right upper quadrant ultrasound", "why": "Not routine; order only for abnormal liver tests or suspected cirrhosis"}], "decision_points": ["Assess for withdrawal severity with CIWA-Ar and treat before complications such as seizures or delirium tremens develop", "Check pregnancy status before treatment planning and imaging in anyone who could be pregnant", "Give thiamine before or with glucose to prevent Wernicke encephalopathy", "Correct magnesium, potassium, and phosphorus to reduce withdrawal seizures and arrhythmias", "Screen for depression, anxiety, and suicide risk, and reassess after a period of abstinence"], "criteria": [{"name": "Alcohol use disorder, clinical criteria", "summary": "A problematic pattern of drinking causing distress or impairment, with at least two of the following in the past year: drinking more or longer than intended; wanting to cut down or unsuccessful attempts; spending a lot of time drinking or recovering; craving; drinking interfering with work, school, or family; continuing despite relationship problems; giving up important activities; drinking in hazardous situations; continuing despite knowing it worsens a physical or psychological problem; tolerance; and withdrawal. Two to three criteria indicate mild, four to five moderate, and six or more severe disorder.", "items": ["Drinking more or longer than intended", "Persistent desire or unsuccessful efforts to cut down", "Much time spent drinking or recovering", "Craving or strong urge to drink", "Failure to fulfill major role obligations", "Continued drinking despite social or interpersonal problems", "Giving up important activities", "Drinking in physically hazardous situations", "Continued drinking despite physical or psychological problems", "Tolerance", "Withdrawal"]}], "scores": ["ciwa_ar", "audit_c", "cage"]}, "differential": [{"name": "Alcohol intoxication", "slug": "alcohol-intoxication", "why_considered": "Acute drinking episode with slurred speech, ataxia, and disinhibition that can look like the impaired control of AUD", "must_not_miss": false, "discriminators": {"history": ["Single episode or recent binge rather than a chronic pattern", "No craving or withdrawal between episodes"], "exam": ["Slurred speech, ataxia, nystagmus that resolve as alcohol clears", "No tremor or diaphoresis once sober"], "labs": ["Blood alcohol level correlates with exam findings", "Normal MCV, GGT, and liver tests in isolated episodes"]}}, {"name": "Sedative-hypnotic or benzodiazepine use disorder", "slug": "sedative-hypnotic-use-disorder", "why_considered": "Same picture of tolerance, withdrawal, and impaired control with a different substance", "must_not_miss": false, "discriminators": {"history": ["Prescription or illicit benzodiazepine, barbiturate, or sleep aid use", "Withdrawal with anxiety, tremor, and seizures similar to alcohol"], "exam": ["Sedation, ataxia, and slurred speech without alcohol on the breath"], "labs": ["Urine drug screen positive for benzodiazepines or barbiturates", "Normal GGT and MCV"]}}, {"name": "Major depressive disorder", "slug": "major-depressive-disorder", "why_considered": "Low mood, poor sleep, guilt, and anhedonia overlap with AUD and often coexist", "must_not_miss": true, "trigger": "Depressed mood, anhedonia, or suicidal thoughts that persist or predate heavy drinking", "discriminators": {"history": ["Depressive symptoms present during periods of abstinence and before heavy drinking began", "No craving, tolerance, or withdrawal"], "exam": ["Flat affect, psychomotor slowing, no tremor or autonomic hyperactivity"], "labs": ["Normal GGT, MCV, and liver tests"]}}, {"name": "Generalized anxiety disorder", "slug": "generalized-anxiety-disorder", "why_considered": "Anxiety, restlessness, and insomnia are common in both AUD and anxiety disorders", "must_not_miss": false, "discriminators": {"history": ["Worry is pervasive and not limited to drinking or withdrawal", "Symptoms persist during abstinence"], "exam": ["Anxious but no tremor, diaphoresis, or tachycardia at rest"], "labs": ["Normal electrolytes, magnesium, and liver tests"]}}, {"name": "Alcohol withdrawal delirium (delirium tremens)", "slug": "alcohol-withdrawal-delirium", "why_considered": "Severe autonomic hyperactivity, confusion, and hallucinations in a heavy drinker", "must_not_miss": true, "trigger": "Confusion, fever, marked tachycardia, and hallucinations 48–96 hours after the last drink", "discriminators": {"history": ["Abrupt cessation after prolonged heavy drinking", "Prior withdrawal seizures or delirium"], "exam": ["Disorientation, agitation, tremor, diaphoresis, fever, tachycardia", "Visual or tactile hallucinations"], "labs": ["Hypomagnesemia, hypokalemia, low bicarbonate", "Elevated GGT and MCV"]}}, {"name": "Hepatic encephalopathy", "slug": "hepatic-encephalopathy", "why_considered": "Confusion, asterixis, and sleep-wake reversal in a patient with alcohol-associated liver disease", "must_not_miss": true, "trigger": "Asterixis, disorientation, or drowsiness in a patient with known cirrhosis", "discriminators": {"history": ["Known cirrhosis or prior episodes of confusion", "Precipitant such as GI bleed, infection, or constipation"], "exam": ["Asterixis, fetor hepaticus, jaundice, ascites, spider angiomata"], "labs": ["Elevated ammonia, low albumin, prolonged INR, thrombocytopenia"], "imaging": ["Coarse nodular liver with splenomegaly and ascites on ultrasound"]}}, {"name": "Wernicke encephalopathy", "slug": "wernicke-encephalopathy", "why_considered": "Confusion, ataxia, and eye movement abnormalities in a malnourished heavy drinker", "must_not_miss": true, "trigger": "Ophthalmoplegia, nystagmus, ataxia, and confusion in a patient with poor nutrition", "discriminators": {"history": ["Poor oral intake, vomiting, and heavy drinking", "Recent carbohydrate load without thiamine"], "exam": ["Horizontal nystagmus, lateral rectus palsy, gait ataxia, confusion"], "labs": ["Low magnesium and low thiamine", "Macrocytic anemia"], "imaging": ["Mamillary body or medial thalamic signal change on MRI"]}}, {"name": "Acute pancreatitis", "slug": "acute-pancreatitis", "why_considered": "Epigastric pain radiating to the back with vomiting in a heavy drinker", "must_not_miss": true, "trigger": "Severe epigastric pain radiating to the back with vomiting", "discriminators": {"history": ["Constant severe epigastric pain radiating to the back", "Nausea and vomiting without relief"], "exam": ["Epigastric tenderness with guarding", "Decreased bowel sounds"], "labs": ["Lipase more than three times the upper limit of normal", "Elevated AST and ALT"], "imaging": ["Pancreatic edema and peripancreatic fluid on CT"]}}, {"name": "Alcohol-associated hepatitis", "slug": "alcohol-associated-hepatitis", "why_considered": "Jaundice, tender hepatomegaly, and fever in a patient with heavy recent drinking", "must_not_miss": true, "trigger": "Jaundice with tender hepatomegaly and fever after heavy drinking", "discriminators": {"history": ["Heavy drinking within the past weeks", "Anorexia, nausea, and right upper quadrant pain"], "exam": ["Jaundice, tender hepatomegaly, low-grade fever", "May have ascites or encephalopathy"], "labs": ["AST elevated with AST:ALT ratio above 2", "Bilirubin elevated, INR prolonged, neutrophilia"], "imaging": ["Hepatomegaly with increased echogenicity on ultrasound"]}}, {"name": "Alcoholic ketoacidosis", "slug": "alcoholic-ketoacidosis", "why_considered": "Nausea, vomiting, abdominal pain, and tachypnea after a binge with poor intake", "must_not_miss": true, "trigger": "Raised anion gap with ketonuria and low or normal glucose after heavy drinking", "discriminators": {"history": ["Binge drinking with little food for days", "Nausea, vomiting, and abdominal pain"], "exam": ["Tachypnea, tachycardia, dehydration, fruity breath"], "labs": ["Raised anion gap, low bicarbonate, ketonuria", "Glucose low, normal, or mildly elevated"]}}, {"name": "Opioid use disorder", "slug": "opioid-use-disorder", "why_considered": "Impaired control, craving, tolerance, and withdrawal with another substance", "must_not_miss": false, "discriminators": {"history": ["Prescription or illicit opioid use", "Withdrawal with diarrhea, yawning, piloerection, and mydriasis"], "exam": ["Pinpoint pupils when intoxicated", "Track marks"], "labs": ["Urine drug screen positive for opioids", "Normal GGT and MCV"]}}, {"name": "Bipolar disorder", "slug": "bipolar-disorder", "why_considered": "Impulsivity, risky behavior, and heavy drinking during manic or hypomanic episodes", "must_not_miss": false, "discriminators": {"history": ["Distinct episodes of elevated mood, decreased need for sleep, and grandiosity", "Mood symptoms persist during abstinence"], "exam": ["Pressured speech, psychomotor agitation, grandiosity"], "labs": ["Normal GGT and MCV"]}}], "course": {"severity": {"mild": "Two to three criteria met; drinking more than intended with craving and some role interference but no withdrawal or medical complications", "moderate": "Four to five criteria met; tolerance and withdrawal are present, with continued drinking despite health, work, or relationship problems", "severe": "Six or more criteria met; daily or near-daily drinking, morning drinking, blackouts, failed attempts to stop, and medical complications such as liver disease or neuropathy", "critical": "Severe withdrawal with seizures or delirium tremens, or a life-threatening complication such as GI bleeding, pancreatitis, or alcoholic ketoacidosis"}, "red_flags": [{"finding": "Confusion, disorientation, or hallucinations", "meaning": "Delirium tremens or Wernicke encephalopathy; needs urgent treatment and thiamine"}, {"finding": "Seizure during withdrawal", "meaning": "Severe withdrawal; risk of further seizures and status epilepticus"}, {"finding": "Heart rate over 120 with fever and marked tremor", "meaning": "Severe autonomic hyperactivity from withdrawal"}, {"finding": "Vomiting blood or black stools", "meaning": "Upper GI bleeding from varices, gastritis, or Mallory-Weiss tear"}, {"finding": "Severe epigastric pain radiating to the back", "meaning": "Acute pancreatitis"}, {"finding": "Jaundice with tender hepatomegaly and fever", "meaning": "Alcohol-associated hepatitis"}, {"finding": "Suicidal ideation or intent", "meaning": "High risk of self-harm; needs immediate psychiatric evaluation"}, {"finding": "Ataxia, ophthalmoplegia, or nystagmus", "meaning": "Wernicke encephalopathy; give thiamine immediately"}], "complications": [{"name": "Alcohol withdrawal seizures", "timing": "early", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["Last drink 12–48 hours ago", "Prior withdrawal seizures", "Low magnesium or potassium"]}, {"name": "Delirium tremens", "timing": "early", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["Last drink 48–96 hours ago", "Confusion, fever, tachycardia, hallucinations", "Prior episodes of severe withdrawal"]}, {"name": "Wernicke encephalopathy", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Confusion, ataxia, ophthalmoplegia", "Poor nutrition and vomiting", "Recent carbohydrate load without thiamine"]}, {"name": "Alcohol-associated hepatitis", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Recent heavy drinking", "Jaundice, tender hepatomegaly, fever", "AST:ALT ratio above 2"]}, {"name": "Cirrhosis with portal hypertension", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Years of heavy drinking", "Ascites, spider angiomata, thrombocytopenia", "Coarse nodular liver on ultrasound"]}, {"name": "Acute pancreatitis", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Epigastric pain radiating to the back", "Vomiting", "Lipase more than three times normal"]}, {"name": "Alcoholic ketoacidosis", "timing": "early", "seriousness": "serious", "frequency": "rare", "clues": ["Binge drinking with poor intake", "Raised anion gap, ketonuria, low bicarbonate"]}, {"name": "Alcoholic cardiomyopathy", "timing": "late", "seriousness": "serious", "frequency": "rare", "clues": ["Years of heavy drinking", "Dyspnea, orthopnea, leg edema", "Cardiomegaly and low ejection fraction"]}, {"name": "Peripheral neuropathy", "timing": "late", "seriousness": "minor", "frequency": "sometimes", "clues": ["Numbness and tingling in a stocking distribution", "Absent ankle reflexes", "Low folate or thiamine"]}, {"name": "Aspiration pneumonia", "timing": "any", "seriousness": "serious", "frequency": "rare", "clues": ["Heavy drinking with vomiting and decreased consciousness", "Cough, fever, hypoxemia", "Infiltrate on chest x-ray"]}], "special_populations": [{"population": "older_adults", "differences": "They may drink less overall but still meet criteria; they reach higher blood alcohol levels with smaller amounts and often present with falls, confusion, insomnia, or worsening heart failure rather than obvious intoxication."}, {"population": "pregnancy", "differences": "Patients often minimize or hide drinking because of stigma; they may present for prenatal care with poor weight gain, preterm contractions, or fetal growth concerns. No amount of alcohol is considered safe in pregnancy, and withdrawal should be managed with close fetal monitoring."}, {"population": "children", "differences": "Adolescents usually binge drink episodically rather than drink daily; they present with school problems, injuries, or mood changes, and withdrawal is uncommon."}, {"population": "hepatic_impairment", "differences": "Patients with cirrhosis may report much lower intake because they feel intoxicated quickly, and they can present with confusion, bleeding, or abdominal swelling rather than craving. Benzodiazepines for withdrawal must be dosed cautiously and thiamine given before glucose."}, {"population": "renal_impairment", "differences": "Electrolyte derangements and volume shifts are more pronounced; magnesium and potassium replacement must be monitored closely, and renally cleared medications need dose adjustment."}]}, "teaching": {"key_questions": [{"question": "How much do you drink on a typical day, and how many days a week?", "category": "hpi", "importance": "essential", "looking_for": "Quantify in standard drinks; men over 4/day or 14/week and women over 3/day or 7/week exceed recommended limits"}, {"question": "Have you ever tried to cut down or stop, and were you able to?", "category": "hpi", "importance": "essential", "looking_for": "Unsuccessful attempts or a persistent desire to cut down"}, {"question": "Do you ever end up drinking more or for longer than you planned?", "category": "hpi", "importance": "essential", "looking_for": "Impaired control over how much or how long they drink"}, {"question": "Do you ever have a strong urge or craving to drink?", "category": "associated", "importance": "essential", "looking_for": "Craving, a core feature of AUD"}, {"question": "Do you need more alcohol than you used to for the same effect?", "category": "associated", "importance": "important", "looking_for": "Tolerance"}, {"question": "When you stop or cut back, do you get shaky, sweaty, nauseated, or have trouble sleeping?", "category": "associated", "importance": "essential", "looking_for": "Withdrawal symptoms; morning drinking to relieve them suggests more severe dependence"}, {"question": "Have you ever had a seizure or seen or heard things that were not there when you stopped drinking?", "category": "red_flag", "importance": "essential", "looking_for": "Prior withdrawal seizures or hallucinations; marks severe withdrawal risk"}, {"question": "Has drinking caused problems with your job, school, family, or friends?", "category": "social", "importance": "essential", "looking_for": "Role obligations not met, relationship conflict, or giving up activities"}, {"question": "Have you driven after drinking or been in other risky situations while drinking?", "category": "social", "importance": "important", "looking_for": "Hazardous use such as drunk driving or unsafe sex"}, {"question": "Have you kept drinking even though it was making a health problem, depression, or anxiety worse?", "category": "associated", "importance": "important", "looking_for": "Continued use despite physical or psychological harm"}, {"question": "How much of your day is spent drinking or recovering from drinking?", "category": "hpi", "importance": "important", "looking_for": "A great deal of time spent drinking or recovering"}, {"question": "Do you ever have memory gaps or blackouts after drinking?", "category": "associated", "importance": "important", "looking_for": "Blackouts, which suggest heavier or more severe use"}, {"question": "Have you had vomiting of blood or black, tarry stools?", "category": "red_flag", "importance": "essential", "looking_for": "Upper GI bleeding from varices, gastritis, or a Mallory-Weiss tear"}, {"question": "Have you had severe belly pain that goes through to your back, with vomiting?", "category": "red_flag", "importance": "important", "looking_for": "Acute pancreatitis"}, {"question": "Have you felt down, anxious, or had thoughts of harming yourself?", "category": "ros", "importance": "essential", "looking_for": "Depression, anxiety, or suicidal ideation that needs immediate attention"}, {"question": "Does anyone in your family have a problem with alcohol?", "category": "family", "importance": "important", "looking_for": "Family history of AUD in a first-degree relative"}, {"question": "How old were you when you first started drinking regularly?", "category": "social", "importance": "important", "looking_for": "Drinking before age 15, a strong risk factor"}, {"question": "What medications are you taking, including anything for sleep, anxiety, or pain?", "category": "medications", "importance": "important", "looking_for": "Benzodiazepines, opioids, or sedative-hypnotics that add risk"}, {"question": "Could you be pregnant? When was your last period?", "category": "obstetric", "importance": "important", "looking_for": "Pregnancy changes counseling and treatment planning; no amount of alcohol is safe in pregnancy"}], "accepted_names": ["Alcohol use disorder", "AUD", "Alcoholism", "Alcohol dependence", "Alcohol abuse"], "reasoning_points": ["A problematic pattern of drinking causing distress or impairment, with at least two features in the past year", "Impaired control: drinking more or longer than intended, wanting to cut down or unsuccessful attempts, craving, or much time spent drinking or recovering", "Social impairment: failure to meet role obligations, relationship problems, or giving up important activities", "Risky use: drinking in hazardous situations or continuing despite known physical or psychological harm", "Tolerance and withdrawal", "Severity is graded by the number of features: 2–3 mild, 4–5 moderate, 6 or more severe", "Assess for withdrawal severity and complications such as seizures, delirium tremens, liver disease, pancreatitis, and Wernicke encephalopathy", "Screen for co-occurring depression, anxiety, and suicide risk"], "difficulty": {"easy": ["Classic daily heavy drinking with morning drinking, shakes, and blackouts", "Clear failed attempts to quit and family conflict about drinking", "Elevated GGT, MCV, and AST with an AST:ALT ratio above 2", "Patient openly reports craving and withdrawal"], "medium": ["Binge-pattern drinking with normal liver tests and no daily withdrawal", "Patient minimizes drinking; family brings up the problem", "Co-occurring depression or anxiety that makes it hard to tell which came first", "Older adult with falls and confusion rather than obvious intoxication"], "hard": ["Patient presents with a complication such as pancreatitis, GI bleeding, or withdrawal seizure and does not volunteer drinking history", "Adolescent with school problems and injuries but no daily drinking or withdrawal", "Pregnant patient who hides drinking because of stigma", "Patient with cirrhosis who reports low intake because they feel intoxicated quickly", "Confusion from hepatic encephalopathy or Wernicke encephalopathy rather than withdrawal"]}}}$rounds_kb$::jsonb)
