"exposures": [], "risk_medications": []}, "presentation": {"chief_complaints": [{"text": "The school nurse said my vision screening was abnormal", "frequency": "common"}, {"text": "I can't see as well out of one eye", "frequency": "common"}, {"text": "My eye turns in sometimes", "frequency": "sometimes"}, {"text": "I have to sit close to the TV or hold books very near my face", "frequency": "sometimes"}], "hpi": {"onset": "Gradual and painless, usually from infancy or early childhood; often first noticed at a routine vision screening or well-child visit", "duration": "Present for months to years; typically detected between ages 3 and 6", "progression": "Stable or slowly worsening until the underlying cause is treated; vision does not improve on its own once the visual system matures", "location": "One eye (occasionally both eyes)", "radiation": "Not applicable", "quality": "Blurred or reduced vision in the affected eye; the eye itself looks normal", "severity": "Mild to moderate; often the child is unaware because the better eye compensates", "timing": "Constant", "aggravating": ["Covering or patching the good eye, which makes the reduced vision obvious"], "relieving": ["Using the good eye; nothing relieves the blur in the affected eye"], "associated_symptoms": [{"text": "Squinting or closing one eye to see", "frequency": "common"}, {"text": "Tilting or turning the head to see better", "frequency": "sometimes"}, {"text": "Eye turning in or out (strabismus)", "frequency": "sometimes"}, {"text": "Poor depth perception or trouble with sports and catching a ball", "frequency": "sometimes"}, {"text": "Frequent eye rubbing or eye strain with near work", "frequency": "sometimes"}, {"text": "Falling behind or difficulty seeing the board at school", "frequency": "sometimes"}], "pertinent_negatives": ["Eye pain or redness", "Sudden vision loss", "Double vision", "Flashes or floaters", "Eye trauma", "White pupil or leukocoria", "Headaches that wake the child from sleep or worsen with Valsalva", "Vomiting or morning headaches", "Recent illness or fever"]}, "ros": [{"system": "eyes", "positives": [{"text": "Reduced vision in one eye", "frequency": "almost_always"}, {"text": "Squinting or closing one eye", "frequency": "common"}, {"text": "Eye turning in or out", "frequency": "sometimes"}, {"text": "Poor depth perception", "frequency": "sometimes"}], "negatives": ["Eye pain", "Eye redness or discharge", "Sudden vision loss", "Flashes or floaters", "Double vision"], "argues_against": ["Painful red eye", "Acute onset of visual loss"]}, {"system": "neurologic", "positives": [{"text": "Head tilting or turning to see", "frequency": "sometimes"}], "negatives": ["Headache", "Vomiting", "Seizures", "Weakness or numbness", "Gait problems", "Developmental regression"], "argues_against": ["Morning headaches with vomiting", "Focal neurologic deficits", "Regression of milestones"]}, {"system": "constitutional", "positives": [], "negatives": ["Fever", "Weight loss", "Poor feeding or failure to thrive", "Lethargy"], "argues_against": ["Systemic illness with fever", "Failure to thrive"]}], "atypical": [{"population": "infants", "how_it_differs": "Cannot report vision problems; presents with a constant eye turn, poor visual tracking, or an abnormal red reflex on newborn or well-baby screening.", "missing_classic_features": ["Complaint of blurred vision", "Squinting or head tilting reported by the child"]}, {"population": "children", "how_it_differs": "Older children may describe trouble seeing the board or reading, but often the condition is silent and found only on screening because the good eye compensates.", "missing_classic_features": ["Spontaneous complaint of vision loss"]}, {"population": "older_adults", "how_it_differs": "Amblyopia is usually lifelong from childhood; adults may present with longstanding reduced vision in one eye, sometimes unmasked when the good eye develops cataract or other disease.", "missing_classic_features": ["Recent onset", "Active visual development"]}]}, "exam": {"general": {"mild": "Well-appearing, alert, no distress; plays and interacts normally", "moderate": "Well-appearing; may squint, close one eye, or tilt the head when looking at distant targets", "severe": "Well-appearing but visibly favors one eye; may turn or tilt the head to fixate; no systemic illness", "critical": "Not applicable; amblyopia is not a critical illness"}, "findings": [{"id": "reduced-visual-acuity", "region": "heent", "maneuver": "Measure visual acuity in each eye separately (age-appropriate chart, or fixation preference in preverbal children) with the other eye occluded", "finding": "Reduced best-corrected acuity in one eye (or both) compared with the fellow eye", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "interocular-acuity-difference", "region": "heent", "maneuver": "Compare acuity between the two eyes with each eye tested alone", "finding": "Two or more lines of difference between the eyes, or a fixation preference for one eye in a preverbal child", "frequency": "common", "significance": "strongly_supports", "importance": "essential"}, {"id": "strabismus-cover-test", "region": "heent", "maneuver": "Perform the cover-uncover and alternate cover test while the patient fixates on a target", "finding": "Manifest or latent ocular misalignment (esotropia or exotropia) with refixation movement", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "refractive-error", "region": "heent", "maneuver": "Perform cycloplegic retinoscopy or autorefraction after cycloplegia", "finding": "Anisometropia or significant refractive error in the amblyopic eye", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "normal-pupils", "region": "heent", "maneuver": "Check pupillary size, symmetry, and reactivity to light", "finding": "Equal, round, reactive pupils with no afferent pupillary defect", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-red-reflex", "region": "heent", "maneuver": "Shine the ophthalmoscope light into each eye and compare the red reflex", "finding": "Symmetric red reflex with no leukocoria or opacity", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "normal-anterior-segment", "region": "heent", "maneuver": "Inspect the eyelids, conjunctiva, cornea, and lens with a light and ophthalmoscope", "finding": "Clear cornea and lens, no cataract, ptosis, or media opacity", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-fundus", "region": "heent", "maneuver": "Perform dilated funduscopic examination", "finding": "Normal optic disc, macula, vessels, and peripheral retina", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "normal-extraocular-movements", "region": "heent", "maneuver": "Test ductions and versions in all gaze directions", "finding": "Full, conjugate eye movements without restriction or palsy", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-visual-fields", "region": "heent", "maneuver": "Confrontation visual fields in each eye", "finding": "Full visual fields without a defect", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-neurologic-exam", "region": "neuro", "maneuver": "Perform a brief cranial nerve, motor, sensory, coordination, and gait examination", "finding": "No focal neurologic deficits, no papilledema, normal gait and coordination", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-head-shape", "region": "musculoskeletal", "maneuver": "Inspect and palpate the head and face", "finding": "No craniofacial asymmetry, plagiocephaly, or orbital abnormality", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {}, "labs": [], "imaging": [{"study": "MRI brain and orbits with and without IV contrast", "modality": "mri", "preferred_when": "Atypical features: suspected intracranial or optic pathway lesion, nystagmus, optic atrophy, or neurologic findings", "findings": [{"text": "Normal brain, optic nerves, chiasm, and orbits", "frequency": "almost_always"}, {"text": "Intracranial mass, hydrocephalus, or optic pathway glioma (alternative diagnosis)", "frequency": "rare"}]}, {"study": "CT head without contrast", "modality": "ct", "preferred_when": "Urgent evaluation when MRI is unavailable or contraindicated and a structural cause is suspected", "findings": [{"text": "Normal intracranial structures", "frequency": "common"}, {"text": "Hydrocephalus or mass lesion (alternative diagnosis)", "frequency": "rare"}]}], "workup": {"initial": [{"test": "Visual acuity testing with age-appropriate chart (each eye separately)", "why": "Detects reduced acuity and interocular difference; the core diagnostic measurement"}, {"test": "Cover-uncover and alternate cover test", "why": "Identifies strabismus, a common cause of amblyopia"}, {"test": "Cycloplegic retinoscopy or autorefraction", "why": "Detects anisometropia and significant refractive error"}, {"test": "Red reflex examination", "why": "Screens for media opacity such as cataract or leukocoria"}, {"test": "Dilated funduscopic examination", "why": "Evaluates optic nerve, macula, and retina for structural causes"}, {"test": "Ocular motility and alignment examination", "why": "Assesses for strabismus and restriction or palsy"}], "confirmatory": [{"test": "Cycloplegic refraction with best-corrected visual acuity", "why": "Confirms amblyopia by showing reduced acuity not fully explained by refractive error alone and identifies treatable refractive causes"}], "supporting": [{"test": "MRI brain and orbits with and without IV contrast", "why": "Rules out intracranial or optic pathway pathology", "only_if": "atypical features such as nystagmus, optic atrophy, neurologic findings, or poor response to treatment"}, {"test": "CT head without contrast", "why": "Alternative structural imaging when MRI is unavailable or contraindicated", "only_if": "urgent concern for structural lesion and MRI not feasible"}], "not_indicated": [{"test": "MRI brain and orbits with and without IV contrast", "why": "Not routine for typical amblyopia with a clear refractive or strabismic cause"}, {"test": "CT head without contrast", "why": "Not routine; radiation exposure without benefit in typical cases"}, {"test": "cbc", "why": "No role in amblyopia"}, {"test": "bmp", "why": "No role in amblyopia"}, {"test": "crp", "why": "No role in amblyopia"}, {"test": "esr", "why": "No role in amblyopia"}, {"test": "tsh", "why": "No role in amblyopia"}, {"test": "b12", "why": "No role in amblyopia"}, {"test": "folate", "why": "No role in amblyopia"}], "decision_points": ["Any child with reduced acuity or interocular difference should have cycloplegic refraction before attributing vision loss to amblyopia", "Leukocoria, optic atrophy, nystagmus, or neurologic findings warrant urgent imaging and ophthalmology referral", "Amblyopia treatment is most effective before age 7–9; early detection and referral are critical"], "criteria": [], "scores": []}, "differential": [{"name": "Retinoblastoma", "slug": "retinoblastoma", "why_considered": "Reduced vision in one eye in a young child; a white pupil may be mistaken for a lazy eye", "must_not_miss": true, "trigger": "Leukocoria, a white pupillary reflex, or a family history of retinoblastoma", "discriminators": {"history": ["White or yellow pupil noticed in photos or by a caregiver", "Family history of retinoblastoma", "Eye turning in or out that appeared in the first year of life"], "exam": ["Leukocoria on red reflex testing", "Strabismus in an infant", "Possible orbital mass or proptosis in advanced disease"], "labs": ["Genetic testing for RB1 mutation when clinical suspicion is high"], "imaging": ["Intraocular mass with calcification on ocular ultrasound or MRI of the orbits", "Enhancing retinal mass on MRI"]}}, {"name": "Congenital cataract", "slug": "congenital-cataract", "why_considered": "Clouding of the lens causes reduced vision and can produce amblyopia if not treated early", "must_not_miss": true, "trigger": "An absent or asymmetric red reflex in a newborn or infant", "discriminators": {"history": ["Abnormal red reflex noted on newborn screening", "Family history of congenital cataract", "Maternal infection during pregnancy"], "exam": ["White or dull lens opacity seen through the pupil", "Absent or asymmetric red reflex", "Poor visual tracking in an infant"], "imaging": ["Lens opacity confirmed on slit-lamp or handheld examination", "Ocular ultrasound if the view is obscured"]}}, {"name": "Optic nerve glioma", "slug": "optic-nerve-glioma", "why_considered": "A tumor of the optic pathway can cause reduced vision in one eye in a child", "must_not_miss": true, "trigger": "Reduced vision with optic disc pallor, nystagmus, or signs of neurofibromatosis type 1", "discriminators": {"history": ["Progressive rather than stable vision loss", "Café-au-lait spots or family history of neurofibromatosis type 1", "Headaches or endocrine symptoms"], "exam": ["Optic disc pallor or swelling", "Afferent pupillary defect", "Proptosis or cranial nerve findings"], "imaging": ["Enlarged or enhancing optic nerve on MRI of the brain and orbits", "Chiasmal or hypothalamic involvement"]}}, {"name": "Strabismus", "slug": "strabismus", "why_considered": "Misaligned eyes are a leading cause of amblyopia and often the reason a child is referred", "must_not_miss": false, "discriminators": {"history": ["Eye turning in or out noticed by caregivers", "Squinting or closing one eye", "Family history of strabismus"], "exam": ["Manifest deviation on cover-uncover or alternate cover test", "Refixation movement when the fixating eye is covered", "Reduced acuity in the deviating eye if amblyopia has developed"]}}, {"name": "Anisometropia", "slug": "anisometropia", "why_considered": "Unequal refractive error between the eyes is a common cause of amblyopia and can present as reduced vision in one eye", "must_not_miss": false, "discriminators": {"history": ["No eye turn; vision is reduced in one eye only", "Child holds objects close or sits near the television", "Family history of childhood glasses use"], "exam": ["Reduced acuity in one eye that improves with corrective lenses", "Cycloplegic retinoscopy shows a significant difference between eyes", "Normal red reflex and fundus"]}}, {"name": "Refractive error", "slug": "refractive-error", "why_considered": "Nearsightedness, farsightedness, or astigmatism can reduce vision and be mistaken for amblyopia", "must_not_miss": false, "discriminators": {"history": ["Blurred vision at distance or near", "Squinting to see the board", "Symptoms improve with glasses"], "exam": ["Acuity corrects fully with refraction", "No interocular difference after correction", "Normal ocular alignment and fundus"]}}, {"name": "Cerebral visual impairment", "slug": "cerebral-visual-impairment", "why_considered": "Brain injury from prematurity, hypoxia, or seizures can cause reduced vision that is not explained by eye pathology", "must_not_miss": false, "discriminators": {"history": ["Prematurity, hypoxic-ischemic encephalopathy, or seizures", "Developmental delay", "Variable visual behavior"], "exam": ["Normal ocular structures with reduced vision", "Visual inattention or difficulty with crowded scenes", "Associated neurologic findings"], "imaging": ["Periventricular leukomalacia or other brain injury on MRI"]}}], "course": {"severity": {"mild": "Reduced acuity in one eye with a small interocular difference (about 2 lines) and a clear refractive or strabismic cause; responds well to glasses, patching, or atropine", "moderate": "Marked interocular difference (3 or more lines) or acuity worse than 20/40 in the amblyopic eye; requires several months of occlusion or atropine therapy", "severe": "Acuity 20/100 or worse in the amblyopic eye, dense deprivation from cataract or media opacity, or amblyopia that persists after initial therapy; may need surgery and prolonged treatment", "critical": "Not applicable; amblyopia itself is not a life-threatening condition"}, "red_flags": [{"finding": "Leukocoria or an absent red reflex", "meaning": "Suggests retinoblastoma, congenital cataract, or another serious intraocular cause; needs urgent ophthalmology evaluation"}, {"finding": "Optic disc pallor or swelling", "meaning": "Suggests optic nerve disease or increased intracranial pressure; requires urgent imaging"}, {"finding": "Afferent pupillary defect", "meaning": "Indicates optic nerve or severe retinal dysfunction; not typical of simple amblyopia"}, {"finding": "Nystagmus", "meaning": "Suggests bilateral visual pathway disease or neurologic disorder; needs urgent workup"}, {"finding": "Headaches that wake the child, vomiting, or focal neurologic deficits", "meaning": "Raises concern for an intracranial mass or hydrocephalus; requires urgent imaging"}, {"finding": "Progressive vision loss rather than stable reduced vision", "meaning": "Suggests an active organic cause such as tumor, inflammation, or retinal disease"}], "complications": [{"name": "Permanent visual impairment in the amblyopic eye", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Treatment started after age 7–9", "Poor adherence to patching or atropine", "Persistent interocular acuity difference"]}, {"name": "Loss of depth perception and stereoacuity", "timing": "late", "seriousness": "minor", "frequency": "common", "clues": ["Difficulty with sports or catching a ball", "Strabismus or anisometropia"]}, {"name": "Recurrence of amblyopia after treatment", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Stopping patching or atropine too early", "Return of the interocular acuity difference on follow-up"]}, {"name": "Blindness in the better eye from later injury or disease", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Trauma or disease affecting the previously good eye", "Sudden loss of vision in the non-amblyopic eye"]}], "special_populations": [{"population": "infants", "differences": "Cannot report vision problems; detected by abnormal red reflex, poor fixation, or a constant eye turn. Treatment must start early because the visual system is still developing."}, {"population": "children", "differences": "Most common age group; often found on routine screening. Treatment is most effective before age 7–9, and adherence to patching or atropine is a major determinant of outcome."}, {"population": "older_adults", "differences": "Amblyopia is usually lifelong from childhood; adults may present when the good eye develops cataract, macular degeneration, or other disease, unmasking longstanding reduced vision."}]}, "teaching": {"key_questions": [{"question": "Did the vision screening at school or the well-child visit show a problem in one eye?", "category": "hpi", "importance": "essential", "looking_for": "Abnormal screening result or an interocular difference in acuity, the usual way amblyopia is found"}, {"question": "Have you or anyone noticed one eye turning in or out?", "category": "hpi", "importance": "essential", "looking_for": "Strabismus, a leading cause of amblyopia"}, {"question": "Does your child squint, close one eye, or tilt or turn the head to see things?", "category": "associated", "importance": "important", "looking_for": "Compensatory behaviors suggesting reduced vision in one eye"}, {"question": "Does your child hold books very close, sit near the television, or have trouble seeing the board at school?", "category": "associated", "importance": "important", "looking_for": "Functional consequences of reduced vision"}, {"question": "Has your child ever had a white or cloudy pupil, or an abnormal red reflex noted on a checkup or in a photograph?", "category": "red_flag", "importance": "essential", "looking_for": "Leukocoria or media opacity suggesting cataract, retinoblastoma, or another serious cause"}, {"question": "Is the vision problem getting worse over time, or has it been stable?", "category": "hpi", "importance": "essential", "looking_for": "Progressive loss suggests an active organic cause rather than stable amblyopia"}, {"question": "Any headaches, morning vomiting, or problems with walking, balance, or weakness?", "category": "red_flag", "importance": "essential", "looking_for": "Signs of raised intracranial pressure or a neurologic lesion"}, {"question": "Was your child born early or with a low birth weight?", "category": "pmh", "importance": "important", "looking_for": "Prematurity or low birth weight, which raise the risk of amblyopia and cerebral visual impairment"}, {"question": "Has your child been diagnosed with any eye condition, or had eye surgery or eye trauma?", "category": "pmh", "importance": "important", "looking_for": "Cataract, ptosis, prior eye surgery, or injury that could cause deprivation amblyopia"}, {"question": "Does anyone in the family have amblyopia, a turned eye, or need for glasses in childhood?", "category": "family", "importance": "important", "looking_for": "Family history of amblyopia, strabismus, or childhood refractive error"}, {"question": "Does your child take any medications, and are there any medication allergies?", "category": "medications", "importance": "optional", "looking_for": "Medications or allergies that could affect treatment choices such as atropine"}, {"question": "Has your child had any recent fever, illness, or eye redness or discharge?", "category": "ros", "importance": "important", "looking_for": "Absent; present suggests infection or another acute cause rather than amblyopia"}], "accepted_names": ["Amblyopia", "Lazy eye", "Amblyopia (lazy eye)"], "reasoning_points": ["Reduced best-corrected visual acuity in one eye, or a two-or-more-line interocular difference, found on screening or examination", "A plausible amblyogenic cause: strabismus, anisometropia, high refractive error, or a media opacity such as cataract", "The eye appears structurally normal on examination, with a normal red reflex, pupils, and fundus", "Vision does not fully correct with refraction alone, distinguishing amblyopia from simple refractive error", "No red flags: no leukocoria, afferent pupillary defect, optic disc pallor or swelling, nystagmus, or neurologic findings", "The history is gradual and painless, without acute vision loss, eye pain, or systemic illness", "Age at presentation is consistent with a developmental visual disorder, typically detected between ages 3 and 6"], "difficulty": {"easy": ["Preschool child with an abnormal vision screening and a clear interocular acuity difference", "Visible eye turn (strabismus) with reduced acuity in the deviating eye", "Normal eye examination otherwise, with a normal red reflex and fundus", "Improves with glasses and patching or atropine"], "medium": ["No visible eye turn; reduced acuity found only on careful separate-eye testing", "Anisometropia detected on cycloplegic refraction as the underlying cause", "Child who does not complain because the good eye compensates", "Older child with trouble seeing the board mistaken for simple nearsightedness"], "hard": ["Preverbal infant with poor fixation or a constant eye turn and no reported symptoms", "Bilateral amblyopia from high refractive error in both eyes", "Deprivation amblyopia from a subtle cataract or ptosis with a mildly abnormal red reflex", "Reduced vision with optic disc pallor or nystagmus suggesting an alternative diagnosis such as optic pathway glioma or cerebral visual impairment", "Amblyopia unmasked in an adult when the good eye develops cataract or other disease"]}}}$rounds_kb$::jsonb)
