tial": [{"name": "Acute coronary syndrome (unstable angina or myocardial infarction)", "slug": "acute-coronary-syndrome", "why_considered": "Same underlying coronary disease; the key question is whether symptoms are stable or represent an acute plaque event", "must_not_miss": true, "trigger": "Pain at rest, new-onset severe pain, or a change in a previously stable pattern", "discriminators": {"history": ["Symptoms at rest or with minimal activity", "Crescendo pattern over hours to days", "Pain lasting more than 20 minutes", "Not relieved by rest or nitroglycerin"], "exam": ["Diaphoresis, pallor, distress", "New S3 or pulmonary crackles", "Hypotension or tachycardia"], "labs": ["Rising or falling high-sensitivity troponin", "Elevated BNP if heart failure develops"], "imaging": ["New regional wall motion abnormality on echocardiography", "ST depression or elevation on ECG"]}}, {"name": "Aortic dissection", "slug": "aortic-dissection", "why_considered": "Severe chest pain that can radiate to the back and mimic cardiac ischemia", "must_not_miss": true, "trigger": "Sudden severe tearing pain, pulse or blood pressure asymmetry, or a widened mediastinum", "discriminators": {"history": ["Abrupt onset, maximal at the start", "Tearing or ripping quality", "Migrating from chest to back or abdomen", "Marfan syndrome or known aortic aneurysm"], "exam": ["Blood pressure difference between arms", "Pulse deficit", "New aortic regurgitation murmur", "Focal neurologic deficit"], "labs": ["No single lab excludes it; troponin may be normal or mildly elevated"], "imaging": ["Widened mediastinum on chest x-ray", "Intimal flap on CT angiography or transesophageal echocardiography"]}}, {"name": "Pulmonary embolism", "slug": "pulmonary-embolism", "why_considered": "Chest discomfort with shortness of breath and tachycardia", "must_not_miss": true, "trigger": "Pleuritic pain, sudden dyspnea, or hypoxia with a clear chest", "discriminators": {"history": ["Sudden onset of dyspnea", "Recent surg