insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$aphasia$rounds_kb$, $rounds_kb$Aphasia$rounds_kb$, $rounds_kb$neurology$rounds_kb$, array[$rounds_kb$neurology$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$nervous$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "aphasia", "triage": {"name": "Aphasia", "case_suitable": true, "reason": "A language deficit that can be characterized by bedside interview and exam, with localization and stroke workup leading to the diagnosis.", "kind": "symptom", "category": "neurologic deficit", "organ_systems": ["nervous"], "primary_clerkship": "neurology", "secondary_clerkships": ["internalMedicine", "emergency"], "commonness": "common", "settings": ["inpatient", "emergency", "clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:15:42Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:26:18Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:26:28Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:26:42Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:26:52Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:27:00Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'ecg' to 'ECG'", "auto-repaired: workup: 'mri brain with diffusion-weighted imaging' was in ['initial', 'confirmatory'], kept ['initial']", "auto-repaired: workup: 'csf' was in ['initial', 'not_indicated'], kept ['not_indicated', 'initial']", "auto-repaired: workup: 'csf' was in ['initial', 'not_indicated'], kept ['not_indicated', 'initial']", "differential intracerebral-hemorrhage: no profile yet", "differential hypoglycemia: no profile yet", "differential delirium: no profile yet", "differential dysarthria: no profile yet", "differential primary-progressive-aphasia: no profile yet", "differential brain-tumor: no profile yet", "differential herpes-simplex-encephalitis: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 45, "typical_max": 85, "peak": "60–80", "possible_min": 0, "possible_max": 110}, "sex": "either", "demographics": ["Most common in middle-aged and older adults because stroke is the leading cause", "Can occur at any age when caused by head trauma, brain infection, or brain tumor", "Risk parallels that of stroke, so it is more common in populations with high rates of hypertension, diabetes, and vascular disease"], "risk_factors": [{"text": "Prior stroke or transient ischemic attack", "strength": "strong"}, {"text": "Hypertension", "strength": "strong"}, {"text": "Atrial fibrillation", "strength": "strong"}, {"text": "Diabetes mellitus", "strength": "moderate"}, {"text": "Hyperlipidemia", "strength": "moderate"}, {"text": "Tobacco smoking", "strength": "moderate"}, {"text": "Traumatic brain injury", "strength": "moderate"}, {"text": "Brain tumor or brain infection", "strength": "moderate"}, {"text": "Neurodegenerative disease such as Alzheimer disease or frontotemporal dementia", "strength": "moderate"}, {"text": "Left-handedness or atypical language dominance (changes which deficits appear)", "strength": "weak"}], "comorbidities": ["Hypertension", "Atrial fibrillation", "Diabetes mellitus", "Coronary artery disease", "Heart failure", "Dementia", "Prior stroke"], "family_history": ["Family history of stroke or early cardiovascular disease"], "social_history": ["Tobacco use", "Heavy alcohol use", "Sedentary lifestyle"], "exposures": [], "risk_medications": ["Anticoagulants (may increase risk of hemorrhagic stroke)", "Antiplatelet agents"]}, "presentation": {"chief_complaints": [{"text": "I can't get my words out", "frequency": "common"}, {"text": "I know what I want to say, but the words come out wrong", "frequency": "common"}, {"text": "I can't understand what people are saying to me", "frequency": "common"}, {"text": "My words get mixed up and I can't find the right one", "frequency": "common"}, {"text": "I can't read or write like I used to", "frequency": "sometimes"}, {"text": "My family says I'm not making sense when I talk", "frequency": "sometimes"}], "hpi": {"onset": "Sudden when caused by stroke or head injury; gradual over weeks to months when caused by a brain tumor or a progressive neurologic disease", "duration": "Acute onset within minutes to hours for vascular causes; insidious and progressive for tumor or neurodegenerative causes", "progression": "Often worst right after the event and then improves over weeks to months with therapy; may be stable or steadily worsen if the underlying cause is progressive", "location": "Not a bodily location; reflects damage to the language areas of the dominant hemisphere (usually the left side of the brain)", "radiation": "Not applicable", "quality": "Difficulty producing words, difficulty understanding language, or both; speech may be effortful and halting or fluent but nonsensical", "severity": "Varies from occasional word-finding trouble to loss of nearly all language ability", "timing": "Constant; may be more noticeable when tired, stressed, or in noisy settings", "aggravating": ["Fatigue", "Stress or anxiety", "Background noise or group conversations", "Being rushed to answer"], "relieving": ["Using gestures, pictures, or a communication device", "Having one person speak slowly and simply", "Writing or drawing instead of speaking"], "associated_symptoms": [{"text": "Trouble finding the right word", "frequency": "almost_always"}, {"text": "Weakness or clumsiness of the right arm, leg, or face", "frequency": "common"}, {"text": "Trouble reading or writing", "frequency": "common"}, {"text": "Frustration, irritability, or tearfulness when trying to communicate", "frequency": "common"}, {"text": "Numbness or tingling on one side of the body", "frequency": "sometimes"}, {"text": "Vision changes such as loss of part of the visual field", "frequency": "sometimes"}, {"text": "Trouble swallowing", "frequency": "sometimes"}, {"text": "Confusion or memory problems", "frequency": "sometimes"}, {"text": "Severe headache at onset", "frequency": "rare"}], "pertinent_negatives": ["Loss of consciousness at onset", "Fever or stiff neck before the speech problem", "Recent head trauma", "Progressive memory loss as the first and main problem", "Hearing loss that predates the speech problem", "Weakness that comes and goes in minutes and resolves completely", "Speech difficulty only when anxious or in social situations"]}, "ros": [{"system": "neurologic", "positives": [{"text": "Difficulty producing or understanding language", "frequency": "almost_always"}, {"text": "Right-sided weakness or clumsiness", "frequency": "common"}, {"text": "Right-sided numbness or tingling", "frequency": "sometimes"}, {"text": "Visual field loss", "frequency": "sometimes"}, {"text": "Trouble swallowing", "frequency": "sometimes"}], "negatives": ["Loss of consciousness", "New seizure activity", "Severe headache", "Neck stiffness", "Progressive memory loss as the main problem"], "argues_against": ["Delirium from a toxic or metabolic cause", "Primary dementia"]}, {"system": "psychiatric", "positives": [{"text": "Frustration or irritability when unable to communicate", "frequency": "common"}, {"text": "Low mood or tearfulness", "frequency": "sometimes"}], "negatives": ["Auditory hallucinations", "Delusions", "Manic symptoms"], "argues_against": ["Primary psychotic disorder"]}, {"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "sometimes"}], "negatives": ["Fever", "Unintentional weight loss", "Night sweats"], "argues_against": ["Brain infection", "Systemic illness causing delirium"]}, {"system": "ent", "positives": [], "negatives": ["Hearing loss", "Ear pain", "Tinnitus"], "argues_against": ["Peripheral hearing loss as the cause of communication difficulty"]}], "atypical": [{"population": "children", "how_it_differs": "Aphasia is uncommon in children and usually follows head trauma, infection, or a seizure disorder rather than stroke; it may be mistaken for a developmental language delay or for stuttering.", "missing_classic_features": ["Sudden onset from stroke", "Vascular risk factors"]}, {"population": "older_adults", "how_it_differs": "Language deficits may be attributed to dementia or hearing loss, and coexisting cognitive decline can make the aphasia harder to recognize and characterize.", "missing_classic_features": ["Clear sudden onset", "Isolated language deficit without memory problems"]}, {"population": "immunocompromised", "how_it_differs": "Brain infection or abscess is a more likely cause than in other adults, so fever, headache, and focal neurologic signs may accompany the language problem.", "missing_classic_features": ["Typical stroke risk profile", "Absence of infectious symptoms"]}]}, "exam": {"general": {"mild": "Alert, cooperative, and fully interactive; may pause or search for words but communicates effectively with circumlocution", "moderate": "Alert and interactive but noticeably effortful or tangential speech; may need repetition or simplified questions to participate in the exam", "severe": "Alert but communication is markedly limited; may follow only simple one-step commands and relies on gestures or yes/no responses", "critical": "Minimally interactive; little or no meaningful verbal output and inconsistent command following, with exam limited to observation and simple stimuli"}, "findings": [{"id": "spontaneous-speech-fluency", "region": "mental_status", "maneuver": "Ask the patient to describe their day or a familiar picture, and listen to the flow, effort, and grammar of speech", "finding": "Speech that is effortful and halting with sparse output (nonfluent) or fluent but empty and paraphasic (fluent)", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "confrontation-naming", "region": "mental_status", "maneuver": "Show common objects (watch, pen, keys) and ask the patient to name each one", "finding": "Inability to name objects, with circumlocution, wrong words, or made-up words", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "auditory-comprehension", "region": "mental_status", "maneuver": "Ask the patient to follow simple then multi-step spoken commands (for example, 'close your eyes', then 'point to the ceiling, then touch your nose')", "finding": "Difficulty following commands despite adequate hearing and attention", "frequency": "common", "significance": "strongly_supports", "importance": "essential"}, {"id": "repetition", "region": "mental_status", "maneuver": "Ask the patient to repeat a short phrase and then a longer sentence", "finding": "Impaired repetition of words or sentences", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "reading-aloud", "region": "mental_status", "maneuver": "Ask the patient to read a short sentence aloud and then explain what it means", "finding": "Difficulty reading aloud or understanding written words", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "writing-sample", "region": "mental_status", "maneuver": "Ask the patient to write their name and a short sentence", "finding": "Misspelled, agrammatic, or unintelligible writing", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "orientation", "region": "mental_status", "maneuver": "Ask the patient their name, where they are, and the date", "finding": "Oriented to person, place, and time", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "attention-serial-sevens", "region": "mental_status", "maneuver": "Ask the patient to count backward from 20 by 1s or to spell a short word backward", "finding": "Attention and working memory intact for the patient's age", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "facial-weakness", "region": "neuro", "maneuver": "Ask the patient to smile, show teeth, and close eyes tightly", "finding": "Lower facial droop on the right", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "right-arm-drift", "region": "neuro", "maneuver": "Have the patient hold both arms out with eyes closed for 10 seconds", "finding": "Downward drift or weakness of the right arm", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "right-leg-weakness", "region": "neuro", "maneuver": "Test strength of hip flexion and knee extension on both sides", "finding": "Weakness of the right leg", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "right-sided-sensory-loss", "region": "neuro", "maneuver": "Test light touch and pinprick on both arms and legs", "finding": "Reduced sensation on the right side of the body", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "homonymous-hemianopia", "region": "neuro", "maneuver": "Test visual fields by confrontation in all four quadrants", "finding": "Loss of the right visual field in both eyes", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "dysarthria-absent", "region": "neuro", "maneuver": "Listen to the clarity of articulation during speech and ask the patient to say 'pa-ta-ka'", "finding": "Articulation is clear; errors are in word choice and sentence construction rather than in the mechanical production of sounds", "frequency": "common", "significance": "argues_against", "importance": "important"}, {"id": "cranial-nerve-exam", "region": "heent", "maneuver": "Examine pupils, extraocular movements, facial sensation, and hearing", "finding": "Cranial nerves II, III, IV, VI, and VIII are intact; hearing is adequate for conversational speech", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "gag-and-swallow", "region": "heent", "maneuver": "Observe a sip of water and check the gag reflex", "finding": "Swallowing is safe with no coughing or choking", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "no-meningismus", "region": "neck", "maneuver": "Check for neck stiffness and perform Brudzinski and Kernig maneuvers", "finding": "No neck stiffness or meningeal signs", "frequency": "almost_always", "significance": "argues_against", "importance": "important"}, {"id": "no-tremor-or-bradykinesia", "region": "extremities", "maneuver": "Observe for rest tremor and test finger tapping and rapid alternating movements", "finding": "No rest tremor, rigidity, or bradykinesia", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "no-cerebellar-signs", "region": "neuro", "maneuver": "Test finger-to-nose, heel-to-shin, and rapid alternating movements", "finding": "No limb ataxia or dysmetria", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "no-asterixis", "region": "extremities", "maneuver": "Ask the patient to hold both arms extended with wrists dorsiflexed for 30 seconds", "finding": "No flapping tremor of the wrists", "frequency": "almost_always", "significance": "argues_against", "importance": "optional"}, {"id": "no-fever-or-rash", "region": "skin", "maneuver": "Inspect the skin and check temperature by touch", "finding": "No rash, petechiae, or warmth suggesting infection", "frequency": "almost_always", "significance": "argues_against", "importance": "optional"}]}, "vitals": {"temp": {"mild": {"min": 97.8, "max": 99.1}, "moderate": {"min": 98.0, "max": 99.5}, "severe": {"min": 98.2, "max": 100.0}, "critical": {"min": 98.0, "max": 100.4}}, "hr": {"mild": {"min": 60, "max": 100}, "moderate": {"min": 65, "max": 110}, "severe": {"min": 70, "max": 120}, "critical": {"min": 80, "max": 140}}, "rr": {"mild": {"min": 12, "max": 20}, "moderate": {"min": 14, "max": 22}, "severe": {"min": 16, "max": 26}, "critical": {"min": 18, "max": 30}}, "sbp": {"mild": {"min": 110, "max": 150}, "moderate": {"min": 120, "max": 170}, "severe": {"min": 130, "max": 190}, "critical": {"min": 90, "max": 220}}, "dbp": {"mild": {"min": 70, "max": 95}, "moderate": {"min": 75, "max": 105}, "severe": {"min": 80, "max": 115}, "critical": {"min": 55, "max": 130}}, "spo2": {"mild": {"min": 95, "max": 100}, "moderate": {"min": 94, "max": 100}, "severe": {"min": 92, "max": 99}, "critical": {"min": 88, "max": 98}}}, "labs": [{"test_id": "glucose", "ranges": {"moderate": {"min": 100, "max": 180}, "severe": {"min": 180, "max": 400}, "critical": {"min": 40, "max": 600}}, "frequency": "common", "importance": "essential", "caveat": "Both hyperglycemia and hypoglycemia can cause focal deficits and altered language; a point-of-care glucose is checked before any imaging in a suspected stroke."}, {"test_id": "a1c", "ranges": {"moderate": {"min": 5.7, "max": 6.4}, "severe": {"min": 6.5, "max": 12.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Reflects chronic glycemic control and vascular risk; not part of the acute stroke decision."}, {"test_id": "inr", "ranges": {"moderate": {"min": 1.2, "max": 1.5}, "severe": {"min": 1.6, "max": 3.0}, "critical": {"min": 3.1, "max": 8.0}}, "frequency": "common", "importance": "essential", "caveat": "An elevated INR raises the chance of hemorrhagic stroke and must be known before thrombolysis; a normal INR does not exclude it."}, {"test_id": "aptt", "ranges": {"severe": {"min": 36, "max": 60}, "critical": {"min": 61, "max": 120}}, "frequency": "sometimes", "importance": "important", "caveat": "Prolonged by heparin or a coagulopathy; relevant when bleeding is a consideration."}, {"test_id": "plt", "ranges": {"severe": {"min": 80, "max": 140}, "critical": {"min": 10, "max": 79}}, "frequency": "sometimes", "importance": "important", "caveat": "Thrombocytopenia increases hemorrhagic risk and is a contraindication to thrombolysis."}, {"test_id": "wbc", "ranges": {"moderate": {"min": 11.5, "max": 16.0}, "severe": {"min": 16.1, "max": 25.0}, "critical": {"min": 25.1, "max": 40.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Mild leukocytosis is common after acute stroke; marked elevation or a left shift suggests infection such as meningitis or encephalitis."}, {"test_id": "cr", "ranges": {"moderate": {"min": 1.4, "max": 2.0}, "severe": {"min": 2.1, "max": 4.0}, "critical": {"min": 4.1, "max": 10.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Needed before contrast CT angiography and to gauge renal reserve; chronic elevation is common in this population."}, {"test_id": "na", "ranges": {"moderate": {"min": 125, "max": 134}, "severe": {"min": 115, "max": 124}, "critical": {"min": 100, "max": 114}}, "frequency": "sometimes", "importance": "important", "caveat": "Hyponatremia can cause confusion and focal deficits that mimic aphasia; correct slowly."}, {"test_id": "ammonia", "ranges": {"moderate": {"min": 46, "max": 80}, "severe": {"min": 81, "max": 150}, "critical": {"min": 151, "max": 300}}, "frequency": "rare", "importance": "optional", "caveat": "Consider when hepatic encephalopathy is suspected as a cause of altered language and attention."}, {"test_id": "tsh", "ranges": {"moderate": {"min": 4.1, "max": 10.0}, "severe": {"min": 10.1, "max": 50.0}}, "frequency": "rare", "importance": "optional", "caveat": "Thyroid disease can contribute to confusion but rarely causes isolated aphasia."}, {"test_id": "csf_wbc", "ranges": {"moderate": {"min": 6, "max": 100}, "severe": {"min": 101, "max": 1000}, "critical": {"min": 1001, "max": 10000}}, "frequency": "rare", "importance": "important", "caveat": "Only when infection or inflammation is suspected; a pleocytosis supports meningitis or encephalitis rather than stroke."}, {"test_id": "csf_protein", "ranges": {"moderate": {"min": 46, "max": 100}, "severe": {"min": 101, "max": 300}, "critical": {"min": 301, "max": 1000}}, "frequency": "rare", "importance": "optional", "caveat": "Elevated in central nervous system infection or inflammation."}, {"test_id": "csf_glucose", "ranges": {"moderate": {"min": 30, "max": 39}, "severe": {"min": 10, "max": 29}}, "frequency": "rare", "importance": "optional", "caveat": "Low values suggest bacterial or fungal meningitis."}], "ecg": {"findings": [{"feature": "rhythm", "finding": "Irregularly irregular rhythm without distinct P waves, consistent with atrial fibrillation", "frequency": "common", "min_severity": "moderate"}, {"feature": "rhythm", "finding": "Sinus rhythm", "frequency": "common"}, {"feature": "st", "finding": "ST elevation in a territorial distribution suggesting acute myocardial infarction as the embolic source", "frequency": "rare", "leads": ["II", "III", "aVF", "V1", "V2", "V3", "V4", "V5", "V6"], "min_severity": "severe"}, {"feature": "other", "finding": "Left ventricular hypertrophy or other evidence of hypertensive heart disease", "frequency": "sometimes", "min_severity": "moderate"}]}, "imaging": [{"study": "Noncontrast CT head", "modality": "ct", "preferred_when": "First-line in the emergency setting for any sudden language deficit", "findings": [{"text": "No acute hemorrhage", "frequency": "common"}, {"text": "Hypodensity in the left frontal or temporal lobe in the territory of the middle cerebral artery", "frequency": "sometimes"}, {"text": "Hyperdense middle cerebral artery sign", "frequency": "sometimes"}, {"text": "Intraparenchymal hemorrhage in the dominant hemisphere", "frequency": "rare"}, {"text": "Mass with surrounding edema and midline shift", "frequency": "rare"}, {"text": "Hypodense old infarct or white matter chronic microangiopathic changes", "frequency": "common"}]}, {"study": "MRI brain with diffusion-weighted imaging", "modality": "mri", "preferred_when": "When CT is nondiagnostic or a small or posterior lesion is suspected", "findings": [{"text": "Restricted diffusion in the left inferior frontal gyrus (Broca area) or posterior superior temporal gyrus (Wernicke area)", "frequency": "common"}, {"text": "Acute infarct in the territory of the left middle cerebral artery", "frequency": "common"}, {"text": "Small cortical or subcortical infarct not seen on CT", "frequency": "sometimes"}, {"text": "Enhancing mass or ring-enhancing lesion suggesting tumor or abscess", "frequency": "rare"}, {"text": "Periventricular and cortical atrophy consistent with a neurodegenerative process", "frequency": "sometimes"}]}, {"study": "CT angiography of the head and neck", "modality": "ct", "preferred_when": "When large-vessel occlusion is suspected and the patient may be a candidate for thrombectomy", "findings": [{"text": "Occlusion of the left middle cerebral artery or internal carotid artery", "frequency": "sometimes"}, {"text": "Atherosclerotic stenosis of the cervical carotid arteries", "frequency": "sometimes"}, {"text": "No large-vessel occlusion", "frequency": "common"}]}, {"study": "Carotid duplex ultrasound", "modality": "ultrasound", "preferred_when": "Screening for carotid stenosis after a transient ischemic attack or minor stroke", "findings": [{"text": "Hemodynamically significant stenosis at the carotid bifurcation", "frequency": "sometimes"}, {"text": "No significant stenosis", "frequency": "common"}]}, {"study": "Echocardiogram", "modality": "echo", "preferred_when": "When a cardioembolic source is suspected", "findings": [{"text": "Left atrial enlargement or thrombus with spontaneous echo contrast", "frequency": "sometimes"}, {"text": "Reduced left ventricular ejection fraction with mural thrombus", "frequency": "sometimes"}, {"text": "Valvular vegetation suggesting endocarditis", "frequency": "rare"}, {"text": "Normal study", "frequency": "common"}]}, {"study": "EEG", "modality": "other", "preferred_when": "When seizures or nonconvulsive status epilepticus are suspected", "findings": [{"text": "Epileptiform discharges or electrographic seizures over the dominant temporal lobe", "frequency": "sometimes"}, {"text": "Diffuse or focal slowing", "frequency": "common"}, {"text": "Normal background activity", "frequency": "common"}]}, {"study": "Chest x-ray", "modality": "xray", "findings": [{"text": "Usually normal; may show cardiomegaly or pulmonary vascular congestion", "frequency": "common"}]}], "workup": {"initial": [{"test": "glucose", "why": "Bedside glucose is checked immediately because hypoglycemia and severe hyperglycemia can mimic a stroke and are rapidly reversible"}, {"test": "cbc", "why": "Baseline blood counts and to look for infection or thrombocytopenia"}, {"test": "bmp", "why": "Electrolytes, renal function, and glucose before contrast imaging"}, {"test": "pt", "why": "Coagulation status before considering thrombolysis"}, {"test": "inr", "why": "Coagulation status before considering thrombolysis"}, {"test": "aptt", "why": "Coagulation status before considering thrombolysis"}, {"test": "ECG", "why": "Looks for atrial fibrillation or acute myocardial infarction as the embolic source"}, {"test": "Noncontrast CT head", "why": "First-line to exclude hemorrhage and identify a large infarct or mass"}, {"test": "CT angiography of the head and neck", "why": "Identifies large-vessel occlusion when thrombectomy is being considered", "only_if": "the patient may be a candidate for endovascular therapy"}, {"test": "MRI brain with diffusion-weighted imaging", "why": "Most sensitive for acute infarct and for small or posterior lesions", "only_if": "CT is nondiagnostic or the deficit is unexplained"}, {"test": "csf", "why": "Cell count, protein, and glucose when central nervous system infection or inflammation is suspected", "only_if": "fever, headache, meningismus, or immunocompromise is present"}], "confirmatory": [{"test": "Speech-language evaluation", "why": "Formal bedside or standardized testing by a speech-language pathologist characterizes the aphasia type and severity"}], "supporting": [{"test": "a1c", "why": "Assesses chronic glycemic control and vascular risk"}, {"test": "lipids", "why": "Cardiovascular risk profile for secondary prevention"}, {"test": "tsh", "why": "Screens for thyroid disease that can contribute to cognitive change"}, {"test": "Echocardiogram", "why": "Looks for a cardioembolic source such as atrial thrombus or valvular disease", "only_if": "a cardioembolic source is suspected or the stroke is cryptogenic"}, {"test": "Carotid duplex ultrasound", "why": "Screens for carotid stenosis after a transient ischemic attack or minor stroke", "only_if": "the event is in the anterior circulation and the patient is a potential revascularization candidate"}, {"test": "EEG", "why": "Evaluates for seizures or nonconvulsive status epilepticus", "only_if": "seizure activity or fluctuating language deficits are suspected"}], "not_indicated": [{"test": "Chest x-ray", "why": "Not routinely needed for an isolated language deficit"}, {"test": "ua", "why": "No role in the workup of aphasia unless a urinary infection is suspected as a cause of delirium"}, {"test": "d_dimer", "why": "Not useful for diagnosing stroke or aphasia"}, {"test": "lipase", "why": "Not relevant to a language deficit"}, {"test": "ammonia", "why": "Only when hepatic encephalopathy is suspected, not routinely"}, {"test": "csf", "why": "Not routine; reserved for suspected infection or inflammation", "only_if": "central nervous system 