insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$bipolar-disorder$rounds_kb$, $rounds_kb$Bipolar Disorder$rounds_kb$, $rounds_kb$psychiatry$rounds_kb$, array[$rounds_kb$psychiatry$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$behavioral$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "bipolar-disorder", "triage": {"name": "Bipolar Disorder", "case_suitable": true, "reason": "Major psychiatric illness with manic or depressive episodes; diagnosis by careful history of mood episodes, sleep and function, with strong safety and differential teaching.", "kind": "disease", "category": "mood disorder", "organ_systems": ["behavioral"], "primary_clerkship": "psychiatry", "secondary_clerkships": ["familyMedicine", "internalMedicine", "emergency"], "commonness": "common", "settings": ["psychiatric", "inpatient", "clinic", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:15:53Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:29:14Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:29:20Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:29:30Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:29:41Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:29:49Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'ua_tox' to 'Ua tox'", "auto-repaired: workup: renamed 'csf_analysis' to 'Csf analysis'", "auto-repaired: workup: renamed 'eeg' to 'EEG'", "auto-repaired: labs: dropped 'ua_tox' (not in the reference table)", "differential major-depressive-disorder: no profile yet", "differential substance-induced-mood-disorder: no profile yet", "differential schizophrenia: no profile yet", "differential schizoaffective-disorder: no profile yet", "differential hyperthyroidism: no profile yet", "differential borderline-personality-disorder: no profile yet", "differential cushing-syndrome: no profile yet", "differential delirium: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 15, "typical_max": 35, "peak": "late teens to mid-20s", "possible_min": 6, "possible_max": 90}, "sex": "either", "demographics": ["Affects men and women at roughly equal rates", "Onset is typically in late adolescence or early adulthood", "Bipolar I disorder tends to present at a slightly younger age and with more manic episodes in men", "Bipolar II disorder with prominent depression and hypomania is diagnosed more often in women", "More than one in four first episodes occur after age 50"], "risk_factors": [{"text": "First-degree relative with bipolar disorder", "strength": "strong"}, {"text": "Prior manic or hypomanic episode", "strength": "strong"}, {"text": "Major depressive episodes, especially early onset or postpartum", "strength": "moderate"}, {"text": "Childhood trauma or major stressful life events", "strength": "moderate"}, {"text": "Substance use, particularly stimulants or cannabis", "strength": "moderate"}, {"text": "Antidepressant treatment that triggers mania or hypomania", "strength": "moderate"}, {"text": "Disrupted circadian rhythm or sleep deprivation", "strength": "weak"}], "comorbidities": ["Anxiety disorders", "Substance use disorders", "Attention-deficit/hyperactivity disorder", "Migraine", "Metabolic syndrome and type 2 diabetes", "Thyroid disease"], "family_history": ["Bipolar disorder in a first-degree relative", "Major depressive disorder in a first-degree relative", "Psychotic disorders in a first-degree relative", "Suicide in a first-degree relative"], "social_history": ["Recent major life stressor or loss", "Irregular sleep schedule or shift work", "Heavy alcohol or drug use", "Recent childbirth"], "exposures": [], "risk_medications": ["corticosteroids", "levothyroxine", "bupropion", "fluoxetine", "sertraline", "venlafaxine", "amphetamine", "methylphenidate", "prednisone"]}, "presentation": {"chief_complaints": [{"text": "I go from feeling on top of the world to not being able to get out of bed", "frequency": "common"}, {"text": "My family says I've been acting completely different", "frequency": "common"}, {"text": "I haven't slept in days and I feel like I don't need to", "frequency": "common"}, {"text": "I feel worthless and can't do anything", "frequency": "common"}, {"text": "My thoughts are racing and I can't slow down", "frequency": "sometimes"}, {"text": "I spent money I don't have and can't explain why", "frequency": "sometimes"}], "hpi": {"onset": "Episodic mood changes beginning in late adolescence or early adulthood; a first episode may be manic, hypomanic, mixed, or depressive", "duration": "Manic episodes last at least a week (or require hospitalization); hypomanic episodes last at least 4 days; depressive episodes typically last at least 2 weeks; episodes recur over a lifetime", "progression": "Discrete episodes of elevated, irritable, or depressed mood separated by periods of normal mood; episode frequency and severity vary, and some patients cycle rapidly with four or more episodes per year", "location": "", "radiation": "", "quality": "Distinct periods of abnormally elevated, expansive, or irritable mood with increased energy, alternating with periods of low mood, anhedonia, and low energy", "severity": "Ranges from mild hypomania that others notice but the patient may not, to severe mania with psychosis or dangerous behavior, and to major depression with suicidal thinking", "timing": "Symptoms occur most of the day, nearly every day, during an episode; mood and energy are often worse in the morning during depression and sleep need is markedly reduced during mania", "aggravating": ["Sleep deprivation", "Substance use", "Major life stressors", "Antidepressant medications", "Seasonal changes"], "relieving": ["Mood stabilizers", "Consistent sleep schedule", "Psychotherapy", "Reduced stimulation during mania"], "associated_symptoms": [{"text": "Decreased need for sleep", "frequency": "almost_always"}, {"text": "Increased energy or activity", "frequency": "almost_always"}, {"text": "Racing thoughts or rapid speech", "frequency": "common"}, {"text": "Irritability or short temper", "frequency": "common"}, {"text": "Grandiosity or inflated self-esteem", "frequency": "common"}, {"text": "Impulsive or risky behavior such as spending, sex, or driving", "frequency": "common"}, {"text": "Depressed mood, hopelessness, or worthlessness", "frequency": "common"}, {"text": "Loss of interest or pleasure in usual activities", "frequency": "common"}, {"text": "Fatigue or low energy", "frequency": "common"}, {"text": "Appetite or weight change", "frequency": "common"}, {"text": "Difficulty concentrating or making decisions", "frequency": "common"}, {"text": "Suicidal thoughts", "frequency": "sometimes"}, {"text": "Psychotic symptoms such as delusions or hallucinations", "frequency": "sometimes"}, {"text": "Anxiety or panic", "frequency": "sometimes"}], "pertinent_negatives": ["Symptoms only during substance use or withdrawal", "Mood elevation only while taking an antidepressant", "Continuous depressed mood for more than two years without elevated episodes", "No discrete episodes, with mood symptoms that are chronic and stable", "Medical cause of mood change such as thyroid disease or steroid use", "Delusions or hallucinations lasting more than two weeks without mood symptoms"]}, "ros": [{"system": "psychiatric", "positives": [{"text": "Elevated, expansive, or irritable mood", "frequency": "almost_always"}, {"text": "Racing thoughts", "frequency": "common"}, {"text": "Grandiosity", "frequency": "common"}, {"text": "Depressed mood or anhedonia", "frequency": "common"}, {"text": "Suicidal ideation", "frequency": "sometimes"}, {"text": "Psychosis", "frequency": "sometimes"}], "negatives": ["Auditory hallucinations commenting on behavior", "Delusions of being controlled", "Symptoms present only when intoxicated"], "argues_against": ["Schizophrenia", "Substance-induced mood disorder"]}, {"system": "constitutional", "positives": [{"text": "Decreased need for sleep", "frequency": "almost_always"}, {"text": "Increased energy", "frequency": "almost_always"}, {"text": "Fatigue during depression", "frequency": "common"}, {"text": "Appetite or weight change", "frequency": "common"}], "negatives": ["Fever", "Night sweats", "Unintentional weight loss"], "argues_against": ["Hyperthyroidism", "Occult malignancy"]}, {"system": "neurologic", "positives": [{"text": "Difficulty concentrating", "frequency": "common"}, {"text": "Racing thoughts", "frequency": "common"}], "negatives": ["Focal weakness", "Seizures", "Headache", "Vision changes"], "argues_against": ["Delirium", "Structural brain lesion"]}, {"system": "endocrine", "positives": [], "negatives": ["Heat intolerance", "Tremor", "Cold intolerance", "Polyuria"], "argues_against": ["Thyroid disease", "Diabetes"]}, {"system": "gastrointestinal", "positives": [], "negatives": ["Nausea", "Vomiting", "Abdominal pain", "Diarrhea"], "argues_against": ["Substance withdrawal", "Gastrointestinal illness"]}], "atypical": [{"population": "children", "how_it_differs": "Children may present with irritability, rapid mood shifts, and behavioral problems rather than clear episodes; mania can look like severe ADHD or oppositional behavior.", "missing_classic_features": ["Clear discrete episodes", "Grandiosity described as unusual for age"]}, {"population": "older_adults", "how_it_differs": "First episodes after age 50 are less common and more often present with depression or confusion; mania may be mistaken for dementia or delirium, and medical causes and medications must be excluded.", "missing_classic_features": ["Early-onset course", "Prominent elevated mood"]}, {"population": "pregnancy", "how_it_differs": "Mood episodes may occur during pregnancy or postpartum; postpartum psychosis is a psychiatric emergency, and medication decisions must weigh fetal and breastfeeding risks.", "missing_classic_features": ["Typical pre-pregnancy pattern"]}]}, "exam": {"general": {"mild": "Well-groomed, talkative, mildly elevated mood or mild psychomotor slowing; no distress", "moderate": "Pressured speech, restless or slowed movement, irritable or tearful, disheveled at times", "severe": "Markedly elevated or depressed, poor attention, disorganized or agitated, may require redirection", "critical": "Acutely agitated or catatonic, unable to cooperate with exam, risk of harm to self or others"}, "findings": [{"id": "elevated-mood", "region": "mental_status", "maneuver": "Ask the patient to describe their mood over the past week", "finding": "Reports feeling unusually high, elated, expansive, or extremely irritable", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "pressured-speech", "region": "mental_status", "maneuver": "Observe the rate, volume, and pressure of speech during the interview", "finding": "Rapid, loud, difficult-to-interrupt speech", "frequency": "common", "min_severity": "moderate", "significance": "strongly_supports", "importance": "essential"}, {"id": "flight-of-ideas", "region": "mental_status", "maneuver": "Ask an open-ended question and follow the patient's train of thought", "finding": "Thoughts jump rapidly from one topic to another with only loose connections", "frequency": "common", "min_severity": "moderate", "significance": "strongly_supports", "importance": "important"}, {"id": "grandiosity", "region": "mental_status", "maneuver": "Ask about self-perception, abilities, and plans", "finding": "Inflated self-esteem or grandiose beliefs out of proportion to reality", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "decreased-sleep-need", "region": "general", "maneuver": "Ask how many hours the patient sleeps and whether they feel rested", "finding": "Sleeps only a few hours but reports feeling rested and energetic", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "psychomotor-agitation", "region": "general", "maneuver": "Observe the patient's activity level and ability to sit still", "finding": "Restless, pacing, unable to remain seated", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "depressed-mood", "region": "mental_status", "maneuver": "Ask about sadness, hopelessness, and loss of interest", "finding": "Depressed mood, tearfulness, or anhedonia", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "psychomotor-retardation", "region": "general", "maneuver": "Observe movement and speech speed during the interview", "finding": "Slowed movement, long pauses before answering, soft monotonous speech", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "suicidal-ideation", "region": "mental_status", "maneuver": "Ask directly about thoughts of death, self-harm, or suicide", "finding": "Expresses suicidal thoughts or a plan", "frequency": "sometimes", "significance": "strongly_supports", "importance": "essential"}, {"id": "psychosis", "region": "mental_status", "maneuver": "Ask about hearing voices or unusual beliefs; assess reality testing", "finding": "Auditory hallucinations or mood-congruent delusions", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "catatonia", "region": "mental_status", "maneuver": "Observe for immobility, mutism, posturing, or negativism", "finding": "Decreased responsiveness, posturing, or waxy flexibility", "frequency": "rare", "min_severity": "critical", "significance": "strongly_supports", "importance": "important"}, {"id": "oriented", "region": "mental_status", "maneuver": "Ask person, place, and time", "finding": "Alert and fully oriented", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-neuro", "region": "neuro", "maneuver": "Perform a focused neurologic exam including cranial nerves, strength, and reflexes", "finding": "No focal deficits, tremor, or abnormal reflexes", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-thyroid-abnormalities", "region": "neck", "maneuver": "Palpate the thyroid and inspect for goiter or eye signs", "finding": "No goiter, lid lag, or proptosis", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-heart-lungs", "region": "cardiac", "maneuver": "Auscultate the heart and lungs", "finding": "Regular rate and rhythm, no murmurs, clear lungs", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {"temp": {"critical": {"min": 99.0, "max": 101.0}}, "hr": {"moderate": {"min": 90, "max": 110}, "severe": {"min": 100, "max": 120}, "critical": {"min": 110, "max": 140}}, "sbp": {"moderate": {"min": 130, "max": 150}, "severe": {"min": 140, "max": 160}, "critical": {"min": 150, "max": 180}}, "dbp": {"moderate": {"min": 80, "max": 95}, "severe": {"min": 85, "max": 100}, "critical": {"min": 90, "max": 110}}}, "labs": [{"test_id": "tsh", "ranges": {"mild": {"min": 0.01, "max": 0.4}, "moderate": {"min": 0.01, "max": 0.2}, "severe": {"min": 0.01, "max": 0.1}}, "frequency": "sometimes", "importance": "essential", "caveat": "Low TSH with elevated free T4 suggests hyperthyroidism, which can mimic mania; a normal TSH makes thyroid disease unlikely."}, {"test_id": "ft4", "ranges": {"mild": {"min": 1.9, "max": 2.5}, "moderate": {"min": 2.0, "max": 3.0}, "severe": {"min": 2.2, "max": 3.5}}, "frequency": "sometimes", "importance": "important", "caveat": "Elevated free T4 with suppressed TSH supports hyperthyroidism rather than bipolar disorder."}, {"test_id": "hcg", "frequency": "sometimes", "importance": "important", "caveat": "Positive in pregnancy; pregnancy and postpartum period affect mood and medication choices. Not a cause of mania but must be known before treatment."}, {"test_id": "glucose", "ranges": {"mild": {"min": 100, "max": 125}, "moderate": {"min": 126, "max": 180}, "severe": {"min": 180, "max": 300}}, "frequency": "sometimes", "importance": "optional", "caveat": "Hyperglycemia may reflect metabolic syndrome or diabetes, common comorbidities and relevant to medication selection."}, {"test_id": "a1c", "ranges": {"mild": {"min": 5.7, "max": 6.4}, "moderate": {"min": 6.5, "max": 8.0}, "severe": {"min": 8.0, "max": 10.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Elevated A1c supports diabetes or prediabetes, which affects choice of mood stabilizer."}, {"test_id": "cr", "ranges": {"mild": {"min": 1.2, "max": 1.5}, "moderate": {"min": 1.5, "max": 2.0}, "severe": {"min": 2.0, "max": 3.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Elevated creatinine indicates renal impairment, which affects dosing of lithium and other medications."}, {"test_id": "ca", "ranges": {"mild": {"min": 10.3, "max": 11.0}, "moderate": {"min": 11.0, "max": 12.0}, "severe": {"min": 12.0, "max": 14.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Hypercalcemia can cause mood changes, confusion, and lethargy that mimic psychiatric illness."}, {"test_id": "cortisol_am", "ranges": {"mild": {"min": 26, "max": 35}, "moderate": {"min": 35, "max": 50}, "severe": {"min": 50, "max": 80}}, "frequency": "rare", "importance": "optional", "caveat": "Elevated morning cortisol suggests Cushing syndrome, which can present with depression, mania, or psychosis."}, {"test_id": "b12", "ranges": {"mild": {"min": 150, "max": 199}, "moderate": {"min": 100, "max": 149}, "severe": {"min": 50, "max": 99}}, "frequency": "sometimes", "importance": "optional", "caveat": "Low B12 can cause mood and cognitive symptoms; replace if deficient."}, {"test_id": "folate", "ranges": {"mild": {"min": 2.0, "max": 2.9}, "moderate": {"min": 1.0, "max": 1.9}, "severe": {"min": 0.1, "max": 0.9}}, "frequency": "sometimes", "importance": "optional", "caveat": "Low folate is associated with depressive symptoms and poor response to treatment."}], "ecg": {"findings": [{"feature": "qt", "finding": "Prolonged QTc interval", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "rate", "finding": "Sinus tachycardia", "frequency": "common", "min_severity": "moderate"}]}, "imaging": [{"study": "MRI brain without contrast", "modality": "mri", "findings": [{"text": "No acute infarct, hemorrhage, or mass", "frequency": "almost_always"}, {"text": "Nonspecific white matter hyperintensities", "frequency": "sometimes"}]}, {"study": "CT head without contrast", "modality": "ct", "findings": [{"text": "No acute intracranial abnormality", "frequency": "almost_always"}]}], "workup": {"initial": [{"test": "tsh", "why": "Screens for thyroid disease, a common reversible cause of mood symptoms"}, {"test": "bmp", "why": "Baseline electrolytes and renal function before starting mood stabilizers"}, {"test": "cbc", "why": "Baseline blood counts; some psychotropic medications can affect them"}, {"test": "Ua tox", "why": "Detects stimulant or other substance use that can cause or mimic mania"}, {"test": "hcg", "why": "Pregnancy test before medication selection", "only_if": "patient is a woman of childbearing age"}], "confirmatory": [], "supporting": [{"test": "ft4", "why": "Confirms hyperthyroidism if TSH is abnormal"}, {"test": "cr", "why": "Renal function before lithium or other renally cleared drugs"}, {"test": "ca", "why": "Screens for hypercalcemia, which can cause psychiatric symptoms"}, {"test": "a1c", "why": "Screens for diabetes, a common comorbidity affecting medication choice"}, {"test": "b12", "why": "Deficiency can contribute to mood and cognitive symptoms"}, {"test": "folate", "why": "Deficiency can contribute to depressive symptoms"}, {"test": "cortisol_am", "why": "Screens for Cushing syndrome if clinical features suggest it", "only_if": "features of Cushing syndrome are present"}], "not_indicated": [{"test": "MRI brain without contrast", "why": "Not routine; reserved for focal neurologic findings or atypical presentation", "only_if": "focal neurologic deficits or atypical features are present"}, {"test": "CT head without contrast", "why": "Not routine; reserved for acute neurologic change or head trauma", "only_if": "acute neurologic change or head trauma is present"}, {"test": "Csf analysis", "why": "Not indicated unless CNS infection or inflammation is suspected"}, {"test": "EEG", "why": "Not indicated unless seizures are suspected"}], "decision_points": ["Always assess suicide risk and safety", "Rule out substance-induced mood disorder with urine toxicology", "Check TSH and free T4 to exclude thyroid disease", "Check pregnancy status before prescribing mood stabilizers in women of childbearing age", "Consider MRI or CT brain only if focal neurologic signs or atypical presentation"], "criteria": [{"name": "Manic episode", "summary": "A distinct period of abnormally elevated, expansive, or irritable mood with increased energy lasting at least one week (or any duration if hospitalization is needed), with at least three of: grandiosity, decreased need for sleep, pressured speech, flight of ideas, distractibility, increased goal-directed activity, or risky behavior; causes marked impairment or requires hospitalization."}, {"name": "Hypomanic episode", "summary": "A distinct period of elevated, expansive, or irritable mood with increased energy lasting at least four days, with similar but less severe symptoms; not severe enough to cause marked impairment or require hospitalization, but noticeable to others."}, {"name": "Major depressive episode", "summary": "At least two weeks of depressed mood or loss of interest, with at least four of: appetite or weight change, sleep disturbance, psychomotor changes, fatigue, worthlessness or guilt, poor concentration, or suicidal thoughts."}, {"name": "Bipolar I disorder", "summary": "At least one manic episode; depressive or hypomanic episodes may also occur."}, {"name": "Bipolar II disorder", "summary": "At least one hypomanic episode and at least one major depressive episode; no full manic episode."}, {"name": "Cyclothymic disorder", "summary": "At least two years (one year in youth) of numerous periods with hypomanic symptoms and depressive symptoms that do not meet full criteria for a manic, hypomanic, or major depressive episode."}], "scores": ["ymrs", "mdq", "phq_9", "c_ssrs"]}, "differential": [{"name": "Major depressive disorder", "slug": "major-depressive-disorder", "why_considered": "Depressive episodes are common in bipolar disorder and often bring the patient to care first; recurrent depression can look identical until an elevated episode is uncovered.", "must_not_miss": true, "trigger": "Any patient presenting with depression, especially early onset, atypical, or treatment-resistant depression", "discriminators": {"history": ["No lifetime manic or hypomanic episode", "No discrete periods of decreased need for sleep with increased energy", "Depression is the only mood polarity", "Family history of depression rather than bipolar disorder"], "exam": ["Depressed mood or anhedonia without elevated, expansive, or irritable mood", "Psychomotor retardation or agitation without pressured speech or flight of ideas"], "labs": ["Normal TSH and free T4", "No substance or medication trigger for mood elevation"]}}, {"name": "Substance-induced mood disorder", "slug": "substance-induced-mood-disorder", "why_considered": "Stimulants, cannabis, alcohol, and withdrawal states can produce elevated, irritable, or depressed mood that mimics a mood episode.", "must_not_miss": true, "trigger": "Mood symptoms that begin during or shortly after substance use or withdrawal", "discriminators": {"history": ["Temporal link between substance use or withdrawal and mood symptoms", "Symptoms resolve with sustained abstinence", "No prior discrete mood episodes independent of substance use"], "exam": ["Signs of intoxication or withdrawal", "Mood changes track with substance use rather than a spontaneous episode"], "labs": ["Positive urine toxicology for stimulants, cannabis, or other substances", "Normal thyroid studies"]}}, {"name": "Schizophrenia", "slug": "schizophrenia", "why_considered": "Psychotic symptoms occur in severe mania and can be mistaken for a primary psychotic disorder.", "must_not_miss": true, "trigger": "Psychosis with prominent mood symptoms or a history of mood episodes", "discriminators": {"history": ["Psychosis occurs only during mood episodes in bipolar disorder", "Prominent and persistent mood symptoms", "Delusions or hallucinations lasting more than two weeks without mood symptoms suggests schizophrenia"], "exam": ["Mood-congruent grandiosity or elevated mood during psychosis", "Negative symptoms such as flat affect are more prominent in schizophrenia"], "labs": ["Urine toxicology to exclude substances", "Normal thyroid studies"]}}, {"name": "Schizoaffective disorder", "slug": "schizoaffective-disorder", "why_considered": "Combines psychotic and mood symptoms, overlapping heavily with bipolar disorder with psychotic features.", "must_not_miss": false, "discriminators": {"history": ["Delusions or hallucinations for at least two weeks in the absence of mood symptoms", "Mood episodes present for the majority of the illness duration", "Psychosis persists beyond mood episodes"], "exam": ["Psychotic symptoms may be present even when mood is euthymic"]}}, {"name": "Hyperthyroidism", "slug": "hyperthyroidism", "why_considered": "Thyroid disease can cause irritability, insomnia, weight loss, palpitations, and mood elevation that mimic mania.", "must_not_miss": false, "discriminators": {"history": ["Heat intolerance, tremor, palpitations, weight loss despite increased appetite", "No discrete mood episodes with periods of normal mood"], "exam": ["Goiter, lid lag, proptosis, fine tremor, tachycardia"], "labs": ["Low TSH with elevated free T4"]}}, {"name": "Attention-deficit/hyperactivity disorder", "slug": "attention-deficit-hyperactivity-disorder", "why_considered": "Chronic hyperactivity, impulsivity, and distractibility can be confused with hypomania, especially in children and young adults.", "must_not_miss": false, "discriminators": {"history": ["Symptoms are chronic and lifelong rather than episodic", "No discrete periods of elevated mood with decreased need for sleep", "Symptoms present before age 12"], "exam": ["Hyperactivity and inattention without mood elevation or grandiosity"]}}, {"name": "Borderline personality disorder", "slug": "borderline-personality-disorder", "why_considered": "Mood instability, impulsivity, and irritability can resemble rapid mood shifts.", "must_not_miss": false, "discriminators": {"history": ["Mood shifts are rapid and reactive to interpersonal triggers rather than sustained episodes", "Chronic feelings of emptiness, fear of abandonment, identity disturbance", "No discrete episodes lasting days to weeks"], "exam": ["Mood changes within minutes to hours rather than days", "Self-harm often without suicidal intent"]}}, {"name": "Cushing syndrome", "slug": "cushing-syndrome", "why_considered": "Excess cortisol can cause depression, mania, or psychosis along with insomnia and irritability.", "must_not_miss": false, "discriminators": {"history": ["Weight gain, easy bruising, proximal muscle weakness, striae", "Recent corticosteroid use"], "exam": ["Central obesity, moon facies, buffalo hump, purple striae, hypertension"], "labs": ["Elevated morning cortisol or failed dexamethasone suppression"]}}, {"name": "Delirium", "slug": "delirium", "why_considered": "Acute confusion, agitation, and mood lability can be mistaken for mania, especially in older adults.", "must_not_miss": true, "trigger": "Acute onset of confusion or agitation with fluctuating attention", "discriminators": {"history": ["Acute onset over hours to days", "Fluctuating course with inattention", "Recent infection, medication change, or metabolic disturbance"], "exam": ["Disorientation, fluctuating attention, altered level of consciousness"], "labs": ["Abnormal CBC, BMP, or urinalysis suggesting infection or metabolic cause"]}}], "course": {"severity": {"mild": "Hypomanic or mild depressive symptoms that are noticeable to others but do not cause marked impairment; the patient can function at work and home with support.", "moderate": "Clear manic or major depressive episode with significant impairment in work, relationships, or self-care; no psychosis and no immediate danger.", "severe": "Mania with psychosis, dangerous impulsivity, or severe depression with inability to care for self; requires hospitalization or intensive treatment.", "critical": "Life-threatening: catatonia, severe self-harm or suicide attempt, dangerous agitation, or medical complications such as dehydration or neuroleptic malignant syndrome."}, "red_flags": [{"finding": "Suicidal ideation with plan or intent", "meaning": "Immediate risk of self-harm; requires emergency psychiatric evaluation and safety planning"}, {"finding": "Psychosis with command hallucinations or dangerous grandiosity", "meaning": "Risk of harm to self or others; needs urgent hospitalization"}, {"finding": "Catatonia", "meaning": "Medical emergency; can lead to dehydration, rhabdomyolysis, and death without treatment"}, {"finding": "Severe agitation or violent behavior", "meaning": "Risk of injury; requires acute stabilization"}, {"finding": "Inability to maintain nutrition or hydration", "meaning": "Medical compromise during a prolonged episode; may need inpatient care"}, {"finding": "Rapid cycling with four or more episodes per year", "meaning": "More difficult to treat and associated with higher morbidity"}], "complications": [{"name": "Suicide attempt or completed suicide", "timing": "any", "seriousness": "life_threatening", "frequency": "common", "clues": ["Hopelessness", "Prior attempts", "Access to lethal means", "Recent discharge from hospital"]}, {"name": "Substance use disorder", "timing": "any", "seriousness": "serious", "frequency": "common", "clues": ["Alcohol or drug use during mood episodes", "Use to self-medicate mood symptoms"]}, {"name": "Metabolic syndrome and type 2 diabetes", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Weight gain", "Hyperglycemia", "Dyslipidemia", "Use of atypical antipsychotics"]}, {"name": "Neuroleptic malignant syndrome", "timing": "early", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Rigidity", "Fever", "Autonomic instability", "Elevated creatine kinase after antipsychotic use"]}, {"name": "Lithium toxicity", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Tremor", "Ataxia", "Confusion", "Vomiting", "Dehydration or drug interaction"]}, {"name": "Cognitive impairment", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Multiple episodes", "Long illness duration", "Complaints of memory and concentration problems between episodes"]}], "special_populations": [{"population": "children", "differences": "May present with irritability, rapid mood shifts, and behavioral problems rather than clear episodes; mania can resemble severe ADHD or oppositional behavior, and diagnosis requires careful longitudinal history."}, {"population": "older_adults", "differences": "First episodes after age 50 are less common and more often present with depression or confusion; mania may be mistaken for dementia or delirium, and medical causes and medications must be excluded."}, {"population": "pregnancy", "differences": "Mood episodes may occur during pregnancy or postpartum; postpartum psychosis is a psychiatric emergency, and medication decisions must weigh fetal and breastfeeding risks."}]}, "teaching": {"key_questions": [{"question": "Have you ever had a period of at least several days when you felt unusually high, elated, or extremely irritable, and had much more energy than usual?", "category": "hpi", "importance": "essential", "looking_for": "A discrete episode of abnormally elevated, expansive, or irritable mood with increased energy and activity, distinct from the patient's baseline"}, {"question": "How long did that period last, and did it last most of the day nearly every day?", "category": "hpi", "importance": "essential", "looking_for": "At least one week for mania (or any duration if hospitalization was needed); at least four days for hypomania"}, {"question": "During that time, how much sleep did you need, and did you still feel rested?", "category": "hpi", "importance": "essential", "looking_for": "A decreased need for sleep, sleeping only a few hours yet feeling energized, which strongly supports a manic or hypomanic episode"}, {"question": "Did you talk more or faster than usual, or feel like your thoughts were racing?", "category": "hpi", "importance": "important", "looking_for": "Pressured speech, rapid speech, or flight of ideas during the elevated period"}, {"question": "Did you feel unusually confident, powerful, or capable of things others thought were unrealistic?", "category": "hpi", "importance": "important", "looking_for": "Grandiosity or inflated self-esteem out of proportion to reality"}, {"question": "Did you do anything risky or out of character, like spending large amounts of money, reckless driving, or sexual behavior you later regretted?", "category": "hpi", "importance": "important", "looking_for": "Impulsive, risky, or poor-judgment behavior during the elevated period"}, {"question": "Have you also had periods of at least two weeks when you felt very sad, hopeless, or lost interest in things you usually enjoy?", "category": "hpi", "importance": "essential", "looking_for": "A major depressive episode, which is common in bipolar disorder and often brings the patient to care first"}, {"question": "Did other people notice or comment that you were acting differently during these periods?", "category": "associated", "importance": "important", "looking_for": "Observable change noticed by family or friends, which supports that the episode was a distinct change from baseline"}, {"question": "Were you ever hospitalized or treated urgently because of your mood or behavior?", "category": "associated", "importance": "important", "looking_for": "Hospitalization for mania supports bipolar I disorder; no hospitalization with shorter episodes suggests hypomania"}, {"question": "Have you ever heard voices or had unusual beliefs that others did not share, and did that happen only during mood episodes?", "category": "associated", "importance": "important", "looking_for": "Psychosis occurring only during mood episodes supports bipolar disorder; psychosis lasting more than two weeks without mood symptoms suggests schizophrenia or schizoaffective disorder"}, {"question": "Have you had thoughts of death, self-harm, or suicide?", "category": "red_flag", "importance": "essential", "looking_for": "Suicidal ideation, plan, or intent, which requires immediate safety assessment and emergency evaluation"}, {"question": "Have you ever been diagnosed with depression, anxiety, or ADHD, and what were you told about it?", "category": "pmh", "importance": "important", "looking_for": "A prior diagnosis of depression or ADHD that may actually reflect unrecognized bipolar disorder"}, {"question": "Have you ever taken an antidepressant, and did it seem to trigger unusual energy, irritability, or not sleeping?", "category": "medications", "importance": "important", "looking_for": "Antidepressant-associated mania or hypomania, which supports a bipolar diathesis"}, {"question": "Have you ever taken steroids, thyroid medicine, or stimulants?", "category": "medications", "importance": "important", "looking_for": "Medications that can cause or mimic mood elevation, such as corticosteroids, levothyroxine, or stimulants"}, {"question": "Does anyone in your family have bipolar disorder, depression, psychosis, or die by suicide?", "category": "family", "importance": "important", "looking_for": "A first-degree relative with bipolar disorder or related psychiatric illness, which raises risk"}, {"question": "How much alcohol or drugs do you use, and do your mood symptoms happen only when you are using or withdrawing?", "category": "social", "importance": "essential", "looking_for": "Substance use that could cause or mimic mood episodes; symptoms that occur only with use or withdrawal suggest substance-induced mood disorder"}, {"question": "Have you recently had a major stressor, loss, or a change in your sleep schedule, such as shift work?", "category": "social", "importance": "optional", "looking_for": "Stressors or circadian disruption that may precipitate episodes"}, {"question": "If you could be pregnant, when was your last period?", "category": "obstetric", "importance": "important", "looking_for": "Pregnancy status, which affects medication selection and safety"}], "accepted_names": ["Bipolar disorder", "Bipolar I disorder", "Bipolar II disorder", "Bipolar affective disorder", "Manic depression", "Manic-depressive illness", "Cyclothymic disorder", "Cyclothymia"], "reasoning_points": ["A discrete episode of abnormally elevated, expansive, or irritable mood with increased energy and activity lasting at least one week (or any duration if hospitalization was needed) for mania, or at least four days for hypomania", "At least three additional symptoms during the elevated period, such as grandiosity, decreased need for sleep, pressured speech, flight of ideas, distractibility, increased goal-directed activity, or risky behavior", "A decreased need for sleep with continued feeling of being rested, which is a hallmark of mania and hypomania", "The presence of at least one major depressive episode, which is common and often the reason the patient seeks care", "Symptoms cause marked impairment or require hospitalization in mania, but not in hypomania", "Psychosis, if present, occurs only during mood episodes rather than independently", "Substance use and medications such as corticosteroids, levothyroxine, or stimulants have been considered and excluded as the cause", "Thyroid disease and other medical causes of mood change have been excluded with history and laboratory testing", "Suicide risk and safety have been assessed directly", "The pattern of discrete episodes separated by periods of normal mood distinguishes bipolar disorder from chronic mood instability or personality-related mood shifts"], "difficulty": {"easy": ["Young adult with a clear history of a week-long episode of elevated mood, decreased need for sleep, pressured speech, and risky spending", "Family history of bipolar disorder", "Prior hospitalization for mania", "Clear alternation between elevated and depressed episodes with normal mood in between"], "medium": ["Patient presents with depression and only on careful questioning reveals a past hypomanic episode", "Antidepressant-associated hypomania or mania", "Bipolar II disorder with prominent depression and subtle hypomania", "Substance use that complicates the timeline of mood episodes"], "hard": ["Older adult with a first episode of mania or confusion, requiring exclusion of delirium, dementia, and medical causes", "Psychosis that raises the question of schizophrenia or schizoaffective disorder", "Rapid cycling with four or more episodes per year", "Mixed episode with simultaneous depressive and manic symptoms", "Postpartum presentation with mood elevation or psychosis"]}}}$rounds_kb$::jsonb)
