insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$body-lice$rounds_kb$, $rounds_kb$Body Lice$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, array[$rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$musculoskeletal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "body-lice", "triage": {"name": "Body Lice", "case_suitable": true, "reason": "Pruritic rash with identifiable lice/nits on exam; diagnosis reachable by history and physical, with good exposure and hygiene history.", "kind": "disease", "category": "ectoparasitic infestation", "organ_systems": ["musculoskeletal"], "primary_clerkship": "familyMedicine", "secondary_clerkships": ["pediatrics", "emergency"], "commonness": "common", "settings": ["clinic", "pediatric_clinic", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:03Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:31:22Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:31:27Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:31:32Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:31:42Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:31:49Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'cbc' was in ['initial', 'not_indicated'], kept ['not_indicated', 'initial']", "auto-repaired: workup: 'skin scraping or scabies preparation' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'cbc' was in ['initial', 'not_indicated'], kept ['not_indicated', 'initial']", "auto-repaired: workup: 'skin scraping or scabies preparation' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential scabies: no profile yet", "differential head-lice: no profile yet", "differential pubic-lice: no profile yet", "differential atopic-dermatitis: no profile yet", "differential contact-dermatitis: no profile yet", "differential delusional-parasitosis: no profile yet", "differential louse-borne-relapsing-fever: no profile yet", "differential epidemic-typhus: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 15, "typical_max": 70, "peak": "adults experiencing homelessness or displacement", "possible_min": 0, "possible_max": 100}, "sex": "either", "demographics": ["Most common in people who cannot bathe or wash clothing regularly, especially in crowded conditions", "In the United States, most often seen in people experiencing homelessness or unstable housing", "Also seen in refugees, displaced persons, and victims of war or natural disasters", "Occurs worldwide; no clear sex predilection"], "risk_factors": [{"text": "Lack of regular bathing or laundering of clothing and bedding", "strength": "strong"}, {"text": "Crowded living conditions (shelters, encampments, refugee camps)", "strength": "strong"}, {"text": "Homelessness or unstable housing", "strength": "strong"}, {"text": "Sharing clothing, bedding, or towels with an infested person", "strength": "moderate"}, {"text": "Close physical contact with an infested person", "strength": "moderate"}, {"text": "Cold weather or inability to change or wash clothing for prolonged periods", "strength": "weak"}], "comorbidities": ["Conditions associated with poor self-care or limited access to hygiene facilities"], "family_history": [], "social_history": ["Shelter, encampment, or other crowded living arrangement", "Limited access to showers, laundry, or clean clothing", "Recent displacement, refugee, or disaster-related living situation"], "exposures": ["Contact with clothing, bedding, or towels used by a person with body lice", "Close physical contact with an infested person"], "risk_medications": []}, "presentation": {"chief_complaints": [{"text": "I itch all over, especially under my clothes", "frequency": "almost_always"}, {"text": "I keep finding little bugs and eggs in the seams of my clothes", "frequency": "common"}, {"text": "I have red bumps and scratch marks on my body", "frequency": "common"}], "hpi": {"onset": "Gradual; itching usually begins days to weeks after infestation, once sensitivity to louse saliva develops", "duration": "Weeks to months if untreated; often present for a long time before medical attention", "progression": "Itching starts and slowly worsens; scratching leads to sores that may become infected; with prolonged infestation, heavily bitten skin becomes thickened and discolored", "location": "Trunk, waist, groin, upper thighs, and areas where clothing seams and waistbands press against the skin; lice and nits are found in clothing seams rather than on the body", "radiation": "Usually none; itching is diffuse over clothed areas", "quality": "Intense, persistent itching with small red bumps and scratch marks", "severity": "Moderate to severe; itching can be intense enough to disturb sleep", "timing": "Continuous, worse at night and when clothing is worn or removed", "aggravating": ["Wearing the same clothing", "Warmth and sweating", "Scratching"], "relieving": ["Removing clothing", "Bathing", "Washing clothing and bedding in hot water"], "associated_symptoms": [{"text": "Intense itching", "frequency": "almost_always"}, {"text": "Red bumps or rash from bites and allergic reaction", "frequency": "common"}, {"text": "Scratch marks and sores from scratching", "frequency": "common"}, {"text": "Thickened, darkened skin in heavily bitten areas (waist, groin, upper thighs) with long-standing infestation", "frequency": "sometimes"}, {"text": "Sores that become infected with bacteria or fungi", "frequency": "sometimes"}, {"text": "Feeling tired or run-down", "frequency": "sometimes"}, {"text": "Fever, headache, or body aches suggesting a louse-borne illness such as typhus, trench fever, or relapsing fever", "frequency": "rare"}], "pertinent_negatives": ["Itching and nits limited to the scalp or hair", "Itching and lice limited to the pubic or genital area", "Burrows, tracks, or nodules between the fingers, wrists, or genitals", "Recent travel to an area with sandflies or other vector-borne skin disease", "Household pets with fleas or mites", "Known immunocompromising condition or immunosuppressive medication"]}, "ros": [{"system": "skin", "positives": [{"text": "Itching all over, worse under clothing", "frequency": "almost_always"}, {"text": "Red bumps or rash on the trunk, waist, and thighs", "frequency": "common"}, {"text": "Scratch marks and open sores", "frequency": "common"}, {"text": "Thickened, darkened skin in bitten areas", "frequency": "sometimes"}], "negatives": ["Rash limited to the scalp or hair", "Rash limited to the pubic area", "Burrows or tracks in the skin", "Painful nodules in the axillae or groin"], "argues_against": ["Infestation confined to the head or pubic hair", "Classic scabies burrows between the fingers or on the wrists"]}, {"system": "constitutional", "positives": [{"text": "Feeling tired or run-down", "frequency": "sometimes"}, {"text": "Fever or chills", "frequency": "rare"}], "negatives": ["Unintentional weight loss", "Night sweats"], "argues_against": ["Persistent fever with weight loss suggesting another systemic illness"]}, {"system": "psychiatric", "positives": [{"text": "Trouble sleeping because of the itching", "frequency": "sometimes"}, {"text": "Feeling embarrassed or anxious about