insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$cataract$rounds_kb$, $rounds_kb$Cataract$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, array[$rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$]::text[], array[$rounds_kb$nervous$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "cataract", "triage": {"name": "Cataract", "case_suitable": true, "reason": "Progressive painless vision loss with an abnormal red reflex and slit-lamp findings; straightforward clinic presentation, though exam findings are specialty-specific.", "kind": "disease", "category": "lens opacity", "organ_systems": ["nervous"], "primary_clerkship": "familyMedicine", "secondary_clerkships": ["internalMedicine"], "commonness": "very_common", "settings": ["clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:21Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:00Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:06Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:11Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:19Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:25Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'slit-lamp examination of the anterior segment' was in ['initial', 'confirmatory'], kept ['initial']", "differential open-angle-glaucoma: no profile yet", "differential age-related-macular-degeneration: no profile yet", "differential diabetic-retinopathy: no profile yet", "differential retinal-detachment: no profile yet", "differential glaucoma-suspect: no profile yet", "differential uveitis: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 55, "typical_max": 90, "peak": "65–80", "possible_min": 0, "possible_max": 110}, "sex": "either", "demographics": ["Very common with advancing age; by age 80 more than half of Americans have a cataract or have had cataract surgery", "Slightly more common in women in most US surveys", "More prevalent and more likely to cause vision loss in Black and Hispanic adults in the US"], "risk_factors": [{"text": "Older age", "strength": "strong"}, {"text": "Diabetes mellitus", "strength": "strong"}, {"text": "Cumulative ultraviolet light exposure (sun, tanning, welding)", "strength": "moderate"}, {"text": "Cigarette smoking", "strength": "moderate"}, {"text": "Family history of cataract", "strength": "moderate"}, {"text": "Prior eye injury or prior eye surgery (e.g., glaucoma surgery)", "strength": "moderate"}, {"text": "Heavy alcohol use", "strength": "weak"}, {"text": "High myopia", "strength": "weak"}], "comorbidities": ["Diabetes mellitus", "Hypertension", "High myopia", "Glaucoma", "Uveitis", "Atopic dermatitis"], "family_history": ["Cataract in a parent or sibling, especially early-onset"], "social_history": ["Outdoor work or long hours in the sun without eye protection", "Current or past smoking", "Heavy alcohol use"], "exposures": ["Chronic ultraviolet light exposure", "Ionizing radiation to the head or neck", "Blunt or penetrating eye trauma"], "risk_medications": ["prednisone", "dexamethasone", "prednisolone"]}, "presentation": {"chief_complaints": [{"text": "My vision has gotten blurry and cloudy", "frequency": "almost_always"}, {"text": "The headlights at night are blinding and there are halos around lights", "frequency": "common"}, {"text": "I keep needing new glasses prescriptions", "frequency": "common"}, {"text": "Colors don't look as bright as they used to", "frequency": "sometimes"}, {"text": "I can't see well enough to read or drive anymore", "frequency": "common"}], "hpi": {"onset": "Gradual and painless, usually noticed only after it has been present for months", "duration": "Months to years; most patients have had subtle changes for a year or more before seeking care", "progression": "Slowly progressive and irreversible; vision worsens as the lens opacity thickens, and symptoms eventually interfere with reading, driving, or recognizing faces", "location": "One or both eyes; when unilateral, the affected eye is the symptomatic one", "radiation": "Not applicable", "quality": "Blurring, cloudiness, or a film over the vision; glare and halos around lights; washed-out or yellowed color perception", "severity": "Mild at first and often dismissed as needing new glasses; becomes moderate to severe when it limits daily activities", "timing": "Constant, but worse in dim light, at night, and with bright oncoming lights; some patients notice better near vision than distance vision (second sight)", "aggravating": ["Driving at night", "Bright lights and oncoming headlights", "Reading small print", "Dim lighting", "Sunlight"], "relieving": ["Brighter lighting", "New eyeglasses prescription", "Magnifiers", "Squinting"], "associated_symptoms": [{"text": "Glare from headlights, lamps, or sunlight", "frequency": "common"}, {"text": "Halos around lights", "frequency": "common"}, {"text": "Poor night vision", "frequency": "common"}, {"text": "Faded or yellowed color vision", "frequency": "sometimes"}, {"text": "Double vision in one eye that goes away when the other eye is covered", "frequency": "sometimes"}, {"text": "Frequent changes in glasses or contact lens prescription", "frequency": "common"}, {"text": "Trouble reading or doing everyday tasks", "frequency": "common"}], "pertinent_negatives": ["Eye pain or aching", "Redness of the eye", "Sudden vision loss over minutes to hours", "Flashes of light or a curtain/shade across the vision", "New floaters", "Severe headache with nausea and vomiting", "Eye discharge", "Contact lens overuse", "Recent eye trauma"]}, "ros": [{"system": "eyes", "positives": [{"text": "Blurry or cloudy vision", "frequency": "almost_always"}, {"text": "Glare and halos around lights", "frequency": "common"}, {"text": "Difficulty seeing at night", "frequency": "common"}, {"text": "Faded color vision", "frequency": "sometimes"}, {"text": "Monocular double vision", "frequency": "sometimes"}], "negatives": ["Eye pain", "Red eye", "Purulent discharge", "Photophobia", "Sudden painless vision loss", "Flashes or floaters", "Visual field loss"], "argues_against": ["Acute angle-closure glaucoma", "Retinal detachment", "Central retinal artery occlusion", "Acute uveitis or keratitis"]}, {"system": "neurologic", "positives": [], "negatives": ["Headache", "Focal weakness or numbness", "Diplopia with both eyes open", "Transient monocular vision loss"], "argues_against": ["Stroke or transient ischemic attack", "Optic neuritis", "Migraine with aura"]}, {"system": "constitutional", "positives": [], "negatives": ["Fever", "Weight loss", "Malaise"], "argues_against": ["Giant cell arteritis", "Systemic infection"]}], "atypical": [{"population": "children", "how_it_differs": "Pediatric cataracts are usually congenital or associated with a syndrome, metabolic disease, or intrauterine infection; infants may present with a white pupil (leukocoria), poor visual tracking, or strabismus rather than complaints of blurry vision.", "missing_classic_features": ["Gradual age-related blurring", "Glare and halos described by the patient", "Longstanding slow progression"]}, {"population": "diabetes", "how_it_differs": "Cataracts appear earlier and progress faster, and fluctuating blood glucose can cause rapid but reversible refractive shifts that mimic cataract progression.", "missing_classic_features": ["Slow, steady progression", "Clear temporal link to aging alone"]}, {"population": "older_adults", "how_it_differs": "Patients may not report vision problems at all; instead they present with falls, difficulty reading medication labels, or a family member noticing they can no longer drive safely.", "missing_classic_features": ["Self-reported blurry vision", "Complaint of glare or halos"]}]}, "exam": {"general": {"mild": "Comfortable, well-appearing, no distress; may squint or lean toward the examiner", "moderate": "Well-appearing but visibly straining to read or recognize faces; may hold materials at arm's length", "severe": "Well-appearing but functionally limited; may need help navigating the room or reading forms", "critical": "Not applicable; cataract alone does not cause a toxic or systemically ill appearance"}, "findings": [{"id": "reduced-distance-acuity", "region": "heent", "maneuver": "Check distance visual acuity one eye at a time with a Snellen chart, with the patient's current glasses on", "finding": "Reduced best-corrected distance acuity in the affected eye(s)", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "pinhole-improvement", "region": "heent", "maneuver": "Repeat the acuity measurement through a pinhole occluder", "finding": "Acuity improves only partially or not at all, unlike a pure refractive error", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "red-reflex-abnormal", "region": "heent", "maneuver": "Shine the ophthalmoscope light into the eye from about 12 inches and observe the red reflex", "finding": "Dull, diminished, or absent red reflex; may see dark opacities within the reflex", "frequency": "common", "significance": "strongly_supports", "importance": "essential"}, {"id": "lens-opacity-slit-lamp", "region": "heent", "maneuver": "Examine the anterior segment at the slit lamp after pupil dilation", "finding": "Visible lens opacity (nuclear sclerosis, cortical spokes, or posterior subcapsular plaque)", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "glare-sensitivity", "region": "heent", "maneuver": "Shine a bright light or penlight toward the eye and ask about discomfort or worsening of vision", "finding": "Marked glare or worsening of vision with bright light", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "normal-pupils", "region": "heent", "maneuver": "Check pupil size, symmetry, and reactivity to light", "finding": "Pupils equal, round, and reactive; no afferent pupillary defect", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "white-pupil", "region": "heent", "maneuver": "Inspect the pupil in room light and with the ophthalmoscope", "finding": "Leukocoria (white pupillary reflex)", "frequency": "rare", "significance": "supports", "importance": "important"}, {"id": "normal-conjunctiva", "region": "heent", "maneuver": "Inspect the conjunctiva and sclera in room light", "finding": "White sclera with no injection, discharge, or ciliary flush", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "non-tender-eye", "region": "heent", "maneuver": "Palpate gently around the orbit and ask about eye pain", "finding": "No ocular or periorbital tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-iop", "region": "heent", "maneuver": "Measure intraocular pressure by tonometry when available", "finding": "Intraocular pressure within the normal range", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-fundus", "region": "heent", "maneuver": "Perform a dilated fundoscopic exam", "finding": "Optic disc, macula, and vessels appear normal; no hemorrhages, exudates, or disc edema", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "normal-extraocular-movements", "region": "heent", "maneuver": "Test extraocular movements in all directions of gaze", "finding": "Full, conjugate, and painless eye movements without diplopia", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-visual-fields", "region": "heent", "maneuver": "Confrontation visual fields in each eye", "finding": "Full visual fields without scotoma or field cut", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-relative-afferent-pupillary-defect", "region": "heent", "maneuver": "Swinging flashlight test", "finding": "No relative afferent pupillary defect", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-neurologic-exam", "region": "neuro", "maneuver": "Screen cranial nerves, strength, sensation, and coordination", "finding": "No focal neurologic deficits", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {}, "labs": [], "imaging": [{"study": "Slit-lamp examination of the anterior segment", "modality": "other", "findings": [{"text": "Lens opacity: nuclear sclerosis (yellow-brown central haze), cortical spokes, or posterior subcapsular plaque", "frequency": "almost_always"}, {"text": "Dense white or brunescent lens opacity obscuring the red reflex", "frequency": "sometimes"}, {"text": "Normal anterior chamber, cornea, and iris without cells or flare", "frequency": "common"}]}, {"study": "Dilated fundoscopic examination", "modality": "other", "findings": [{"text": "Optic disc, macula, and vessels normal; no hemorrhages, exudates, or disc edema", "frequency": "common"}, {"text": "Lens opacity partially obscures the view of the posterior pole", "frequency": "sometimes"}, {"text": "Incidental diabetic or hypertensive retinopathy in a patient with those comorbidities", "frequency": "sometimes"}]}, {"study": "Optical coherence tomography of the macula", "modality": "other", "preferred_when": "Suspected coexisting macular disease before cataract surgery", "findings": [{"text": "Normal macular architecture with intact foveal contour", "frequency": "common"}, {"text": "Macular edema, epiretinal membrane, or drusen suggesting a coexisting retinal condition", "frequency": "sometimes"}]}, {"study": "Ocular ultrasound (B-scan)", "modality": "ultrasound", "preferred_when": "Dense cataract prevents a view of the posterior segment", "findings": [{"text": "Normal posterior segment with no retinal detachment or mass", "frequency": "common"}, {"text": "Retinal detachment or intraocular mass identified behind the opaque lens", "frequency": "rare"}]}], "workup": {"initial": [{"test": "Visual acuity testing with refraction", "why": "Establishes the degree of vision loss and whether it improves with correction"}, {"test": "Slit-lamp examination of the anterior segment", "why": "Directly visualizes the lens opacity and classifies its type"}, {"test": "Dilated fundoscopic examination", "why": "Evaluates the retina and optic nerve for coexisting disease"}, {"test": "Red reflex assessment", "why": "Bedside screen for lens opacity and leukocoria"}, {"test": "Intraocular pressure measurement by tonometry", "why": "Screens for coexisting glaucoma"}], "confirmatory": [], "supporting": [{"test": "Optical coherence tomography of the macula", "why": "Detects macular disease that could limit visual recovery after surgery", "only_if": "macular pathology is suspected or the fundus view is poor"}, {"test": "Ocular ultrasound (B-scan)", "why": "Assesses the posterior segment when the lens is too opaque to see through", "only_if": "dense cataract obscures the fundus"}, {"test": "a1c", "why": "Identifies diabetes, which accelerates cataract formation and affects surgical planning", "only_if": "diabetes is suspected or glycemic control is unknown"}, {"test": "glucose", "why": "Screens for hyperglycemia that can cause reversible refractive fluctuation", "only_if": "the patient reports rapid changes in glasses prescription"}], "not_indicated": [{"test": "cbc", "why": "No role in an isolated lens opacity"}, {"test": "bmp", "why": "Not needed for diagnosis; obtain only for preoperative clearance when indicated"}, {"test": "esr", "why": "Does not help diagnose cataract; consider only if giant cell arteritis is suspected"}, {"test": "crp", "why": "Does not help diagnose cataract"}, {"test": "tsh", "why": "Not part of the cataract workup unless thyroid eye disease is suspected"}, {"test": "MRI of the brain and orbits", "why": "Not indicated for a lens opacity; reserved for suspected intracranial or orbital pathology"}, {"test": "CT of the head", "why": "Not indicated for cataract"}], "decision_points": ["Cataract surgery is offered when the opacity limits the patient's daily activities, not based on acuity alone", "Dilated fundus examination and macular assessment before surgery to identify coexisting retinal disease", "In infants and children with leukocoria, evaluate urgently for retinoblastoma and congenital cataract"], "criteria": [], "scores": []}, "differential": [{"name": "Open-angle glaucoma", "slug": "open-angle-glaucoma", "why_considered": "Both are common causes of progressive, painless vision loss in older adults and frequently coexist.", "must_not_miss": true, "trigger": "Peripheral vision loss, elevated intraocular pressure, or optic disc cupping", "discriminators": {"history": ["Gradual loss of peripheral vision rather than central blurring", "Often asymptomatic until late", "Family history of glaucoma"], "exam": ["Elevated intraocular pressure on tonometry", "Optic disc cupping with increased cup-to-disc ratio", "Visual field defects on perimetry"], "labs": [], "imaging": ["Optical coherence tomography showing retinal nerve fiber layer thinning"]}}, {"name": "Age-related macular degeneration", "slug": "age-related-macular-degeneration", "why_considered": "Common cause of central vision loss in older adults that can be mistaken for cataract.", "must_not_miss": true, "trigger": "Central vision distortion or scotoma with relatively preserved peripheral vision", "discriminators": {"history": ["Central blurring or distortion (metamorphopsia)", "Difficulty reading or recognizing faces", "Straight lines appear wavy"], "exam": ["Reduced central acuity with normal peripheral fields", "Drusen, pigmentary changes, or macular hemorrhage on fundoscopy"], "labs": [], "imaging": ["Optical coherence tomography showing drusen, subretinal fluid, or macular thickening"]}}, {"name": "Diabetic retinopathy", "slug": "diabetic-retinopathy", "why_considered": "Diabetes is a strong risk factor for cataract, and diabetic retinopathy can cause similar visual symptoms.", "must_not_miss": true, "trigger": "Known diabetes with floaters, fluctuating vision, or retinal findings", "discriminators": {"history": ["Longstanding or poorly controlled diabetes", "Floaters or sudden vision changes", "Fluctuating vision with glucose control"], "exam": ["Microaneurysms, hemorrhages, exudates, or neovascularization on fundoscopy", "Macular edema"], "labs": ["Elevated hemoglobin A1c"], "imaging": ["Fluorescein angiography showing leakage or ischemia", "Optical coherence tomography showing macular edema"]}}, {"name": "Retinal detachment", "slug": "retinal-detachment", "why_considered": "Can present with sudden visual changes that patients may attribute to cataract.", "must_not_miss": true, "trigger": "Sudden onset of flashes, floaters, or a curtain-like visual field defect", "discriminators": {"history": ["Sudden onset of flashes and floaters", "Curtain or shade across vision", "Recent eye trauma or surgery"], "exam": ["Visual field defect", "Retinal tear or detachment on dilated fundoscopy"], "labs": [], "imaging": ["Ocular ultrasound showing retinal detachment if fundus view is obscured"]}}, {"name": "Primary open-angle glaucoma suspect", "slug": "glaucoma-suspect", "why_considered": "Patients with risk factors for glaucoma may have subtle visual complaints overlapping with cataract.", "must_not_miss": false, "discriminators": {"history": ["Family history of glaucoma", "No significant visual symptoms"], "exam": ["Borderline intraocular pressure", "Suspicious optic disc appearance without definite field loss"], "labs": [], "imaging": ["Optical coherence tomography showing borderline nerve fiber layer thinning"]}}, {"name": "Uveitis", "slug": "uveitis", "why_considered": "Can cause blurred vision and is associated with cataract formation, especially in younger patients.", "must_not_miss": false, "discriminators": {"history": ["Eye pain, redness, and photophobia", "Associated systemic autoimmune disease"], "exam": ["Ciliary flush, cells and flare in the anterior chamber", "Synechiae or keratic precipitates"], "labs": ["Elevated inflammatory markers if systemic disease suspected"], "imaging": []}}], "course": {"severity": {"mild": "Early lens opacity; vision still adequate for most activities, occasional glare or need for brighter light, and symptoms may be managed with new glasses.", "moderate": "Increasing opacity; noticeable blurring, glare, halos, and difficulty with night driving or reading small print; interferes with some daily activities.", "severe": "Dense opacity; vision significantly impaired, limiting reading, driving, and recognizing faces; surgery is typically indicated.", "critical": "Not applicable; cataract alone is not life-threatening."}, "red_flags": [{"finding": "Sudden painless vision loss", "meaning": "Suggests retinal artery occlusion, vitreous hemorrhage, or retinal detachment rather than cataract"}, {"finding": "Eye pain, redness, or photophobia", "meaning": "Suggests uveitis, acute angle-closure glaucoma, or keratitis"}, {"finding": "Flashes of light or new floaters", "meaning": "Suggests retinal tear or detachment"}, {"finding": "Curtain or shade across vision", "meaning": "Suggests retinal detachment"}, {"finding": "Leukocoria in a child", "meaning": "Requires urgent evaluation for retinoblastoma or congenital cataract"}], "complications": [{"name": "Posterior capsular opacification", "timing": "late", "seriousness": "minor", "frequency": "common", "clues": ["Gradual return of blurry vision months to years after cataract surgery", "Cloudy posterior capsule on slit-lamp exam"]}, {"name": "Retained lens fragments", "timing": "early", "seriousness": "serious", "frequency": "rare", "clues": ["Persistent inflammation after surgery", "Elevated intraocular pressure"]}, {"name": "Endophthalmitis", "timing": "early", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Severe eye pain, redness, and vision loss days after surgery", "Hypopyon on exam"]}, {"name": "Retinal detachment", "timing": "any", "seriousness": "serious", "frequency": "rare", "clues": ["Sudden flashes, floaters, or visual field defect after surgery"]}], "special_populations": [{"population": "children", "differences": "Pediatric cataracts are often congenital or associated with syndromes, metabolic disorders, or intrauterine infections; they may present with leukocoria, strabismus, or poor visual tracking and require urgent evaluation to prevent amblyopia."}, {"population": "older_adults", "differences": "May not report vision problems; instead present with falls, difficulty reading medication labels, or family noticing unsafe driving."}, {"population": "diabetes", "differences": "Cataracts appear earlier and progress faster; fluctuating blood glucose can cause reversible refractive changes that mimic cataract progression."}]}, "teaching": {"key_questions": [{"question": "How has your vision changed, and how long has this been going on?", "category": "hpi", "importance": "essential", "looking_for": "Gradual, painless blurring or cloudiness over months to years"}, {"question": "Is the change in one eye or both?", "category": "hpi", "importance": "important", "looking_for": "One or both eyes; cataract does not spread between eyes"}, {"question": "What makes your vision worse?", "category": "hpi", "importance": "essential", "looking_for": "Dim light, night driving, bright lights and oncoming headlights"}, {"question": "Do you see glare or halos around lights?", "category": "associated", "importance": "important", "looking_for": "Glare and halos, especially at night"}, {"question": "Have your glasses or contact lens prescriptions been changing often?", "category": "associated", "importance": "important", "looking_for": "Frequent prescription changes; may report better near vision than before"}, {"question": "Do colors look faded or yellowed?", "category": "associated", "importance": "optional", "looking_for": "Washed-out or yellowed color perception"}, {"question": "Do you see double? Does it go away when you cover one eye?", "category": "associated", "importance": "important", "looking_for": "Monocular double vision that resolves with one eye covered"}, {"question": "Is there any eye pain, redness, or discharge?", "category": "red_flag", "importance": "essential", "looking_for": "Absent; pain or redness points to uveitis, acute angle-closure glaucoma, or keratitis"}, {"question": "Did the vision loss come on suddenly, or have you had flashes, new floaters, or a curtain across your vision?", "category": "red_flag", "importance": "essential", "looking_for": "Absent; these suggest retinal detachment or vascular occlusion"}, {"question": "Does this interfere with reading, driving, watching TV, or recognizing faces?", "category": "hpi", "importance": "essential", "looking_for": "Functional limitation; this is what drives the decision to offer surgery"}, {"question": "Do you have diabetes, or any other health problems?", "category": "pmh", "importance": "important", "looking_for": "Diabetes accelerates cataract formation and affects surgical planning"}, {"question": "Have you ever had an eye injury or eye surgery?", "category": "pmh", "importance": "important", "looking_for": "Prior trauma or surgery (e.g., glaucoma surgery) as a cause"}, {"question": "Do you take steroid medicines, by mouth, injection, or as eye drops?", "category": "medications", "importance": "important", "looking_for": "Chronic corticosteroid use as a risk factor"}, {"question": "Does anyone in your family have cataracts, especially at a young age?", "category": "family", "importance": "optional", "looking_for": "Family history, particularly early-onset"}, {"question": "Do you smoke or drink alcohol?", "category": "social", "importance": "optional", "looking_for": "Current or past smoking, heavy alcohol use"}, {"question": "Do you spend a lot of time outdoors or in the sun without eye protection?", "category": "social", "importance": "optional", "looking_for": "Cumulative ultraviolet light exposure"}], "accepted_names": ["Cataract", "Age-related cataract", "Senile cataract", "Nuclear sclerotic cataract", "Cortical cataract", "Posterior subcapsular cataract", "Lens opacity"], "reasoning_points": ["Gradual, painless, progressive blurring or cloudiness of vision over months to years", "Glare and halos around lights, worse at night and with oncoming headlights", "Frequent changes in eyeglass prescription and faded color perception", "Reduced best-corrected distance acuity that improves only partially through a pinhole", "Dull or diminished red reflex and a visible lens opacity on slit-lamp exam", "No eye pain, redness, discharge, or acute red-flag features such as flashes, floaters, or a curtain across the vision", "Risk factors such as older age, diabetes, ultraviolet exposure, smoking, steroid use, or prior eye injury or surgery"], "difficulty": {"easy": ["Older adult with months of gradually worsening, painless blurry vision", "Glare and halos with night driving", "Reduced acuity that does not correct fully with refraction", "Dull red reflex and a visible lens opacity on slit-lamp exam"], "medium": ["Patient attributes the change to needing new glasses and reports frequent prescription changes", "Monocular double vision or faded color vision as the main complaint", "Diabetes with fluctuating vision from both refractive shifts and cataract", "Coexisting glaucoma or macular degeneration that must be separated from the cataract"], "hard": ["Older adult who does not report vision problems and instead presents with falls or trouble reading medication labels", "Dense cataract obscuring the fundus so the posterior segment cannot be assessed", "Younger patient with steroid-induced or post-traumatic cataract", "Child with leukocoria or poor visual tracking rather than complaints of blurry vision"]}}}$rounds_kb$::jsonb)
