insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$celiac-disease$rounds_kb$, $rounds_kb$Celiac Disease$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$]::text[], array[$rounds_kb$gastrointestinal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "celiac-disease", "triage": {"name": "Celiac Disease", "case_suitable": true, "reason": "Malabsorption case with a clear diagnosis reachable by history, exam, serology and biopsy, plus important look-alikes.", "kind": "disease", "category": "malabsorption syndrome", "organ_systems": ["gastrointestinal"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["familyMedicine", "pediatrics"], "commonness": "common", "settings": ["clinic", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:21Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:37:11Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:37:16Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:37:27Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:37:39Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:37:45Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'tissue_transglutaminase_iga' to 'Tissue transglutaminase iga'", "auto-repaired: workup: renamed 'total_iga' to 'Total iga'", "auto-repaired: workup: renamed 'endomyseal_iga' to 'Endomyseal iga'", "auto-repaired: workup: renamed 'gliadin_iga' to 'Gliadin iga'", "auto-repaired: workup: renamed 'hla_dq2_dq8' to 'Hla dq2 dq8'", "auto-repaired: workup: renamed 'hla_dq2_dq8' to 'Hla dq2 dq8'", "auto-repaired: workup: 'hla dq2 dq8' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'hla dq2 dq8' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential irritable-bowel-syndrome: no profile yet", "differential inflammatory-bowel-disease: no profile yet", "differential lactose-intolerance: no profile yet", "differential wheat-allergy: no profile yet", "differential non-celiac-gluten-sensitivity: no profile yet", "differential tropical-sprue: no profile yet", "differential whipple-disease: no profile yet", "differential giardiasis: no profile yet", "differential small-intestinal-bacterial-overgrowth: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 6, "typical_max": 60, "peak": "bimodal: early childhood and 30s–50s", "possible_min": 1, "possible_max": 90}, "sex": "female_predominant", "demographics": ["More common in people of European descent, especially Northern European ancestry", "Can occur in any ethnic group", "More common in females than males"], "risk_factors": [{"text": "First-degree relative with celiac disease", "strength": "strong"}, {"text": "Type 1 diabetes mellitus", "strength": "strong"}, {"text": "Down syndrome, Turner syndrome, or Williams syndrome", "strength": "strong"}, {"text": "Autoimmune thyroid disease", "strength": "moderate"}, {"text": "IgA deficiency", "strength": "moderate"}, {"text": "Female sex", "strength": "weak"}], "comorbidities": ["Type 1 diabetes mellitus", "Autoimmune thyroid disease", "IgA deficiency", "Down syndrome", "Turner syndrome", "Williams syndrome", "Osteoporosis", "Iron-deficiency anemia"], "family_history": ["Celiac disease in a first-degree relative", "Type 1 diabetes mellitus", "Autoimmune thyroid disease"], "social_history": [], "exposures": ["Diet containing wheat, barley, or rye"], "risk_medications": []}, "presentation": {"chief_complaints": [{"text": "I've been having diarrhea for months", "frequency": "common"}, {"text": "I feel tired all the time", "frequency": "common"}, {"text": "My stomach is always bloated and gassy", "frequency": "common"}, {"text": "I've lost weight without trying", "frequency": "sometimes"}, {"text": "I have an itchy, blistery rash", "frequency": "sometimes"}], "hpi": {"onset": "Gradual, often over weeks to months; may follow a viral illness, pregnancy, or stress", "duration": "Chronic, usually months to years before diagnosis", "progression": "Persistent or intermittent symptoms that wax and wane; slowly progressive malabsorption if untreated", "location": "Diffuse abdominal discomfort, often periumbilical or generalized", "radiation": "Usually none", "quality": "Crampy abdominal pain with bloating and loose stools", "severity": "Mild to moderate; can become severe with significant weight loss and malnutrition", "timing": "Related to meals; diarrhea often worse after eating gluten-containing foods", "aggravating": ["Eating wheat, barley, or rye", "Large meals", "Dairy products (if secondary lactose intolerance)"], "relieving": ["Avoiding gluten", "Eating smaller meals"], "associated_symptoms": [{"text": "Bloating and gas", "frequency": "common"}, {"text": "Fatigue", "frequency": "common"}, {"text": "Chronic diarrhea or greasy, bulky, foul-smelling stools", "frequency": "common"}, {"text": "Weight loss", "frequency": "sometimes"}, {"text": "Iron-deficiency anemia", "frequency": "sometimes"}, {"text": "Mouth ulcers or dry mouth", "frequency": "sometimes"}, {"text": "Itchy blistering rash (dermatitis herpetiformis)", "frequency": "sometimes"}, {"text": "Bone or joint pain", "frequency": "sometimes"}, {"text": "Depression or anxiety", "frequency": "sometimes"}, {"text": "Nausea and vomiting", "frequency": "sometimes"}, {"text": "Constipation", "frequency": "sometimes"}, {"text": "Lactose intolerance", "frequency": "sometimes"}], "pertinent_negatives": ["Bloody diarrhea", "Nocturnal diarrhea waking from sleep", "Fever", "Severe weight loss with night sweats", "Recent antibiotic use", "Travel to areas with poor sanitation", "Known inflammatory bowel disease"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "common"}, {"text": "Weight loss", "frequency": "sometimes"}], "negatives": ["Fever", "Night sweats"]}, {"system": "gastrointestinal", "positives": [{"text": "Diarrhea", "frequency": "common"}, {"text": "Bloating", "frequency": "common"}, {"text": "Abdominal pain", "frequency": "common"}, {"text": "Gas", "frequency": "common"}, {"text": "Constipation", "frequency": "sometimes"}, {"text": "Nausea", "frequency": "sometimes"}, {"text": "Vomiting", "frequency": "sometimes"}], "negatives": ["Blood in stool", "Jaundice"], "argues_against": ["Bloody diarrhea", "Nocturnal diarrhea"]}, {"system": "skin", "positives": [{"text": "Itchy blistering rash on elbows, knees, or buttocks", "frequency": "sometimes"}], "negatives": ["Skin rash elsewhere"]}, {"system": "musculoskeletal", "positives": [{"text": "Bone or joint pain", "frequency": "sometimes"}], "negatives": ["Joint swelling", "Morning stiffness"]}, {"system": "neurologic", "positives": [{"text": "Headaches", "frequency": "sometimes"}, {"text": "Peripheral numbness or tingling", "frequency": "sometimes"}], "negatives": ["Seizures", "Focal weakness"]}, {"system": "psychiatric", "positives": [{"text": "Depression or anxiety", "frequency": "sometimes"}], "negatives": ["Suicidal ideation"]}, {"system": "hematologic", "positives": [{"text": "Anemia", "frequency": "sometimes"}], "negatives": ["Easy bruising", "Bleeding gums"]}, {"system": "reproductive", "positives": [{"text": "Missed menstrual periods", "frequency": "sometimes"}, {"text": "History of miscarriage", "frequency": "sometimes"}], "negatives": ["Current pregnancy"]}], "atypical": [{"population": "children", "how_it_differs": "Children often present with failure to thrive, poor weight gain, irritability, and digestive symptoms; extraintestinal symptoms are less common.", "missing_classic_features": ["Weight loss", "Dermatitis herpetiformis"]}, {"population": "older_adults", "how_it_differs": "May present with anemia, osteoporosis, or neuropathy without prominent diarrhea.", "missing_classic_features": ["Diarrhea", "Abdominal pain"]}, {"population": "pregnancy", "how_it_differs": "May present with anemia, fatigue, and recurrent miscarriage; symptoms may be attributed to pregnancy.", "missing_classic_features": ["Weight loss", "Diarrhea"]}]}, "exam": {"general": {"mild": "Well-appearing, no distress; may look tired", "moderate": "Thin, pale, mildly fatigued but not toxic", "severe": "Cachectic or visibly malnourished, pale, weak, ill-appearing", "critical": "Severely wasted, dehydrated, lethargic, hypotensive"}, "findings": [{"id": "weight-loss", "region": "general", "maneuver": "Measure weight and compare with prior records or reported usual weight; calculate BMI", "finding": "Unintentional weight loss or low BMI", "frequency": "sometimes", "significance": "supports", "importance": "essential"}, {"id": "growth-faltering", "region": "general", "maneuver": "Plot height, weight, and BMI on a growth chart in a child", "finding": "Faltering growth or short stature", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "pallor", "region": "general", "maneuver": "Inspect the conjunctivae and palmar creases", "finding": "Conjunctival or palmar pallor suggesting anemia", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "abdominal-distention", "region": "abdomen", "maneuver": "Inspect and palpate the abdomen", "finding": "Abdominal distention or bloating", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "diffuse-abdominal-tenderness", "region": "abdomen", "maneuver": "Palpate all four quadrants", "finding": "Mild diffuse or periumbilical tenderness without focal or rebound tenderness", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "no-organomegaly", "region": "abdomen", "maneuver": "Palpate for hepatosplenomegaly and masses", "finding": "No hepatomegaly, splenomegaly, or abdominal mass", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "dermatitis-herpetiformis", "region": "skin", "maneuver": "Inspect the extensor surfaces of the elbows and knees, the buttocks, and the scalp", "finding": "Intensely itchy grouped vesicles or excoriated papules on an erythematous base (dermatitis herpetiformis)", "frequency": "sometimes", "significance": "strongly_supports", "importance": "essential"}, {"id": "angular-cheilitis", "region": "heent", "maneuver": "Inspect the lips and oral mucosa", "finding": "Angular cheilitis or cracking at the mouth corners", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "aphthous-ulcers", "region": "heent", "maneuver": "Inspect the oral mucosa and tongue", "finding": "Recurrent aphthous ulcers or a smooth, atrophic tongue", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "peripheral-neuropathy", "region": "neuro", "maneuver": "Test vibration, pinprick, and light touch in the feet", "finding": "Reduced distal sensation suggesting peripheral neuropathy", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "normal-rectal-exam", "region": "rectal", "maneuver": "Perform a digital rectal exam when bleeding or malignancy is a concern", "finding": "No blood, mass, or tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {"temp": {"mild": {"min": 97.8, "max": 99.1}, "moderate": {"min": 97.8, "max": 99.1}, "severe": {"min": 97.5, "max": 99.1}, "critical": {"min": 96.8, "max": 99.1}}, "hr": {"mild": {"min": 60, "max": 100}, "moderate": {"min": 70, "max": 105}, "severe": {"min": 85, "max": 120}, "critical": {"min": 100, "max": 140}}, "sbp": {"severe": {"min": 85, "max": 105}, "critical": {"min": 70, "max": 90}}, "dbp": {"severe": {"min": 50, "max": 65}, "critical": {"min": 40, "max": 60}}}, "labs": [{"test_id": "hgb", "ranges": {"mild": {"min": 11.0, "max": 12.0}, "moderate": {"min": 9.0, "max": 11.0}, "severe": {"min": 7.0, "max": 9.0}, "critical": {"min": 5.5, "max": 7.0}}, "frequency": "common", "importance": "essential", "caveat": "Iron-deficiency anemia is the most common laboratory clue; anemia may be absent in mild or screen-detected disease."}, {"test_id": "mcv", "ranges": {"mild": {"min": 75, "max": 80}, "moderate": {"min": 65, "max": 78}, "severe": {"min": 55, "max": 72}}, "frequency": "common", "importance": "important", "caveat": "Microcytic from iron deficiency; can be normocytic or macrocytic when folate or B12 deficiency coexists."}, {"test_id": "ferritin", "ranges": {"mild": {"min": 8, "max": 20}, "moderate": {"min": 4, "max": 12}, "severe": {"min": 1, "max": 8}}, "frequency": "common", "importance": "important", "caveat": "Low ferritin confirms iron deficiency; ferritin is an acute-phase reactant and may look normal when inflammation is present."}, {"test_id": "iron", "ranges": {"mild": {"min": 40, "max": 60}, "moderate": {"min": 25, "max": 50}, "severe": {"min": 10, "max": 35}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "tibc", "ranges": {"mild": {"min": 360, "max": 450}, "moderate": {"min": 400, "max": 500}, "severe": {"min": 430, "max": 550}}, "frequency": "sometimes", "importance": "optional", "caveat": "Elevated TIBC with low iron and low ferritin supports iron deficiency."}, {"test_id": "folate", "ranges": {"moderate": {"min": 1.5, "max": 3.0}, "severe": {"min": 0.5, "max": 2.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Low folate from malabsorption; can cause a macrocytic anemia."}, {"test_id": "b12", "ranges": {"moderate": {"min": 150, "max": 200}, "severe": {"min": 80, "max": 180}}, "frequency": "sometimes", "importance": "important", "caveat": "Low B12 from terminal ileal malabsorption; contributes to anemia and neuropathy."}, {"test_id": "albumin", "ranges": {"mild": {"min": 3.2, "max": 3.5}, "moderate": {"min": 2.8, "max": 3.4}, "severe": {"min": 2.0, "max": 3.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Low albumin reflects protein malabsorption and chronic inflammation; a low value supports more severe disease."}, {"test_id": "ca", "ranges": {"mild": {"min": 8.2, "max": 8.5}, "moderate": {"min": 7.8, "max": 8.4}, "severe": {"min": 7.0, "max": 8.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Hypocalcemia from vitamin D and calcium malabsorption; check albumin because total calcium falls with low albumin."}, {"test_id": "alp", "ranges": {"mild": {"min": 150, "max": 250}, "moderate": {"min": 200, "max": 400}, "severe": {"min": 300, "max": 600}}, "frequency": "sometimes", "importance": "optional", "caveat": "Elevated alkaline phosphatase can reflect osteomalacia or secondary hyperparathyroidism from malabsorption."}, {"test_id": "tsh", "ranges": {"mild": {"min": 4.0, "max": 6.0}, "moderate": {"min": 5.0, "max": 10.0}, "severe": {"min": 8.0, "max": 20.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Ordered to look for associated autoimmune thyroid disease; an elevated TSH suggests hypothyroidism."}], "imaging": [{"study": "Upper gastrointestinal endoscopy with duodenal biopsy", "modality": "endoscopy", "preferred_when": "All patients being evaluated for celiac disease while still eating gluten", "findings": [{"text": "Scalloping or loss of the normal duodenal fold pattern", "frequency": "common"}, {"text": "Mosaic or cracked-mud mucosal appearance", "frequency": "sometimes"}, {"text": "Nodularity of the duodenal mucosa", "frequency": "sometimes"}, {"text": "Attenuation or flattening of duodenal folds", "frequency": "common"}, {"text": "Normal-appearing duodenal mucosa (visible appearance does not exclude disease)", "frequency": "common"}]}, {"study": "Small bowel follow-through (barium contrast radiography)", "modality": "xray", "findings": [{"text": "Flocculation or clumping of barium from increased intraluminal fluid", "frequency": "sometimes"}, {"text": "Dilatation of small bowel loops", "frequency": "sometimes"}, {"text": "Loss of the normal feathery fold pattern", "frequency": "sometimes"}]}, {"study": "Dual-energy x-ray absorptiometry (DXA) bone density", "modality": "other", "preferred_when": "Adults at diagnosis and those with malabsorption or fracture risk", "findings": [{"text": "Low bone mineral density (osteopenia or osteoporosis)", "frequency": "common"}]}], "workup": {"initial": [{"test": "cbc", "why": "Looks for anemia and microcytosis from iron deficiency"}, {"test": "cmp_extra", "why": "Assesses albumin, calcium, and alkaline phosphatase as markers of malabsorption"}, {"test": "iron_vitamins", "why": "Confirms iron deficiency and checks folate and vitamin B12"}, {"test": "tsh", "why": "Screens for associated autoimmune thyroid disease"}, {"test": "Tissue transglutaminase iga", "why": "First-line serology for celiac disease while the patient is still eating gluten"}, {"test": "Total iga", "why": "Detects IgA deficiency, which can cause a false-negative IgA tissue transglutaminase result"}], "confirmatory": [{"test": "Upper gastrointestinal endoscopy with duodenal biopsy", "why": "Shows villous atrophy, crypt hyperplasia, and increased intraepithelial lymphocytes; the reference standard for diagnosis"}], "supporting": [{"test": "Endomyseal iga", "why": "Highly specific serology used when tissue transglutaminase is equivocal or discordant"}, {"test": "Gliadin iga", "why": "Less specific; occasionally used in young children or when other serology is unavailable"}, {"test": "Hla dq2 dq8", "why": "High negative predictive value; a negative result makes celiac disease very unlikely", "only_if": "serology and biopsy are discordant or the diagnosis is uncertain"}, {"test": "Dual-energy x-ray absorptiometry (DXA) bone density", "why": "Detects bone loss from malabsorption", "only_if": "adult at diagnosis or with malabsorption"}], "not_indicated": [{"test": "crp", "why": "Nonspecific; celiac disease does not typically cause marked systemic inflammation"}, {"test": "esr", "why": "Nonspecific and not part of the diagnostic workup"}, {"test": "lipase", "why": "Not needed unless pancreatitis is suspected"}, {"test": "d_dimer", "why": "No role in chronic diarrhea or malabsorption"}, {"test": "ua", "why": "Urinary infection does not explain chronic diarrhea and weight loss"}, {"test": "Small bowel follow-through (barium contrast radiography)", "why": "Rarely changes management now that serology and biopsy are available", "only_if": "endoscopy is not possible or a structural small bowel lesion is suspected"}, {"test": "Hla dq2 dq8", "why": "Not a routine diagnostic test because these alleles are common in the general population", "only_if": "serology and biopsy are discordant or the diagnosis is uncertain"}], "decision_points": ["Serology and biopsy must be obtained while the patient is still eating gluten; a gluten-free diet before testing causes false-negative results", "Check total IgA when tissue transglutaminase IgA is negative or borderline, because IgA deficiency can cause a false-negative result", "Do not start a gluten-free diet before the diagnostic workup is complete", "Consider HLA-DQ2/DQ8 testing only when serology and biopsy disagree"], "criteria": [{"name": "Celiac disease diagnosis", "summary": "Diagnosis requires compatible history and examination plus positive celiac serology and characteristic duodenal biopsy findings while the patient is on a gluten-containing diet. In selected children with very high tissue transglutaminase levels, some guidelines allow diagnosis without biopsy after discussion with a specialist.", "items": ["Symptoms or risk factors suggesting celiac disease", "Positive IgA tissue transglutaminase (with normal total IgA) or positive endomysial antibody", "Duodenal biopsy showing villous atrophy, crypt hyperplasia, and increased intraepithelial lymphocytes", "Testing performed while the patient is eating gluten"]}], "scores": []}, "differential": [{"name": "Irritable bowel syndrome", "slug": "irritable-bowel-syndrome", "why_considered": "Chronic bloating, abdominal pain, and altered stool habits are common to both conditions", "must_not_miss": false, "discriminators": {"history": ["Pain relieved by defecation and linked to stool frequency or form", "No weight loss, anemia, or greasy foul-smelling stools", "Symptoms fluctuate for years without progressive malnutrition"], "exam": ["Normal general appearance and nutritional status", "Mild diffuse tenderness without distention or pallor"], "labs": ["Normal hemoglobin, ferritin, albumin, and folate", "Negative tissue transglutaminase IgA"], "imaging": ["Normal duodenal biopsy if performed"]}}, {"name": "Inflammatory bowel disease", "slug": "inflammatory-bowel-disease", "why_considered": "Chronic diarrhea, abdominal pain, and weight loss can suggest Crohn disease or ulcerative colitis", "must_not_miss": true, "trigger": "Bloody diarrhea, nocturnal symptoms, fever, or perianal disease", "discriminators": {"history": ["Bloody or mucoid diarrhea", "Nocturnal diarrhea that wakes the patient", "Fever, night sweats, or perianal fistulas", "Family history of inflammatory bowel disease"], "exam": ["Focal abdominal tenderness or a right lower quadrant mass", "Perianal fissures, fistulas, or abscesses", "Aphthous ulcers and erythema nodosum or pyoderma gangrenosum"], "labs": ["Elevated CRP and ESR", "Fecal calprotectin elevated", "Negative tissue transglutaminase IgA"], "imaging": ["Terminal ileum thickening or skip lesions on CT or MRI enterography", "Mucosal ulceration and inflammation on colonoscopy"]}}, {"name": "Lactose intolerance", "slug": "lactose-intolerance", "why_considered": "Bloating, gas, and diarrhea after dairy are common in celiac disease and in primary lactose intolerance", "must_not_miss": false, "discriminators": {"history": ["Symptoms occur only after milk or dairy, not after wheat, barley, or rye", "No weight loss, anemia, or extraintestinal features", "Symptoms improve promptly with lactose avoidance"], "exam": ["Normal nutritional status and no rash", "Mild abdominal distention after dairy"], "labs": ["Normal hemoglobin, ferritin, and albumin", "Negative tissue transglutaminase IgA", "Positive hydrogen breath test after lactose load"]}}, {"name": "Wheat allergy", "slug": "wheat-allergy", "why_considered": "Symptoms after eating wheat can be mistaken for celiac disease", "must_not_miss": true, "trigger": "Urticaria, wheezing, or hypotension shortly after wheat ingestion", "discriminators": {"history": ["Rapid onset within minutes to hours of wheat ingestion", "Itchy eyes, hives, lip swelling, or trouble breathing", "No chronic diarrhea or malabsorption"], "exam": ["Urticaria, angioedema, or wheezing", "Normal nutritional status"], "labs": ["Elevated wheat-specific IgE", "Normal tissue transglutaminase IgA", "Normal duodenal biopsy"]}}, {"name": "Non-celiac gluten sensitivity", "slug": "non-celiac-gluten-sensitivity", "why_considered": "Gluten-related bloating, fatigue, and abdominal pain without villous atrophy", "must_not_miss": false, "discriminators": {"history": ["Symptoms improve on a gluten-free diet but no malabsorption", "No weight loss, anemia, or dermatitis herpetiformis"], "exam": ["Normal examination and nutritional status"], "labs": ["Negative tissue transglutaminase IgA and endomysial antibody", "Normal duodenal biopsy while on gluten"]}}, {"name": "Tropical sprue", "slug": "tropical-sprue", "why_considered": "Chronic diarrhea, weight loss, and malabsorption with small bowel mucosal injury", "must_not_miss": false, "discriminators": {"history": ["Residence or travel in the tropics", "Symptoms persist despite a gluten-free diet", "Often responds to antibiotics and folate"], "exam": ["Signs of folate or B12 deficiency", "Weight loss and pallor"], "labs": ["Megaloblastic anemia with low folate or B12", "Negative tissue transglutaminase IgA"], "imaging": ["Small bowel biopsy shows villous atrophy but no response to gluten withdrawal"]}}, {"name": "Whipple disease", "slug": "whipple-disease", "why_considered": "Malabsorption with weight loss, diarrhea, and systemic symptoms", "must_not_miss": true, "trigger": "Arthralgias, fever, and neurologic or cardiac findings with malabsorption", "discriminators": {"history": ["Migratory arthralgias and arthritis", "Fever, night sweats, and lymphadenopathy", "Neurologic symptoms such as memory problems or ophthalmoplegia"], "exam": ["Lymphadenopathy, hyperpigmentation, or cardiac murmur", "Neurologic deficits"], "labs": ["Negative tissue transglutaminase IgA", "PCR or biopsy showing Tropheryma whipplei"], "imaging": ["Small bowel biopsy with PAS-positive macrophages"]}}, {"name": "Giardiasis", "slug": "giardiasis", "why_considered": "Chronic diarrhea, bloating, and malabsorption after exposure to contaminated water", "must_not_miss": false, "discriminators": {"history": ["Recent travel or camping with untreated water", "Acute onset of watery diarrhea followed by weeks of bloating", "No dermatitis herpetiformis"], "exam": ["Mild abdominal tenderness and bloating", "No rash or growth failure"], "labs": ["Stool microscopy or antigen positive for Giardia", "Negative tissue transglutaminase IgA"], "imaging": ["Normal duodenal biopsy or trophozoites seen on biopsy"]}}, {"name": "Small intestinal bacterial overgrowth", "slug": "small-intestinal-bacterial-overgrowth", "why_considered": "Bloating, diarrhea, and malabsorption from bacterial overgrowth", "must_not_miss": false, "discriminators": {"history": ["Prior abdominal surgery, stricture, or motility disorder", "Symptoms may improve with antibiotics", "No gluten-dependent pattern"], "exam": ["Bloating and diffuse tenderness", "Signs of vitamin deficiency"], "labs": ["Positive hydrogen or methane breath test", "Negative tissue transglutaminase IgA"], "imaging": ["Normal duodenal biopsy or nonspecific inflammation"]}}], "course": {"severity": {"mild": "Subtle or intermittent symptoms such as bloating, fatigue, or mild diarrhea; anemia may be the only laboratory clue; no significant weight loss or nutritional deficiency", "moderate": "Persistent diarrhea, abdominal pain, and bloating with weight loss, iron-deficiency anemia, or low albumin; daily activities affected", "severe": "Marked weight loss, cachexia, hypoalbuminemia, hypocalcemia, multiple vitamin deficiencies, and bone loss; may require hospitalization for nutritional support", "critical": "Rare life-threatening presentations such as severe dehydration, electrolyte derangement, or refeeding syndrome after prolonged starvation; untreated celiac crisis with profound malnutrition"}, "red_flags": [{"finding": "Bloody diarrhea or nocturnal diarrhea waking from sleep", "meaning": "Suggests inflammatory bowel disease or another cause rather than uncomplicated celiac disease"}, {"finding": "Fever, night sweats, or lymphadenopathy", "meaning": "Raises concern for infection, lymphoma, or Whipple disease"}, {"finding": "Severe weight loss with progressive weakness", "meaning": "Suggests advanced malabsorption or an underlying malignancy such as enteropathy-associated T-cell lymphoma"}, {"finding": "Hypotension, tachycardia, or decreased urine output", "meaning": "Dehydration or severe malnutrition requiring urgent fluid and electrolyte management"}, {"finding": "Persistent symptoms despite a strict gluten-free diet", "meaning": "Consider refractory celiac disease, inadvertent gluten exposure, or an alternative diagnosis"}], "complications": [{"name": "Iron-deficiency anemia", "timing": "any", "seriousness": "minor", "frequency": "common", "clues": ["Fatigue and pallor", "Low ferritin and microcytosis"]}, {"name": "Osteoporosis and osteomalacia", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Bone pain or fragility fracture", "Low bone mineral density on DXA", "Low calcium and elevated alkaline phosphatase"]}, {"name": "Peripheral neuropathy", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Numbness or tingling in the feet", "Reduced vibration or pinprick sensation"]}, {"name": "Infertility and recurrent miscarriage", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Difficulty conceiving", "History of pregnancy loss"]}, {"name": "Enteropathy-associated T-cell lymphoma", "timing": "late", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Worsening symptoms despite a gluten-free diet", "Weight loss, fever, and abdominal pain", "Small bowel mass or ulceration on imaging"]}, {"name": "Refractory celiac disease", "timing": "late", "seriousness": "serious", "frequency": "rare", "clues": ["Persistent villous atrophy and symptoms after at least 12 months of strict gluten-free diet", "Need for immunosuppressive therapy"]}], "special_populations": [{"population": "children", "differences": "Often present with failure to thrive, poor weight gain, irritability, and digestive symptoms; growth charts are essential; extraintestinal symptoms are less common."}, {"population": "older_adults", "differences": "May present with anemia, osteoporosis, or neuropathy without prominent diarrhea; higher risk of bone loss and nutritional deficiency."}, {"population": "pregnancy", "differences": "May present with anemia, fatigue, and recurrent miscarriage; symptoms may be attributed to pregnancy; untreated disease increases risk of low birth weight and preterm delivery."}]}, "teaching": {"key_questions": [{"question": "What do your stools look like — are they loose, greasy, bulky, or unusually foul-smelling?", "category": "hpi", "importance": "essential", "looking_for": "Chronic diarrhea or steatorrhea, the classic malabsorption pattern"}, {"question": "How long has this been going on, and is it constant or does it come and go?", "category": "hpi", "importance": "essential", "looking_for": "Chronic symptoms over months to years that wax and wane"}, {"question": "Do your symptoms get worse after eating bread, pasta, cereal, or beer?", "category": "hpi", "importance": "essential", "looking_for": "Gluten-containing foods as a trigger"}, {"question": "Have you lost weight without trying, or has your appetite changed?", "category": "hpi", "importance": "essential", "looking_for": "Unintentional weight loss or poor weight gain in a child"}, {"question": "Have you noticed bloating, gas, or crampy belly pain?", "category": "associated", "importance": "important", "looking_for": "Bloating and crampy abdominal discomfort"}, {"question": "Do you feel tired or short of breath with activity?", "category": "associated", "importance": "important", "looking_for": "Fatigue or exertional dyspnea suggesting anemia"}, {"question": "Have you had an itchy, blistery rash on your elbows, knees, or buttocks?", "category": "associated", "importance": "essential", "looking_for": "Dermatitis herpetiformis"}, {"question": "Do you get mouth sores, or does your tongue feel sore or smooth?", "category": "associated", "importance": "optional", "looking_for": "Aphthous ulcers or atrophic glossitis from nutritional deficiency"}, {"question": "Have you had any bone or joint pain, or broken a bone easily?", "category": "associated", "importance": "important", "looking_for": "Bone pain or fragility suggesting osteopenia or osteomalacia"}, {"question": "Do you have numbness, tingling, or balance problems in your feet?", "category": "ros", "importance": "optional", "looking_for": "Peripheral neuropathy from vitamin deficiency"}, {"question": "Has anyone in your family been diagnosed with celiac disease or another autoimmune condition?", "category": "family", "importance": "essential", "looking_for": "First-degree relative with celiac disease or associated autoimmunity"}, {"question": "Do you have type 1 diabetes, thyroid disease, or a genetic condition like Down or Turner syndrome?", "category": "pmh", "importance": "important", "looking_for": "Conditions strongly associated with celiac disease"}, {"question": "Have you already started a gluten-free diet or tried removing gluten on your own?", "category": "hpi", "importance": "essential", "looking_for": "Prior gluten restriction, which can cause false-negative serology and biopsy"}, {"question": "Have you had any fevers, night sweats, or diarrhea that wakes you from sleep?", "category": "red_flag", "importance": "important", "looking_for": "Features that argue against uncomplicated celiac disease and suggest infection, IBD, or malignancy"}, {"question": "Have you had trouble getting pregnant or had miscarriages?", "category": "obstetric", "importance": "optional", "looking_for": "Infertility or recurrent pregnancy loss associated with untreated disease"}], "accepted_names": ["Celiac disease", "Celiac sprue", "Gluten-sensitive enteropathy", "Nontropical sprue", "Coeliac disease"], "reasoning_points": ["Chronic diarrhea with greasy, bulky, foul-smelling stools and bloating suggesting malabsorption", "Unintentional weight loss, fatigue, or iron-deficiency anemia", "Symptoms provoked by gluten-containing foods and relieved by gluten avoidance", "Associated autoimmune or genetic conditions such as type 1 diabetes, thyroid disease, Down syndrome, or Turner syndrome", "Family history of celiac disease in a first-degree relative", "Dermatitis herpetiformis on extensor surfaces supports the diagnosis", "Positive IgA tissue transglutaminase with a normal total IgA, or positive endomysial antibody", "Duodenal biopsy showing villous atrophy, crypt hyperplasia, and increased intraepithelial lymphocytes", "Testing performed while the patient is still eating gluten, since a gluten-free diet causes false-negative results", "Alternative causes of chronic diarrhea and malabsorption considered and excluded"], "difficulty": {"easy": ["Young adult or child with chronic diarrhea, bloating, and weight loss", "Symptoms clearly worse after wheat, barley, or rye", "Iron-deficiency anemia and low albumin on labs", "Positive tissue transglutaminase IgA", "First-degree relative with celiac disease"], "medium": ["Adult with anemia or osteoporosis but little or no diarrhea", "Itchy blistering rash on elbows and knees without prominent GI symptoms", "Symptoms attributed to irritable bowel syndrome for years", "Associated type 1 diabetes or autoimmune thyroid disease", "IgA deficiency making the usual serology falsely negative"], "hard": ["Older adult presenting only with neuropathy or bone loss", "Patient already eating gluten-free, causing negative serology and biopsy", "Child with failure to thrive and irritability but no classic diarrhea", "Pregnant patient with anemia and recurrent miscarriage", "Persistent symptoms despite a strict gluten-free diet, raising concern for refractory disease or lymphoma"]}}}$rounds_kb$::jsonb)
