insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$cellulitis$rounds_kb$, $rounds_kb$Cellulitis$rounds_kb$, $rounds_kb$emergency$rounds_kb$, array[$rounds_kb$emergency$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$surgery$rounds_kb$]::text[], array[$rounds_kb$musculoskeletal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "cellulitis", "triage": {"name": "Cellulitis", "case_suitable": true, "reason": "Acute spreading skin infection with fever and erythema; diagnosis is clinical and mimics DVT and necrotizing infection, a strong teaching case.", "kind": "disease", "category": "skin and soft tissue infection", "organ_systems": ["musculoskeletal"], "primary_clerkship": "emergency", "secondary_clerkships": ["internalMedicine", "familyMedicine", "surgery"], "commonness": "very_common", "settings": ["emergency", "clinic", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:21Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:34Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:40Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:52:49Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:53:03Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:53:10Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'ct of the affected area with iv