routine evaluation"}, {"test": "esr", "why": "Nonspecific and does not change management"}, {"test": "lipase", "why": "No role in dyspnea or chronic cough"}, {"test": "ua", "why": "No role unless a urinary infection is suspected"}], "decision_points": ["Confirm airflow obstruction with post-bronchodilator spirometry before labeling the disease COPD", "A normal chest x-ray does not exclude chronic bronchitis", "Consider alpha-1 antitrypsin testing once in every patient with COPD", "An arterial blood gas is needed when SpO2 is below 90% or CO2 retention is suspected", "Do not use supplemental oxygen to blunt dyspnea without checking for CO2 retention in known hypercapnia"], "criteria": [{"name": "Clinical definition of chronic bronchitis", "summary": "A chronic productive cough on most days for at least 3 months a year for 2 consecutive years, with other causes of chronic cough excluded.", "items": ["Productive cough present on most days", "At least 3 months per year", "For 2 consecutive years", "No alternative explanation for the cough"]}, {"name": "COPD airflow obstruction on spirometry", "summary": "Persistent airflow obstruction demonstrated by a reduced post-bronchodilator FEV1 to FVC ratio.", "items": ["Post-bronchodilator FEV1/FVC below 0.70", "Severity graded by FEV1 percent predicted", "Symptoms and exposure history consistent with COPD"]}], "scores": ["mmrc_dyspnea", "cat_copd", "curb_65"]}, "differential": [{"name": "Asthma", "slug": "asthma", "why_considered": "Chronic cough, wheeze, and chest tightness with reversible airflow obstruction", "must_not_miss": false, "discriminators": {"history": ["Symptoms often begin in childhood or young adulthood", "Episodic attacks with symptom-free intervals", "Worse at night and with allergens, exercise, or cold air", "Personal or family history of atopy, eczema, or allergic rhinitis"], "exam": ["Wheezing during exacerbations with clear lungs between episodes", "No chronic sputum production between attacks"], "labs": ["Eosinophilia on CBC", "Elevated total IgE or positive allergen-specific IgE"], "imaging": ["Normal chest x-ray between attacks"], "ecg": ["Normal sinus rhythm"]}}, {"name": "Heart failure", "slug": "heart-failure", "why_considered": "Dyspnea on exertion, cough, wheeze, and leg swelling in an older adult", "must_not_miss": true, "trigger": "Orthopnea, paroxysmal nocturnal dyspnea, or bilateral crackles that do not clear with coughing", "discriminators": {"history": ["Orthopnea and paroxysmal nocturnal dyspnea", "Chest pain or known coronary disease", "Rapid weight gain from fluid retention"], "exam": ["Bibasilar crackles that persist after coughing", "Elevated jugular venous pressure", "S3 gallop", "Cool extremities or narrow pulse pressure in advanced disease"], "labs": ["BNP or NT-proBNP markedly elevated", "Hyponatremia from volume overload"], "imaging": ["Cardiomegaly, pulmonary venous congestion, or pleural effusions on chest x-ray", "Reduced left ventricular ejection fraction or diastolic dysfunction on echocardiogram"], "ecg": ["Left ventricular hypertrophy", "Left bundle branch block", "Atrial fibrillation"]}}, {"name": "Lung cancer", "slug": "lung-cancer", "why_considered": "Chronic cough in a long-term smoker, sometimes with sputum changes", "must_not_miss": true, "trigger": "Hemoptysis, unexplained weight loss, hoarseness, or a new focal finding on chest imaging", "discriminators": {"history": ["Hemoptysis", "Unintentional weight loss", "Hoarseness or dysphagia", "Symptoms that progress despite inhaler therapy"], "exam": ["Focal wheeze that does not clear with coughing", "Digital clubbing", "Supraclavicular or cervical lymphadenopathy", "Horner syndrome or superior vena cava findings in advanced disease"], "labs": ["Anemia or hypercalcemia", "Elevated alkaline phosphatase if bone metastases"], "imaging": ["Solitary pulmonary nodule, mass, or hilar adenopathy on chest x-ray", "Enlarging or spiculated mass on CT", "Mediastinal lymphadenopathy or pleural effusion"]}}, {"name": "Bronchiectasis", "slug": "bronchiectasis", "why_considered": "Chronic productive cough with daily purulent sputum", "must_not_miss": false, "discriminators": {"history": ["Large volumes of purulent sputum daily", "Recurrent pneumonia in the same lobe", "History of severe childhood respiratory infection or measles", "Hemoptysis"], "exam": ["Coarse crackles at the lung bases", "Halitosis"], "labs": ["Sputum culture growing Pseudomonas aeruginosa or nontuberculous mycobacteria"], "imaging": ["Dilated airways with a signet-ring appearance and tram-track lines on high-resolution CT", "Mucous plugging and tree-in-bud nodularity"]}}, {"name": "Tuberculosis", "slug": "tuberculosis", "why_considered": "Chronic cough with sputum in a patient with risk factors", "must_not_miss": true, "trigger": "Night sweats, fever, weight loss, hemoptysis, or known exposure to tuberculosis", "discriminators": {"history": ["Night sweats and low-grade fever", "Unintentional weight loss", "Immigration from or travel to a high-prevalence country", "Incarceration, shelter residence, or HIV infection"], "exam": ["Upper-lobe crackles or amphoric breath sounds", "Lymphadenopathy"], "labs": ["Positive interferon-gamma release assay or tuberculin skin test", "Acid-fast bacilli on sputum smear", "Positive nucleic acid amplification test for Mycobacterium tuberculosis"], "imaging": ["Upper-lobe infiltrates, cavitation, or miliary pattern on chest x-ray", "Tree-in-bud nodularity and cavitary lesions on CT"]}}, {"name": "Upper airway cough syndrome", "slug": "upper-airway-cough-syndrome", "why_considered": "Chronic cough that is worse when lying down and improves with antihistamines", "must_not_miss": false, "discriminators": {"history": ["Postnasal drip and frequent throat clearing", "Nasal congestion and sneezing", "Cough is the only or predominant symptom", "Improves with intranasal steroids or antihistamines"], "exam": ["Cobblestoning of the posterior pharynx", "Clear nasal discharge or mucosal swelling"], "imaging": ["Normal chest x-ray"]}}, {"name": "Gastroesophageal reflux disease", "slug": "gastroesophageal-reflux-disease", "why_considered": "Chronic cough worsened by lying flat and by meals", "must_not_miss": false, "discriminators": {"history": ["Heartburn and regurgitation", "Cough worse after meals and when supine", "Improves with proton pump inhibitor therapy"], "exam": ["Normal lung examination", "No wheezing"], "labs": ["Normal CBC and inflammatory markers"], "imaging": ["Normal chest x-ray"]}}, {"name": "Alpha-1 antitrypsin deficiency", "slug": "alpha-1-antitrypsin-deficiency", "why_considered": "COPD with chronic bronchitis in a younger patient or with minimal smoking exposure", "must_not_miss": false, "discriminators": {"history": ["COPD before age 45", "Minimal or no smoking history", "Family history of early emphysema or liver disease", "Unexplained liver disease in the patient or a relative"], "exam": ["Early-onset emphysema with basilar predominance", "Signs of liver disease in some patients"], "labs": ["Low serum alpha-1 antitrypsin level", "PI*ZZ or other deficient genotype on phenotyping or genotyping", "Elevated liver enzymes"], "imaging": ["Basilar-predominant emphysema on CT"]}}], "course": {"severity": {"mild": "Chronic productive cough on most days with preserved exercise tolerance; FEV1 at or above 80% predicted; SpO2 94% or higher at rest; no signs of right heart failure", "moderate": "Daily cough and sputum with dyspnea on moderate exertion such as climbing one flight of stairs; FEV1 50 to 79% predicted; SpO2 90 to 95%; occasional exacerbations", "severe": "Dyspnea with minimal activity or at rest; FEV1 30 to 49% predicted; SpO2 85 to 92%; frequent exacerbations; may have peripheral edema, elevated jugular venous pressure, or polycythemia from chronic hypoxemia", "critical": "Acute-on-chronic respiratory failure with acidemia, hypercapnia, and hypoxemia; altered mental status; inability to speak in full sentences; hemodynamic instability; requires noninvasive or invasive ventilation"}, "red_flags": [{"finding": "Acidemia on arterial blood gas in a patient with known CO2 retention", "meaning": "Acute-on-chronic respiratory failure; needs urgent ventilatory support"}, {"finding": "Altered mental status, somnolence, or asterixis", "meaning": "Hypercapnic encephalopathy; impending respiratory failure"}, {"finding": "SpO2 below 88% on room air or new oxygen requirement", "meaning": "Severe hypoxemia; assess for pneumonia, pulmonary embolism, or pneumothorax"}, {"finding": "Hemoptysis", "meaning": "Consider lung cancer, bronchiectasis, or tuberculosis rather than uncomplicated chronic bronchitis"}, {"finding": "Unilateral leg swelling or pleuritic chest pain", "meaning": "Pulmonary embolism until proven otherwise"}, {"finding": "Sudden unilateral pleuritic pain with absent breath sounds", "meaning": "Pneumothorax, which is more common in patients with emphysema"}, {"finding": "Fever with purulent sputum and worsening dyspnea", "meaning": "Acute bacterial exacerbation or pneumonia; needs antibiotics and possibly hospitalization"}, {"finding": "New focal wheeze or focal crackles", "meaning": "Consider endobronchial obstruction from a mass or a retained foreign body"}], "complications": [{"name": "Acute exacerbation of COPD", "timing": "any", "seriousness": "serious", "frequency": "common", "clues": ["Increased sputum volume or purulence", "Worsening dyspnea", "Increased cough and wheeze", "Low-grade fever"]}, {"name": "Acute respiratory failure with hypercapnia", "timing": "any", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["Drowsiness or confusion", "Accessory muscle use", "SpO2 below 88%", "Acidemia on arterial blood gas"]}, {"name": "Bacterial pneumonia", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["High fever", "Focal crackles or consolidation", "Leukocytosis", "New infiltrate on chest x-ray"]}, {"name": "Cor pulmonale and right heart failure", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Bilateral pitting edema", "Elevated jugular venous pressure", "Right ventricular dilation on echocardiogram", "Elevated BNP"]}, {"name": "Secondary polycythemia from chronic hypoxemia", "timing": "late", "seriousness": "minor", "frequency": "sometimes", "clues": ["Elevated hemoglobin and hematocrit", "Plethora", "Headache"]}, {"name": "Pneumothorax", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Sudden unilateral pleuritic chest pain", "Absent breath sounds on one side", "Tracheal deviation in tension pneumothorax"]}, {"name": "Pulmonary hypertension", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Exertional dyspnea out of proportion to spirometry", "Loud P2", "Prominent central pulmonary arteries on chest x-ray"]}, {"name": "Depression and anxiety", "timing": "late", "seriousness": "minor", "frequency": "common", "clues": ["Low mood", "Poor sleep", "Reduced activity", "Social withdrawal"]}, {"name": "Osteoporosis from chronic steroid use", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Back pain", "Loss of height", "Fragility fracture"]}], "special_populations": [{"population": "older_adults", "differences": "Symptoms may be attributed to normal aging or heart disease; activity limitation may be the presenting complaint rather than cough. Comorbid heart failure and coronary disease are common and can mimic or worsen dyspnea."}, {"population": "pregnancy", "differences": "Increasing dyspnea may be attributed to normal pregnancy changes, delaying recognition of worsening lung disease. Smoking cessation support is a priority; hypoxemia threatens both mother and fetus."}, {"population": "immunocompromised", "differences": "Recurrent chest infections may dominate the picture and the chronic cough may be attributed to infection rather than underlying airway disease. Consider atypical organisms and evaluate for bronchiectasis."}, {"population": "obesity", "differences": "Reduced chest wall compliance and deconditioning worsen dyspnea; obesity hypoventilation can add to CO2 retention and complicate interpretation of blood gases."}, {"population": "diabetes", "differences": "Systemic corticosteroids used during exacerbations cause hyperglycemia; monitor glucose closely and adjust therapy."}]}, "teaching": {"key_questions": [{"question": "How long have you had this cough, and does it bring up phlegm?", "category": "hpi", "importance": "essential", "looking_for": "Productive cough on most days for at least 3 months a year for 2 or more years"}, {"question": "Is the cough there every day, or does it come and go?", "category": "hpi", "importance": "essential", "looking_for": "Chronic daily pattern rather than episodic attacks with symptom-free intervals"}, {"question": "When during the day is the cough worst?", "category": "hpi", "importance": "important", "looking_for": "Worst in the morning after waking and when lying down"}, {"question": "What does the sputum look like?", "category": "hpi", "importance": "important", "looking_for": "Clear, white, or gray most days; yellow or green during flare-ups"}, {"question": "Do you get short of breath? With what level of activity?", "category": "hpi", "importance": "essential", "looking_for": "Exertional dyspnea that has crept in after years of cough; grades activity tolerance"}, {"question": "Do you smoke or have you ever smoked? How much and for how many years?", "category": "social", "importance": "essential", "looking_for": "Current or former cigarette use, often 20 or more pack-years"}, {"question": "Have you been exposed to dusts, fumes, or chemicals at work, or to secondhand smoke at home?", "category": "social", "importance": "important", "looking_for": "Occupational or household inhaled irritants that add to the smoking risk"}, {"question": "Have you coughed up any blood?", "category": "red_flag", "importance": "essential", "looking_for": "Absent; hemoptysis points to cancer, bronchiectasis, or tuberculosis"}, {"question": "Have you lost weight without trying, or had night sweats or fevers between flare-ups?", "category": "red_flag", "importance": "essential", "looking_for": "Absent; present suggests malignancy, tuberculosis, or another chronic infection"}, {"question": "Do you wake up at night short of breath, or need extra pillows to sleep?", "category": "associated", "importance": "important", "looking_for": "Absent; orthopnea and paroxysmal nocturnal dyspnea point to heart failure"}, {"question": "Have you noticed swelling in your ankles or legs?", "category": "associated", "importance": "important", "looking_for": "Bilateral swelling in advanced disease suggests cor pulmonale; one-sided swelling suggests DVT"}, {"question": "How many chest colds or flare-ups have you had in the past year, and have you needed antibiotics or steroids?", "category": "hpi", "importance": "important", "looking_for": "Frequent exacerbations, which drive management and prognosis"}, {"question": "What inhalers or other breathing medicines do you use, and do they help?", "category": "medications", "importance": "important", "looking_for": "Bronchodilator use with partial relief; steroid inhalers in more severe disease"}, {"question": "Have you had your flu and pneumococcal vaccines?", "category": "pmh", "importance": "optional", "looking_for": "Up-to-date immunizations, which reduce exacerbations"}, {"question": "Does anyone in your family have COPD, emphysema, or liver disease at a young age?", "category": "family", "importance": "optional", "looking_for": "Family history suggesting alpha-1 antitrypsin deficiency"}, {"question": "Has your cough changed recently, or is it worse than it has ever been?", "category": "red_flag", "importance": "important", "looking_for": "A change in a stable chronic pattern, which should prompt evaluation for a new problem"}], "accepted_names": ["Chronic bronchitis", "COPD with chronic bronchitis", "Chronic obstructive pulmonary disease, bronchitis-predominant", "Type B COPD", "COPD, chronic bronchitis phenotype"], "reasoning_points": ["Productive cough on most days for at least 3 months a year for 2 consecutive years", "Other causes of chronic cough excluded (asthma, upper airway cough syndrome, reflux, infection, malignancy)", "Long-term cigarette smoke exposure, often 20 or more pack-years", "Typical age of onset in the 40s or later, with gradual worsening over years", "Cough worst in the morning and with cold air or infections", "Spirometry showing persistent post-bronchodilator airflow obstruction with FEV1/FVC below 0.70", "Chest imaging without a mass, infiltrate, or other alternative explanation", "No hemoptysis, weight loss, night sweats, or fever between flare-ups"], "difficulty": {"easy": ["Long-time smoker over 40 with a daily morning productive cough for years", "Sputum is clear to white and worse in the morning", "Diffuse expiratory wheezing and a prolonged expiratory phase on exam", "Spirometry shows post-bronchodilator FEV1/FVC below 0.70"], "medium": ["Patient dismisses the cough as a 'smoker's cough' and reports only exertional dyspnea", "Coexisting heart failure or asthma makes the cause of dyspnea ambiguous", "Older adult whose activity limitation is attributed to aging", "Chest x-ray is normal, which does not exclude the diagnosis"], "hard": ["Younger patient or one with minimal smoking history, raising concern for alpha-1 antitrypsin deficiency", "Chronic cough with purulent sputum and recurrent same-lobe pneumonias suggesting bronchiectasis", "Smoker with hemoptysis or weight loss requiring evaluation for lung cancer", "Acute-on-chronic presentation with hypercapnia and acidemia obscuring the underlying chronic disease", "Immunocompromised patient whose recurrent infections dominate the picture"]}}}$rounds_kb$::jsonb)
