insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$concussion$rounds_kb$, $rounds_kb$Concussion$rounds_kb$, $rounds_kb$emergency$rounds_kb$, array[$rounds_kb$emergency$rounds_kb$, $rounds_kb$neurology$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$nervous$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "concussion", "triage": {"name": "Concussion", "case_suitable": true, "reason": "Common head injury with characteristic history and exam; diagnosis reachable clinically with important red flags to exclude.", "kind": "injury", "category": "traumatic brain injury", "organ_systems": ["nervous"], "primary_clerkship": "emergency", "secondary_clerkships": ["neurology", "pediatrics", "familyMedicine"], "commonness": "very_common", "settings": ["emergency", "clinic", "pediatric_clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:40Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:58:08Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:58:20Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:58:26Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:58:37Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:58:43Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'mri brain without contrast' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'mri brain without contrast' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential epidural-hematoma: no profile yet", "differential subdural-hematoma: no profile yet", "differential subarachnoid-hemorrhage: no profile yet", "differential cervical-spine-injury: no profile yet", "differential post-traumatic-migraine: no profile yet", "differential acute-stress-reaction: no profile yet", "differential benign-paroxysmal-positional-vertigo: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 5, "typical_max": 65, "peak": "bimodal: adolescents/young adults (15–25) and older adults (65+)", "possible_min": 0, "possible_max": 110}, "sex": "either", "demographics": ["More common in males, especially adolescents and young adults, reflecting higher rates of contact sports and risk-taking injuries", "Older adults have higher rates of concussion from falls, often with more severe consequences", "Children and adolescents are frequently affected, particularly in organized sports"], "risk_factors": [{"text": "Participation in contact or collision sports (e.g., football, soccer, hockey, basketball)", "strength": "strong"}, {"text": "Prior concussion", "strength": "strong"}, {"text": "Age extremes (young children, older adults)", "strength": "moderate"}, {"text": "Male sex", "strength": "weak"}, {"text": "History of falls or gait instability", "strength": "moderate"}, {"text": "Lack of protective equipment (helmet use)", "strength": "moderate"}], "comorbidities": ["Migraine or other headache disorders", "Attention-deficit/hyperactivity disorder (ADHD)", "Learning disabilities", "Mood disorders (anxiety, depression)", "Balance disorders", "Coagulopathy or anticoagulant use (increases risk of intracranial hemorrhage)"], "family_history": [], "social_history": ["Athletic participation", "Military service", "High-risk occupations (construction, law enforcement)"], "exposures": ["Blunt head trauma", "Rapid acceleration-deceleration forces (e.g., whiplash, blast injury)"], "risk_medications": ["anticoagulants (e.g., warfarin, apixaban, rivaroxaban)", "antiplatelet agents (e.g., aspirin, clopidogrel)"]}, "presentation": {"chief_complaints": [{"text": "I hit my head and now I have a headache", "frequency": "almost_always"}, {"text": "I feel dizzy and foggy", "frequency": "common"}, {"text": "I feel nauseous", "frequency": "common"}, {"text": "I can't remember what happened", "frequency": "sometimes"}], "hpi": {"onset": "Sudden, immediately after a blow to the head or body; symptoms may not be noticed until hours later", "duration": "Symptoms typically last days to weeks; most resolve within 7–10 days but can persist for months", "progression": "Symptoms begin immediately or within hours; may worsen over the first 24–48 hours, then gradually improve", "location": "Headache is usually generalized or frontal; neck pain may be present", "radiation": "Headache may radiate to the neck or behind the eyes", "quality": "Headache is typically pressure-like or throbbing; dizziness is described as lightheadedness or a spinning sensation", "severity": "Variable; headache often moderate (4–7/10), but can be severe", "timing": "Headache is often constant, worsened by physical or cognitive exertion", "aggravating": ["Physical exertion", "Mental concentration (e.g., reading, screen time)", "Bright lights", "Loud noises", "Rapid head movements"], "relieving": ["Rest in a dark, quiet room", "Sleep", "Acetaminophen or ibuprofen (may help headache but must be used cautiously)"], "associated_symptoms": [{"text": "Headache", "frequency": "almost_always"}, {"text": "Dizziness or balance problems", "frequency": "common"}, {"text": "Nausea", "frequency": "common"}, {"text": "Feeling mentally foggy or slowed down", "frequency": "common"}, {"text": "Difficulty concentrating", "frequency": "common"}, {"text": "Sensitivity to light (photophobia)", "frequency": "common"}, {"text": "Sensitivity to noise (phonophobia)", "frequency": "common"}, {"text": "Fatigue or low energy", "frequency": "common"}, {"text": "Blurred or double vision", "frequency": "sometimes"}, {"text": "Memory problems (amnesia around the event)", "frequency": "sometimes"}, {"text": "Sleep disturbances (sleeping more or less than usual)", "frequency": "sometimes"}, {"text": "Irritability or mood changes", "frequency": "sometimes"}, {"text": "Ringing in the ears (tinnitus)", "frequency": "sometimes"}, {"text": "Loss of consciousness (brief, seconds to minutes)", "frequency": "sometimes"}, {"text": "Vomiting", "frequency": "sometimes"}, {"text": "Neck pain", "frequency": "sometimes"}], "pertinent_negatives": ["Loss of consciousness lasting more than a few minutes", "Seizure or convulsion", "Repeated vomiting", "Severe or worsening headache", "Weakness or numbness in arms or legs", "Slurred speech", "Confusion or agitation that worsens", "Inability to wake up", "Clear fluid or blood from nose or ears", "Focal neurological deficit"]}, "ros": [{"system": "neurologic", "positives": [{"text": "Headache", "frequency": "almost_always"}, {"text": "Dizziness", "frequency": "common"}, {"text": "Balance problems", "frequency": "common"}, {"text": "Difficulty concentrating", "frequency": "common"}, {"text": "Memory problems", "frequency": "sometimes"}, {"text": "Blurred vision", "frequency": "sometimes"}, {"text": "Sensitivity to light", "frequency": "common"}, {"text": "Sensitivity to noise", "frequency": "common"}], "negatives": ["Seizures", "Focal weakness", "Numbness", "Slurred speech", "Loss of consciousness >1 minute"], "argues_against": ["Focal neurological deficit suggests structural brain injury (e.g., hemorrhage, stroke)", "Seizure suggests more severe injury"]}, {"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "common"}, {"text": "Sleep disturbances", "frequency": "sometimes"}], "negatives": ["Fever", "Chills", "Weight loss"], "argues_against": ["Fever suggests infection (e.g., meningitis)"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea", "frequency": "common"}, {"text": "Vomiting (usually once)", "frequency": "sometimes"}], "negatives": ["Repeated vomiting", "Abdominal pain", "Blood in vomit"], "argues_against": ["Repeated vomiting suggests increased intracranial pressure"]}, {"system": "psychiatric", "positives": [{"text": "Irritability", "frequency": "sometimes"}, {"text": "Mood changes", "frequency": "sometimes"}, {"text": "Anxiety", "frequency": "sometimes"}], "negatives": ["Suicidal ideation", "Hallucinations"], "argues_against": ["Primary psychiatric disorder"]}, {"system": "eyes", "positives": [{"text": "Blurred vision", "frequency": "sometimes"}, {"text": "Double vision", "frequency": "sometimes"}, {"text": "Light sensitivity", "frequency": "common"}], "negatives": ["Vision loss", "Eye pain"], "argues_against": ["Primary ocular injury"]}, {"system": "ent", "positives": [{"text": "Ringing in the ears", "frequency": "sometimes"}, {"text": "Sensitivity to noise", "frequency": "common"}], "negatives": ["Ear drainage", "Hearing loss"], "argues_against": ["Basilar skull fracture (CSF otorrhea)"]}, {"system": "musculoskeletal", "positives": [{"text": "Neck pain", "frequency": "sometimes"}], "negatives": ["Neck stiffness", "Arm or leg weakness"], "argues_against": ["Cervical spine injury"]}], "atypical": [{"population": "children", "how_it_differs": "Young children may not report headache or dizziness; they may present with irritability, crying, vomiting, changes in sleep or eating, loss of interest in toys, or unsteady walking. They may be unable to describe amnesia or confusion.", "missing_classic_features": ["Verbal report of headache", "Clear description of amnesia", "Dizziness"]}, {"population": "older_adults", "how_it_differs": "Older adults may have subtle symptoms, and concussion can mimic dementia or delirium. They are at higher risk of intracranial hemorrhage, so a lower threshold for imaging is used. Symptoms like headache may be less prominent, while confusion or balance problems may dominate.", "missing_classic_features": ["Severe headache", "Clear loss of consciousness"]}, {"population": "infants", "how_it_differs": "Infants may present with inconsolable crying, vomiting, poor feeding, lethargy, or irritability. A history of trauma may be absent or unclear. Non-accidental trauma should be considered.", "missing_classic_features": ["Verbal report of symptoms", "Amnesia", "Headache"]}]}, "exam": {"general": {"mild": "Alert, oriented, appears well; may be slightly slowed or uncomfortable but not toxic", "moderate": "Dazed or foggy, mild distress, may be photophobic or holding head", "severe": "Ill-appearing, drowsy but arousable, may vomit or have significant headache", "critical": "Lethargic, difficult to arouse, focal deficits, or signs of herniation (e.g., unequal pupils, posturing)"}, "findings": [{"id": "gcs-normal", "region": "mental_status", "maneuver": "Assess level of consciousness using Glasgow Coma Scale", "finding": "GCS 15 (alert, oriented, follows commands)", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "gcs-mildly-reduced", "region": "mental_status", "maneuver": "Assess level of consciousness using Glasgow Coma Scale", "finding": "GCS 13–14 (mildly confused or drowsy)", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "gcs-severely-reduced", "region": "mental_status", "maneuver": "Assess level of consciousness using Glasgow Coma Scale", "finding": "GCS ≤12 (moderate to severe impairment)", "frequency": "rare", "min_severity": "severe", "significance": "strongly_supports", "importance": "essential"}, {"id": "confusion", "region": "mental_status", "maneuver": "Ask orientation questions (person, place, time, situation)", "finding": "Disorientation or confusion", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "amnesia", "region": "mental_status", "maneuver": "Ask about memory of the event and events immediately before/after", "finding": "Retrograde or anterograde amnesia", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "pupils-equal-reactive", "region": "heent", "maneuver": "Shine light into each eye and observe pupillary response", "finding": "Pupils equal, round, reactive to light", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "pupil-asymmetry", "region": "heent", "maneuver": "Shine light into each eye and observe pupillary response", "finding": "Anisocoria or sluggish/unreactive pupil", "frequency": "rare", "min_severity": "severe", "significance": "argues_against", "importance": "essential"}, {"id": "extraocular-movements-intact", "region": "heent", "maneuver": "Ask patient to follow finger in all directions (H-test)", "finding": "Full extraocular movements without diplopia or nystagmus", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "nystagmus", "region": "heent", "maneuver": "Observe for nystagmus during extraocular movements or with gaze fixation", "finding": "Nystagmus", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "visual-acuity-normal", "region": "heent", "maneuver": "Check visual acuity with Snellen chart or bedside card", "finding": "Visual acuity at baseline (no new deficit)", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "facial-symmetry", "region": "neuro", "maneuver": "Ask patient to smile and show teeth", "finding": "Symmetric facial movement", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "facial-weakness", "region": "neuro", "maneuver": "Ask patient to smile and show teeth", "finding": "Facial droop or asymmetry", "frequency": "rare", "min_severity": "severe", "significance": "argues_against", "importance": "essential"}, {"id": "motor-strength-normal", "region": "extremities", "maneuver": "Test strength in all four extremities (e.g., shoulder abduction, grip, hip flexion, foot dorsiflexion)", "finding": "Full strength (5/5) in all extremities", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "focal-weakness", "region": "extremities", "maneuver": "Test strength in all four extremities", "finding": "Focal weakness in one or more extremities", "frequency": "rare", "min_severity": "severe", "significance": "argues_against", "importance": "essential"}, {"id": "sensation-intact", "region": "neuro", "maneuver": "Test light touch and pinprick sensation in all extremities", "finding": "Sensation intact and symmetric", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "sensory-deficit", "region": "neuro", "maneuver": "Test light touch and pinprick sensation in all extremities", "finding": "Focal sensory loss", "frequency": "rare", "min_severity": "severe", "significance": "argues_against", "importance": "essential"}, {"id": "reflexes-normal", "region": "neuro", "maneuver": "Test deep tendon reflexes (biceps, brachioradialis, patellar, Achilles)", "finding": "Reflexes 2+ and symmetric", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "reflex-asymmetry", "region": "neuro", "maneuver": "Test deep tendon reflexes", "finding": "Asymmetric or hyperactive reflexes", "frequency": "rare", "min_severity": "severe", "significance": "argues_against", "importance": "important"}, {"id": "coordination-normal", "region": "neuro", "maneuver": "Perform finger-to-nose and heel-to-shin testing", "finding": "No dysmetria or ataxia", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "coordination-abnormal", "region": "neuro", "maneuver": "Perform finger-to-nose and heel-to-shin testing", "finding": "Dysmetria or ataxia", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "gait-normal", "region": "musculoskeletal", "maneuver": "Observe gait and ask patient to walk a few steps", "finding": "Normal gait and balance", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "gait-unsteady", "region": "musculoskeletal", "maneuver": "Observe gait and ask patient to walk a few steps", "finding": "Unsteady or wide-based gait", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "romberg-negative", "region": "neuro", "maneuver": "Ask patient to stand with feet together and eyes closed (Romberg test)", "finding": "No increased sway or loss of balance", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "romberg-positive", "region": "neuro", "maneuver": "Ask patient to stand with feet together and eyes closed (Romberg test)", "finding": "Increased sway or tendency to fall", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "neck-supple", "region": "neck", "maneuver": "Assess neck range of motion and palpate for tenderness", "finding": "Supple neck, no midline tenderness, full range of motion", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "neck-tenderness", "region": "neck", "maneuver": "Palpate the posterior midline of the neck", "finding": "Midline cervical spine tenderness", "frequency": "sometimes", "significance": "argues_against", "importance": "essential"}, {"id": "no-csf-leak", "region": "heent", "maneuver": "Inspect nose and ears for clear fluid or blood", "finding": "No CSF rhinorrhea or otorrhea, no hemotympanum", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "csf-leak", "region": "heent", "maneuver": "Inspect nose 