"system": "musculoskeletal", "positives": [{"text": "Weakness in the legs", "frequency": "sometimes"}], "negatives": ["Joint swelling", "Muscle pain"]}, {"system": "psychiatric", "positives": [{"text": "Anxiety about breathing", "frequency": "common"}, {"text": "Low mood", "frequency": "sometimes"}], "negatives": ["Suicidal ideation"]}]}, "exam": {"general": {"mild": "Comfortable at rest, speaks in full sentences, no distress", "moderate": "Mildly tachypneic with exertion, speaks in full sentences at rest, pursed-lip breathing may be seen", "severe": "Sits upright and leans forward, pursed-lip breathing, speaks in short phrases, barrel chest", "critical": "Accessory muscle use, tripod positioning, speaks in words, may be confused or drowsy"}, "findings": [{"id": "barrel-chest", "region": "lung", "maneuver": "Inspect the chest from the side and front", "finding": "Increased anteroposterior diameter (barrel chest)", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "prolonged-expiration", "region": "lung", "maneuver": "Auscultate and observe the respiratory cycle", "finding": "Prolonged expiratory phase", "frequency": "almost_always", "significance": "supports", "importance": "essential"}, {"id": "wheezing", "region": "lung", "maneuver": "Auscultate all lung fields during quiet and forced breathing", "finding": "Diffuse expiratory wheezing", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "decreased-breath-sounds", "region": "lung", "maneuver": "Auscultate the lung bases", "finding": "Diminished breath sounds, especially at the bases", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "crackles", "region": "lung", "maneuver": "Auscultate the lung bases", "finding": "Coarse crackles that may clear with cough", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "hyperresonance", "region": "lung", "maneuver": "Percuss the posterior chest", "finding": "Hyperresonance to percussion", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "accessory-muscle-use", "region": "general", "maneuver": "Observe the patient's breathing at rest", "finding": "Use of sternocleidomastoid and intercostal muscles", "frequency": "common", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "pursed-lip-breathing", "region": "general", "maneuver": "Observe the patient's breathing pattern", "finding": "Pursed-lip breathing", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "tripod-position", "region": "general", "maneuver": "Observe the patient's posture", "finding": "Leaning forward with arms braced on knees or table", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "digital-clubbing", "region": "extremities", "maneuver": "Inspect the fingers", "finding": "Clubbing is absent", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "peripheral-edema", "region": "extremities", "maneuver": "Press the dorsum of each foot and the lower leg", "finding": "Pitting edema of the ankles and feet", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "optional"}, {"id": "cyanosis", "region": "general", "maneuver": "Inspect the lips and nail beds", "finding": "Central or peripheral cyanosis", "frequency": "rare", "min_severity": "critical", "significance": "supports", "importance": "important"}, {"id": "altered-mental-status", "region": "mental_status", "maneuver": "Assess orientation and level of alertness", "finding": "Confusion, somnolence, or agitation suggesting hypercapnia", "frequency": "rare", "min_severity": "critical", "significance": "strongly_supports", "impor