insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$crohn-s-disease$rounds_kb$, $rounds_kb$Crohn's Disease$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$surgery$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$gastrointestinal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "crohn-s-disease", "triage": {"name": "Crohn's Disease", "case_suitable": true, "reason": "Chronic inflammatory bowel disease with abdominal pain, diarrhea and weight loss; diagnosis reached by history, exam, labs, imaging and endoscopy.", "kind": "disease", "category": "inflammatory bowel disease", "organ_systems": ["gastrointestinal"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["surgery", "pediatrics", "familyMedicine", "emergency"], "commonness": "common", "settings": ["clinic", "inpatient", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:50Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:44:36Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:44:44Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:44:58Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:45:13Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:45:20Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'abdominal x-ray (supine and upright)' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'abdominal x-ray (supine and upright)' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential ulcerative-colitis: no profile yet", "differential intestinal-tuberculosis: no profile yet", "differential infectious-colitis: no profile yet", "differential irritable-bowel-syndrome: no profile yet", "differential behcet-disease: no profile yet", "differential diverticulitis: no profile yet", "differential ischemic-colitis: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 15, "typical_max": 40, "peak": "bimodal: late teens to 20s and a second smaller peak in the 50s to 60s", "possible_min": 2, "possible_max": 90}, "sex": "either", "demographics": ["Slightly more common in females in some series, but overall affects both sexes similarly", "More common in people of Ashkenazi Jewish ancestry", "More common in developed countries and in urban areas", "Higher incidence in northern latitudes", "More common in White populations, though it occurs in all races and ethnicities"], "risk_factors": [{"text": "Family history of inflammatory bowel disease in a first-degree relative", "strength": "strong"}, {"text": "Cigarette smoking (current or past)", "strength": "strong"}, {"text": "Ashkenazi Jewish ancestry", "strength": "moderate"}, {"text": "Young adulthood (late teens to 20s)", "strength": "moderate"}, {"text": "Use of NSAIDs such as ibuprofen or aspirin", "strength": "weak"}, {"text": "Use of oral contraceptive pills", "strength": "weak"}, {"text": "High-fat or Western diet", "strength": "weak"}, {"text": "Prior antibiotic use", "strength": "weak"}], "comorbidities": ["Primary sclerosing cholangitis", "Ankylosing spondylitis or sacroiliitis", "Psoriasis", "Venous thromboembolism", "Osteoporosis", "Anxiety or depression"], "family_history": ["Crohn's disease or ulcerative colitis in a parent, sibling, or child", "Other autoimmune disease in the family"], "social_history": ["Current or former smoking", "Stress and certain foods may worsen symptoms but do not cause the disease"], "exposures": [], "risk_medications": ["ibuprofen", "naproxen", "aspirin", "oral contraceptive pills", "antibiotics"]}, "presentation": {"chief_complaints": [{"text": "I keep having diarrhea", "frequency": "almost_always"}, {"text": "My belly cramps and hurts", "frequency": "almost_always"}, {"text": "I've been losing weight without trying", "frequency": "common"}, {"text": "I'm exhausted all the time", "frequency": "common"}, {"text": "I have pain around my bottom", "frequency": "sometimes"}], "hpi": {"onset": "Gradual, with intermittent symptoms that come and go over weeks to months", "duration": "Often present for weeks to months before diagnosis; may have had milder episodes for longer", "progression": "Symptoms wax and wane in flares; diarrhea and cramping become more frequent and weight loss accumulates over time", "location": "Diffuse or lower abdominal cramping, often right lower quadrant or periumbilical", "radiation": "Usually none; pain may be referred to the back with severe inflammation", "quality": "Crampy, colicky abdominal pain; diarrhea is often loose to watery and may be urgent", "severity": "Moderate; pain 4–7/10 during flares, milder between flares", "timing": "Pain often comes in waves before a bowel movement and eases afterward; diarrhea may wake the patient at night", "aggravating": ["Eating, especially high-fiber or fatty foods", "Stress", "Smoking", "NSAIDs"], "relieving": ["Having a bowel movement", "Eating smaller, low-fiber meals", "Rest"], "associated_symptoms": [{"text": "Fatigue", "frequency": "common"}, {"text": "Loss of appetite", "frequency": "common"}, {"text": "Low-grade fever", "frequency": "sometimes"}, {"text": "Nausea", "frequency": "sometimes"}, {"text": "Mouth sores or ulcers", "frequency": "sometimes"}, {"text": "Joint pain or soreness", "frequency": "sometimes"}, {"text": "Eye redness or pain", "frequency": "rare"}, {"text": "Red, tender bumps under the skin, often on the shins", "frequency": "rare"}, {"text": "Anal pain, itching, or drainage", "frequency": "sometimes"}], "pertinent_negatives": ["Bloody diarrhea as the main symptom", "Tenesmus (constant feeling of needing to pass stool)", "Recent travel or sick contacts with similar diarrhea", "Antibiotic use before symptoms started", "Weight gain or unchanged weight", "Nocturnal diarrhea is present in Crohn's but bloody stools are less typical than in ulcerative colitis"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "common"}, {"text": "Low-grade fever", "frequency": "sometimes"}, {"text": "Unintentional weight loss", "frequency": "common"}], "negatives": ["High fever with chills", "Night sweats"], "argues_against": ["Acute infectious colitis"]}, {"system": "gastrointestinal", "positives": [{"text": "Chronic diarrhea", "frequency": "almost_always"}, {"text": "Abdominal cramping", "frequency": "almost_always"}, {"text": "Urgency to have a bowel movement", "frequency": "common"}, {"text": "Mouth ulcers", "frequency": "sometimes"}, {"text": "Perianal pain or drainage", "frequency": "sometimes"}], "negatives": ["Bloody stools as the predominant symptom", "Tenesmus", "Jaundice"], "argues_against": ["Ulcerative colitis", "Infectious gastroenteritis"]}, {"system": "musculoskeletal", "positives": [{"text": "Joint pain or swelling", "frequency": "sometimes"}], "negatives": ["Morning stiffness lasting more than an hour", "Back pain that wakes the patient at night"], "argues_against": ["Ankylosing spondylitis as the sole diagnosis"]}, {"system": "skin", "positives": [{"text": "Red, tender bumps on the shins", "frequency": "rare"}, {"text": "Painful skin ulcers", "frequency": "rare"}], "negatives": ["Rash after starting a new medication", "Itchy hives"], "argues_against": ["Drug reaction"]}, {"system": "eyes", "positives": [{"text": "Eye redness or pain", "frequency": "rare"}], "negatives": ["Vision loss", "Eye discharge"], "argues_against": ["Infectious conjunctivitis"]}, {"system": "hematologic", "positives": [{"text": "Pallor or easy fatigue from anemia", "frequency": "sometimes"}], "negatives": ["Easy bruising", "Bleeding gums"], "argues_against": ["Primary hematologic malignancy"]}], "atypical": [{"population": "children", "how_it_differs": "Children may present with growth failure, delayed puberty, and poor weight gain rather than prominent diarrhea or pain.", "missing_classic_features": ["Chronic diarrhea", "Abdominal pain"]}, {"population": "older_adults", "how_it_differs": "Presentation may be milder or mistaken for diverticular disease or ischemic colitis; a second peak occurs in the 50s to 60s.", "missing_classic_features": ["Young age at onset", "Family history"]}, {"population": "pregnancy", "how_it_differs": "Symptoms may flare or remit; active disease increases risk of preterm birth and low birth weight, and some medications need adjustment.", "missing_classic_features": ["Typical waxing and waning pattern"]}, {"population": "immunocompromised", "how_it_differs": "Infectious colitis and medication-related colitis are more likely and must be excluded before attributing symptoms to Crohn's.", "missing_classic_features": ["Classic chronic relapsing course"]}]}, "exam": {"general": {"mild": "Well-appearing, comfortable at rest, no distress; may look tired", "moderate": "Mildly ill-appearing, thin, uncomfortable during the interview, shifting in the chair", "severe": "Ill-appearing, visibly thin or wasted, pale, diaphoretic, guarding the abdomen", "critical": "Toxic-appearing, cachectic, pale, hypotensive and tachycardic, lethargic or confused"}, "findings": [{"id": "weight-loss", "region": "general", "maneuver": "Measure weight and compare with prior records or the patient's reported usual weight", "finding": "Unintentional weight loss, often 5–10% or more of body weight", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "pallor", "region": "general", "maneuver": "Inspect the conjunctivae and palmar creases", "finding": "Pallor suggesting anemia", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "oral-ulcers", "region": "heent", "maneuver": "Inspect the lips, buccal mucosa, tongue and palate", "finding": "Aphthous or deep linear ulcers in the mouth", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "abdominal-tenderness", "region": "abdomen", "maneuver": "Palpate all four quadrants, starting away from the area of pain", "finding": "Tenderness, often in the right lower quadrant or periumbilical region", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "abdominal-mass", "region": "abdomen", "maneuver": "Palpate deeply in the right lower quadrant and along the colon", "finding": "A tender, ill-defined mass or fullness suggesting inflamed bowel, phlegmon or abscess", "frequency": "sometimes", "min_severity": "moderate", "significance": "strongly_supports", "importance": "essential"}, {"id": "abdominal-distension", "region": "abdomen", "maneuver": "Inspect and percuss the abdomen", "finding": "Distension with tympany, suggesting obstruction or ileus", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "bowel-sounds-abnormal", "region": "abdomen", "maneuver": "Auscultate bowel sounds in all four quadrants", "finding": "Hyperactive, high-pitched or absent bowel sounds", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "guarding-rigidity", "region": "abdomen", "maneuver": "Palpate gently, then assess for rebound tenderness", "finding": "Voluntary or involuntary guarding; rigidity suggests perforation or peritonitis", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "essential"}, {"id": "perianal-fissure", "region": "rectal", "maneuver": "Inspect the perianal skin and spread the buttocks", "finding": "Anal fissure, skin tag, or perianal erythema", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "perianal-fistula-abscess", "region": "rectal", "maneuver": "Inspect and gently palpate the perianal area; perform a digital rectal exam when tolerated", "finding": "Fistula opening with drainage, induration, or a tender fluctuant abscess", "frequency": "sometimes", "significance": "strongly_supports", "importance": "essential"}, {"id": "rectal-normal", "region": "rectal", "maneuver": "Perform a digital rectal exam when the patient can tolerate it", "finding": "No palpable mass, no gross blood on the glove", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "erythema-nodosum", "region": "skin", "maneuver": "Inspect the shins and extensor surfaces of the legs", "finding": "Tender, red, raised nodules (erythema nodosum)", "frequency": "rare", "significance": "supports", "importance": "important"}, {"id": "pyoderma-gangrenosum", "region": "skin", "maneuver": "Inspect the lower legs and any skin ulcers", "finding": "Painful, well-demarcated ulcer with a purulent base (pyoderma gangrenosum)", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "joint-synovitis", "region": "musculoskeletal", "maneuver": "Inspect and palpate the knees, ankles, wrists and small joints", "finding": "Joint swelling, warmth or tenderness (peripheral arthritis)", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "eye-inflammation", "region": "heent", "maneuver": "Inspect the conjunctivae and sclera; check for photophobia", "finding": "Red eye with perilimbal injection or photophobia suggesting uveitis