insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$diabetes-and-pregnancy$rounds_kb$, $rounds_kb$Diabetes and Pregnancy$rounds_kb$, $rounds_kb$obgyn$rounds_kb$, array[$rounds_kb$obgyn$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$endocrine$rounds_kb$, $rounds_kb$reproductive$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "diabetes-and-pregnancy", "triage": {"name": "Diabetes and Pregnancy", "case_suitable": true, "reason": "Pregnancy with pre-existing diabetes is a manageable case: glycemic history, monitoring and maternal-fetal risk assessment.", "kind": "disease", "category": "pregnancy with medical comorbidity", "organ_systems": ["endocrine", "reproductive"], "primary_clerkship": "obgyn", "secondary_clerkships": ["internalMedicine", "familyMedicine"], "commonness": "common", "settings": ["clinic", "labor_delivery", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:59Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:48:56Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:02Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:13Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:25Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:32Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["differential preeclampsia: no profile yet", "differential diabetic-ketoacidosis: no profile yet", "differential hyperemesis-gravidarum: no profile yet", "differential urinary-tract-infection: no profile yet", "differential type-2-diabetes-mellitus: no profile yet", "differential chronic-hypertension: no profile yet", "differential fetal-macrosomia: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 18, "typical_max": 45, "peak": "25–35", "possible_min": 12, "possible_max": 55}, "sex": "female_only", "demographics": ["Occurs in pregnant women of any race or ethnicity", "Higher rates of gestational diabetes in African American, Hispanic/Latina, American Indian, Alaska Native, Native Hawaiian and Pacific Islander women", "Pre-existing type 1 or type 2 diabetes is increasingly common in pregnancy as rates of obesity and type 2 diabetes rise in women of childbearing age"], "risk_factors": [{"text": "Overweight or obesity before pregnancy", "strength": "strong"}, {"text": "Family history of diabetes in a first-degree relative", "strength": "strong"}, {"text": "Gestational diabetes in a previous pregnancy", "strength": "strong"}, {"text": "Previous infant weighing 9 pounds (4 kg) or more", "strength": "strong"}, {"text": "Polycystic ovary syndrome", "strength": "moderate"}, {"text": "Pre-existing type 1 or type 2 diabetes", "strength": "strong"}, {"text": "Age over 35 years", "strength": "moderate"}, {"text": "Physical inactivity", "strength": "weak"}], "comorbidities": ["Obesity", "Polycystic ovary syndrome", "Chronic hypertension", "Diabetic retinopathy", "Diabetic nephropathy", "Prior pregnancy complicated by preeclampsia or macrosomia"], "family_history": ["Type 2 diabetes in a parent or sibling", "Gestational diabetes in a mother or sister"], "social_history": ["Sedentary lifestyle", "Limited access to prenatal care"], "exposures": [], "risk_medications": ["corticosteroids", "olanzapine", "risperidone", "quetiapine", "tacrolimus", "sirolimus"]}, "presentation": {"chief_complaints": [{"text": "I'm pregnant and my blood sugar has been high", "frequency": "common"}, {"text": "I'm thirstier than usual and peeing all the time", "frequency": "sometimes"}, {"text": "I feel tired all the time", "frequency": "sometimes"}, {"text": "My doctor said my glucose screening test was abnormal", "frequency": "common"}], "hpi": {"onset": "Often gradual and detected on routine prenatal screening; women with pre-existing diabetes may notice worsening glucose control as pregnancy progresses", "duration": "Gestational diabetes is usually diagnosed at 24–28 weeks; pre-existing diabetes is present before conception", "progression": "Insulin resistance rises through the second and third trimesters, so glucose levels and medication needs tend to increase until near term", "location": "Not applicable", "radiation": "Not applicable", "quality": "Not applicable", "severity": "Often asymptomatic; when symptoms occur they are mild", "timing": "Symptoms, if any, are persistent rather than episodic", "aggravating": ["Eating high-carbohydrate meals", "Later stages of pregnancy"], "relieving": ["Dietary changes", "Physical activity", "Insulin or other glucose-lowering medication"], "associated_symptoms": [{"text": "Increased thirst", "frequency": "sometimes"}, {"text": "Frequent urination", "frequency": "sometimes"}, {"text": "Fatigue", "frequency": "sometimes"}, {"text": "Blurred vision", "frequency": "rare"}, {"text": "Recurrent vaginal or urinary infections", "frequency": "rare"}], "pertinent_negatives": ["Vaginal bleeding", "Severe abdominal pain", "Persistent vomiting", "Fever or chills", "Dysuria or flank pain", "Severe headache with visual changes", "Right upper quadrant pain", "Decreased fetal movement", "Leakage of fluid from the vagina"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "sometimes"}], "negatives": ["Fever", "Chills", "Unintentional weight loss"]}, {"system": "endocrine", "positives": [{"text": "Increased thirst", "frequency": "sometimes"}, {"text": "Frequent urination", "frequency": "sometimes"}], "negatives": ["Heat intolerance", "Palpitations", "Tremor"]}, {"system": "genitourinary", "positives": [{"text": "Vaginal itching or discharge", "frequency": "rare"}], "negatives": ["Dysuria", "Hematuria", "Flank pain", "Vaginal bleeding"], "argues_against": ["Urinary tract infection", "Ectopic pregnancy", "Miscarriage"]}, {"system": "cardiovascular", "positives": [], "negatives": ["Chest pain", "Shortness of breath at rest", "Palpitations", "Swelling of face or hands"], "argues_against": ["Preeclampsia", "Peripartum cardiomyopathy"]}, {"system": "neurologic", "positives": [{"text": "Blurred vision", "frequency": "rare"}], "negatives": ["Severe headache", "Visual spots or flashes", "Seizures", "Numbness or tingling in hands or feet"], "argues_against": ["Preeclampsia with severe features", "Diabetic neuropathy"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea", "frequency": "sometimes"}], "negatives": ["Vomiting blood", "Right upper quadrant pain", "Severe epigastric pain", "Jaundice"], "argues_against": ["HELLP syndrome", "Acute fatty liver of pregnancy"]}, {"system": "reproductive", "positives": [], "negatives": ["Decreased fetal movement", "Leakage of fluid", "Regular painful contractions before term"], "argues_against": ["Preterm labor", "Fetal distress"]}], "atypical": [{"population": "obesity", "how_it_differs": "Higher baseline insulin resistance means glucose levels rise earlier and higher, and more women need medication rather than diet alone.", "missing_classic_features": ["Mild asymptomatic course"]}, {"population": "diabetes", "how_it_differs": "Women with pre-existing type 1 or type 2 diabetes often have symptoms of hyperglycemia and known complications before pregnancy, and their insulin requirements change markedly through pregnancy.", "missing_classic_features": ["Normal glucose before pregnancy", "Diagnosis at 24–28 weeks"]}, {"population": "older_adults", "how_it_differs": "Pregnancy over age 35 carries higher baseline risk of gestational diabetes and hypertensive complications, and symptoms may be attributed to age rather than hyperglycemia.", "missing_classic_features": ["Younger age at presentation"]}]}, "exam": {"general": {"mild": "Well-appearing, comfortable, no distress; uterine size consistent with dates", "moderate": "Well-appearing but tired; may appear overweight or obese; no acute distress", "severe": "Ill-appearing with signs of dehydration from hyperglycemia (dry mucous membranes, poor skin turgor) or hypertensive urgency", "critical": "Toxic-appearing, lethargic or confused, signs of severe dehydration, Kussmaul respirations, or seizures from severe preeclampsia/eclampsia"}, "findings": [{"id": "fundal-height-dates", "region": "abdomen", "maneuver": "Measure fundal height with a tape from the pubic symphysis to the top of the fundus", "finding": "Fundal height greater than expected for gestational age, suggesting macrosomia or polyhydramnios", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "fetal-heart-tones", "region": "abdomen", "maneuver": "Auscultate fetal heart tones with a Doppler or fetoscope", "finding": "Fetal heart tones present and regular in the expected range (110–160/min)", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "uterine-tenderness", "region": "abdomen", "maneuver": "Palpate the uterus for tenderness and assess uterine tone", "finding": "Uterine tenderness or hypertonicity suggesting abruption or preterm labor", "frequency": "rare", "min_severity": "severe", "significance": "argues_against", "importance": "important"}, {"id": "edema", "region": "extremities", "maneuver": "Press the dorsum of each foot and the pretibial area for 5 seconds", "finding": "Pitting edema of the lower extremities", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "facial-hand-edema", "region": "general", "maneuver": "Inspect the face and hands for swelling", "finding": "Swelling of the face or hands suggesting preeclampsia", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "hyperreflexia", "region": "neuro", "maneuver": "Test deep tendon reflexes at the biceps, brachioradialis, patella and Achilles", "finding": "Hyperreflexia or clonus suggesting preeclampsia with severe features", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "fundoscopic-exam", "region": "heent", "maneuver": "Perform a dilated fundoscopic exam", "finding": "Diabetic retinopathy (microaneurysms, hemorrhages, exudates, or proliferative changes)", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "skin-infections", "region": "skin", "maneuver": "Inspect skin folds, feet and perineum", "finding": "Candidal intertrigo, vulvovaginitis, or skin infections associated with hyperglycemia", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "foot-exam", "region": "extremities", "maneuver": "Inspect the feet and test protective sensation with a 10-g monofilament", "finding": "Diabetic neuropathy with loss of protective sensation or foot ulcers", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "normal-lung-exam", "region": "lung", "maneuver": "Auscultate all lung fields", "finding": "Clear to auscultation bilaterally without crackles or wheeze", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-cardiac-exam", "region": "cardiac", "maneuver": "Auscultate the heart and palpate peripheral pulses", "finding": "Regular rate and rhythm without murmurs, rubs or gallops; normal peripheral pulses", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-neuro-exam", "region": "neuro", "maneuver": "Assess cranial nerves, strength and sensation", "finding": "No focal neurologic deficits, no severe headache or visual changes", "frequency": "almost_always", "significance": "neutral", "importance": "important"}]}, "vitals": {"temp": {"mild": {"min": 97.8, "max": 99.1}, "moderate": {"min": 97.8, "max": 99.5}, "severe": {"min": 98.0, "max": 100.4}, "critical": {"min": 98.0, "max": 101.0}}, "hr": {"mild": {"min": 70, "max": 100}, "moderate": {"min": 80, "max": 110}, "severe": {"min": 95, "max": 125}, "critical": {"min": 110, "max": 140}}, "rr": {"mild": {"min": 12, "max": 20}, "moderate": {"min": 14, "max": 22}, "severe": {"min": 18, "max": 26}, "critical": {"min": 22, "max": 32}}, "sbp": {"mild": {"min": 100, "max": 130}, "moderate": {"min": 110, "max": 140}, "severe": {"min": 140, "max": 170}, "critical": {"min": 160, "max": 200}}, "dbp": {"mild": {"min": 60, "max": 80}, "moderate": {"min": 65, "max": 90}, "severe": {"min": 90, "max": 110}, "critical": {"min": 100, "max": 120}}, "spo2": {"mild": {"min": 95, "max": 100}, "moderate": {"min": 95, "max": 100}, "severe": {"min": 92, "max": 99}, "critical": {"min": 88, "max": 96}}}, "labs": [{"test_id": "glucose", "ranges": {"mild": {"min": 92, "max": 105}, "moderate": {"min": 100, "max": 130}, "severe": {"min": 126, "max": 200}, "critical": {"min": 180, "max": 400}}, "frequency": "almost_always", "importance": "essential", "caveat": "Fasting plasma glucose. In pregnancy, fasting ≥92 mg/dL meets criteria for gestational diabetes; values ≥126 mg/dL suggest overt pre-existing diabetes."}, {"test_id": "a1c", "ranges": {"mild": {"min": 5.7, "max": 6.4}, "moderate": {"min": 6.0, "max": 7.0}, "severe": {"min": 6.5, "max": 9.0}, "critical": {"min": 8.0, "max": 12.0}}, "frequency": "common", "importance": "essential", "caveat": "Used to assess pre-pregnancy and early-pregnancy glycemic control; A1c ≥6.5% suggests pre-existing diabetes. A1c is less reliable in later pregnancy due to hemodilution and increased red cell turnover."}, {"test_id": "ua_glucose", "qualitative": {"mild": "Trace", "moderate": "1+", "severe": "2+", "critical": "3+"}, "frequency": "common", "importance": "important", "caveat": "Glucosuria reflects glucose above the renal threshold; can be positive in pregnancy even with normal glucose due to increased GFR."}, {"test_id": "ua_ketones", "qualitative": {"moderate": "Trace", "severe": "Small", "critical": "Moderate"}, "frequency": "sometimes", "importance": "important", "caveat": "Ketones suggest inadequate carbohydrate intake, starvation ketosis, or diabetic ketoacidosis; important to assess in type 1 diabetes."}, {"test_id": "ua_protein", "qualitative": {"moderate": "Trace", "severe": "1+", "critical": "2+"}, "frequency": "sometimes", "importance": "important", "caveat": "Proteinuria may indicate preeclampsia or diabetic nephropathy; requires quantification with protein/creatinine ratio."}, {"test_id": "cr", "ranges": {"moderate": {"min": 0.8, "max": 1.1}, "severe": {"min": 1.0, "max": 1.5}, "critical": {"min": 1.4, "max": 3.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Creatinine normally falls in pregnancy due to increased GFR; a value ≥0.8 mg/dL may indicate renal impairment."}, {"test_id": "hco3", "ranges": {"severe": {"min": 18, "max": 21}, "critical": {"min": 10, "max": 18}}, "frequency": "rare", "importance": "important", "caveat": "Low bicarbonate suggests metabolic acidosis from diabetic ketoacidosis."}, {"test_id": "k", "ranges": {"moderate": {"min": 3.3, "max": 3.5}, "severe": {"min": 3.0, "max": 3.4}, "critical": {"min": 2.5, "max": 3.2}}, "frequency": "rare", "importance": "important", "caveat": "Hypokalemia can occur with insulin treatment and osmotic diuresis in diabetic ketoacidosis."}, {"test_id": "hcg", "frequency": "almost_always", "importance": "essential", "caveat": "Confirms pregnancy and establishes gestational age; essential before initiating any diabetes management plan."}, {"test_id": "tsh", "ranges": {"mild": {"min": 0.1, "max": 0.4}, "moderate": {"min": 4.0, "max": 6.0}, "severe": {"min": 5.0, "max": 10.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Thyroid dysfunction is more common in women with type 1 diabetes and can affect pregnancy outcomes."}], "imaging": [{"study": "Obstetric ultrasound (fetal anatomy survey)", "modality": "ultrasound", "preferred_when": "18–22 weeks gestation for detailed anatomy; earlier for dating and viability", "findings": [{"text": "Fetal biometry consistent with dates or showing macrosomia (estimated fetal weight >90th percentile)", "frequency": "common"}, {"text": "Polyhydramnios (amniotic fluid index >24 cm)", "frequency": "sometimes"}, {"text": "Fetal cardiac, neural tube, or other structural anomalies", "frequency": "sometimes"}, {"text": "Normal fetal anatomy", "frequency": "common"}]}, {"study": "Fetal echocardiography", "modality": "ultrasound", "preferred_when": "Women with pre-existing diabetes and poor glycemic control (A1c >6.5%) or elevated maternal serum alpha-fetoprotein", "findings": [{"text": "Normal cardiac anatomy and function", "frequency": "common"}, {"text": "Congenital heart defects (ventricular septal defect, transposition of great arteries, truncus arteriosus)", "frequency": "sometimes"}]}, {"study": "Growth ultrasound (serial fetal biometry)", "modality": "ultrasound", "preferred_when": "Third trimester, especially with pre-existing diabetes or poor control", "findings": [{"text": "Estimated fetal weight >90th percentile (macrosomia)", "frequency": "common"}, {"text": "Normal interval growth", "frequency": "common"}, {"text": "Oligohydramnios or polyhydramnios", "frequency": "sometimes"}]}, {"study": "Umbilical artery Doppler", "modality": "ultrasound", "preferred_when": "Suspected fetal growth restriction or maternal vascular disease", "findings": [{"text": "Normal forward flow with low resistance", "frequency": "common"}, {"text": "Increased resistance or absent/reversed end-diastolic flow", "frequency": "rare"}]}, {"study": "Dilated retinal examination", "modality": "other", "preferred_when": "All women with pre-existing diabetes at first prenatal visit and each trimester", "findings": [{"text": "No retinopathy", "frequency": "common"}, {"text": "Nonproliferative diabetic retinopathy (microaneurysms, dot-blot hemorrhages, hard exudates)", "frequency": "sometimes"}, {"text": "Proliferative diabetic retinopathy or macular edema", "frequency": "rare"}]}], "workup": {"initial": [{"test": "hcg", "why": "Confirms pregnancy and dating"}, {"test": "glucose", "why": "Fasting glucose to screen for or diagnose diabetes in pregnancy"}, {"test": "a1c", "why": "Assesses pre-pregnancy and early-pregnancy glycemic control; identifies pre-existing diabetes"}, {"test": "cbc", "why": "Baseline hemoglobin, platelets; anemia is common in pregnancy"}, {"test": "bmp", "why": "Baseline renal function, electrolytes, and glucose"}, {"test": "ua", "why": "Screens for glucosuria, ketonuria, proteinuria, and urinary infection"}, {"test": "tsh", "why": "Thyroid dysfunction is more common in type 1 diabetes and affects pregnancy"}, {"test": "Obstetric ultrasound (fetal anatomy survey)", "why": "Dating, viability, and anatomy assessment", "only_if": "initial prenatal visit or 18–22 weeks"}, {"test": "Dilated retinal examination", "why": "Baseline assessment for diabetic retinopathy, which can worsen in pregnancy", "only_if": "pre-existing diabetes"}], "confirmatory": [{"test": "Oral glucose tolerance test (75 g, 2-hour)", "why": "Diagnostic test for gestational diabetes; fasting ≥92, 1-hour ≥180, or 2-hour ≥153 mg/dL meets criteria"}, {"test": "Glucose challenge test (50 g, 1-hour)", "why": "Screening test; if ≥130–140 mg/dL, proceed to diagnostic OGTT", "only_if": "screening at 24–28 weeks"}], "supporting": [{"test": "Fetal echocardiography", "why": "Detects congenital heart defects associated with poor glycemic control", "only_if": "pre-existing diabetes with A1c >6.5% or abnormal anatomy survey"}, {"test": "Growth ultrasound (serial fetal biometry)", "why": "Monitors for macrosomia and growth restriction", "only_if": "third trimester with diabetes"}, {"test": "Umbilical artery Doppler", "why": "Assesses fetal well-being in growth restriction", "only_if": "suspected fetal growth restriction"}, {"test": "cr", "why": "Assesses renal function; elevated creatinine may indicate nephropathy", "only_if": "proteinuria or hypertension"}, {"test": "ua_protein", "why": "Screens for preeclampsia or nephropathy", "only_if": "hypertension or symptoms of preeclampsia"}], "not_indicated": [{"test": "d_dimer", "why": "Not useful for diagnosing preeclampsia or diabetes in pregnancy; elevated in normal pregnancy"}, {"test": "lactate", "why": "Not routinely needed unless diabetic ketoacidosis or sepsis is suspected"}, {"test": "ct abdomen and pelvis with IV contrast", "why": "Avoid ionizing radiation in pregnancy unless a life-threatening condition requires it"}, {"test": "Abdominal x-ray", "why": "Not indicated for diabetes in pregnancy"}], "decision_points": ["Screen for gestational diabetes at 24–28 weeks in all pregnant women; screen early if high risk", "Diagnose gestational diabetes with 75 g OGTT using IADPSG criteria: fasting ≥92, 1-hour ≥180, or 2-hour ≥153 mg/dL", "In pre-existing diabetes, optimize A1c before conception and monitor closely during pregnancy", "Assess for preeclampsia if new hypertension or proteinuria develops", "Perform retinal exam each trimester in pre-existing diabetes"], "criteria": [{"name": "Gestational diabetes diagnostic criteria (IADPSG/ADA)", "summary": "Diagnosis is made if any one of the following thresholds is met or exceeded on a 75 g 2-hour OGTT: fasting plasma glucose 92 mg/dL, 1-hour 180 mg/dL, or 2-hour 153 mg/dL.", "items": ["Fasting plasma glucose ≥92 mg/dL", "1-hour plasma glucose ≥180 mg/dL", "2-hour plasma glucose ≥153 mg/dL"]}, {"name": "Overt diabetes in pregnancy", "summary": "Diagnosed when fasting glucose ≥126 mg/dL, A1c ≥6.5%, or random glucose ≥200 mg/dL with symptoms.", "items": ["Fasting plasma glucose ≥126 mg/dL", "A1c ≥6.5%", "Random plasma glucose ≥200 mg/dL with classic symptoms"]}], "scores": []}, "differential": [{"name": "Preeclampsia", "slug": "preeclampsia", "why_considered": "Both conditions occur in pregnancy and share risk factors such as obesity, chronic hypertension and pre-existing diabetes; new hypertension or proteinuria in a pregnant woman with diabetes raises concern.", "must_not_miss": true, "trigger": "New hypertension after 20 weeks with proteinuria, headache, visual changes, or right upper quadrant pain", "discriminators": {"history": ["New or worsening headache", "Visual spots or flashes", "Right upper quadrant or epigastric pain", "Rapid swelling of face and hands"], "exam": ["Blood pressure 140/90 mmHg or higher on two occasions", "Facial or hand edema", "Hyperreflexia or clonus"], "labs": ["Proteinuria on urine protein/creatinine ratio or 24-hour collection", "Elevated AST/ALT", "Low platelets", "Elevated creatinine"], "imaging": ["Fetal growth restriction or oligohydramnios on ultrasound", "Abnormal umbilical artery Doppler in severe disease"]}}, {"name": "Diabetic ketoacidosis", "slug": "diabetic-ketoacidosis", "why_considered": "Pregnancy accelerates ketosis and insulin resistance, so women with type 1 diabetes can present with nausea, vomiting and abdominal pain that mimic routine pregnancy complaints.", "must_not_miss": true, "trigger": "Nausea, vomiting, abdominal pain, deep rapid breathing, or fruity breath odor in a pregnant woman with diabetes", "discriminators": {"history": ["Polydipsia and polyuria out of proportion to pregnancy", "Missed insulin doses or illness", "Rapid onset of vomiting and abdominal pain"], "exam": ["Kussmaul respirations", "Fruity acetone breath", "Signs of dehydration", "Lethargy or altered mental status"], "labs": ["Glucose usually above 200 mg/dL", "Low bicarbonate and low pH", "Positive serum or urine ketones", "Elevated anion gap"]}}, {"name": "Hyperemesis gravidarum", "slug": "hyperemesis-gravidarum", "why_considered": "Persistent nausea and vomiting in early pregnancy can cause dehydration, ketonuria and starvation ketosis that resemble poorly controlled diabetes.", "must_not_miss": false, "discriminators": {"history": ["Vomiting beginning in the first trimester", "Weight loss", "Inability to keep down fluids"], "exam": ["Signs of dehydration", "Normal or low blood pressure", "No fruity breath"], "labs": ["Normal or low glucose", "Urine ketones from starvation rather than hyperglycemia", "Normal anion gap"]}}, {"name": "Urinary tract infection", "slug": "urinary-tract-infection", "why_considered": "Pregnant women with diabetes have more frequent urinary infections, and both conditions can cause urinary frequency and malaise.", "must_not_miss": false, "discriminators": {"history": ["Dysuria", "Suprapubic pain", "Fever or chills"], "exam": ["Suprapubic tenderness", "Costovertebral angle tenderness if pyelonephritis"], "labs": ["Positive urine leukocyte esterase and nitrites", "Bacteriuria on urine culture", "Glucose may be normal or elevated"]}}, {"name": "Type 2 diabetes mellitus", "slug": "type-2-diabetes-mellitus", "why_considered": "Overt diabetes may first be recognized during pregnancy, and it shares obesity, family history and glucosuria with gestational diabetes.", "must_not_miss": false, "discriminators": {"history": ["Hyperglycemia symptoms before pregnancy", "Long-standing obesity", "Strong family history of diabetes"], "labs": ["Fasting glucose 126 mg/dL or higher", "A1c 6.5% or higher", "Elevated glucose persists after delivery"]}}, {"name": "Chronic hypertension", "slug": "chronic-hypertension", "why_considered": "Frequently coexists with diabetes in pregnancy and can be confused with preeclampsia when blood pressure rises.", "must_not_miss": false, "discriminators": {"history": ["Hypertension diagnosed before pregnancy or before 20 weeks", "Antihypertensive use before conception"], "exam": ["Elevated blood pressure without facial or hand edema", "No hyperreflexia"], "labs": ["No proteinuria", "Normal platelets and liver enzymes"]}}, {"name": "Fetal macrosomia from other causes", "slug": "fetal-macrosomia", "why_considered": "A larger-than-dates uterus can reflect macrosomia from diabetes but also from constitutional factors or post-term pregnancy.", "must_not_miss": false, "discriminators": {"history": ["Previous large infant without diabetes", "Post-term pregnancy", "Tall or large parents"], "labs": ["Normal glucose screening and OGTT"], "imaging": ["Estimated fetal weight above the 90th percentile with normal amniotic fluid", "No stigmata of diabetic fetopathy"]}}], "course": {"severity": {"mild": "Gestational diabetes or well-controlled pre-existing diabetes managed with diet and activity alone; fasting glucose below 95 mg/dL and normal fetal growth.", "moderate": "Diabetes requiring medication (insulin or an oral agent) with glucose near target; no maternal vascular complications and normal fetal growth.", "severe": "Poorly controlled diabetes with A1c above 7%, macrosomia or polyhydramnios, or worsening retinopathy or nephropathy.", "critical": "Diabetic ketoacidosis, severe preeclampsia or eclampsia, or diabetic coma with fetal compromise."}, "red_flags": [{"finding": "Nausea, vomiting, abdominal pain, deep rapid breathing or fruity breath", "meaning": "Diabetic ketoacidosis; a maternal and fetal emergency requiring immediate treatment"}, {"finding": "Blood pressure 160/110 mmHg or higher, severe headache, visual changes or right upper quadrant pain", "meaning": "Preeclampsia with severe features; risk of seizure, stroke and placental abruption"}, {"finding": "Decreased fetal movement or abnormal fetal heart tracing", "meaning": "Fetal compromise; needs urgent obstetric evaluation"}, {"finding": "Vaginal bleeding or uterine tenderness", "meaning": "Placental abruption or other obstetric emergency"}, {"finding": "Leakage of fluid or regular painful contractions before term", "meaning": "Preterm labor, which is more common with diabetes"}, {"finding": "Severe hypoglycemia with confusion or loss of consciousness", "meaning": "Tight glycemic control in pregnancy increases hypoglycemia risk, especially in type 1 diabetes"}], "complications": [{"name": "Macrosomia", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Fundal height greater than dates", "Estimated fetal weight above the 90th percentile on ultrasound", "Polyhydramnios"]}, {"name": "Preeclampsia", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["New hypertension after 20 weeks", "Proteinuria", "Headache or visual changes", "Right upper quadrant pain"]}, {"name": "Congenital birth defects", "timing": "early", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["A1c above 6.5% near conception", "Cardiac, neural tube or renal anomalies on anatomy ultrasound", "Elevated maternal serum alpha-fetoprotein"]}, {"name": "Neonatal hypoglycemia", "timing": "early", "seriousness": "serious", "frequency": "common", "clues": ["Maternal hyperglycemia in labor", "Large-for-gestational-age infant", "Jitteriness or poor feeding after birth"]}, {"name": "Shoulder dystocia and birth trauma", "timing": "early", "seriousness": "serious", "frequency": "sometimes", "clues": ["Estimated fetal weight above 4,000 g", "Difficult delivery of the shoulders", "Neonatal clavicle fracture or brachial plexus injury"]}, {"name": "Cesarean delivery", "timing": "early", "seriousness": "minor", "frequency": "common", "clues": ["Macrosomia", "Failed induction", "Non-reassuring fetal status"]}, {"name": "Diabetic ketoacidosis", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Type 1 diabetes", "Infection or vomiting", "Missed insulin doses", "Kussmaul respirations"]}, {"name": "Worsening diabetic retinopathy", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Pre-existing retinopathy", "Rapid improvement in glucose control", "Blurred vision or new floaters"]}, {"name": "Worsening diabetic nephropathy", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Pre-existing proteinuria", "Rising creatinine", "Worsening hypertension"]}, {"name": "Miscarriage and stillbirth", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Poor glycemic control", "Decreased fetal movement", "Abnormal fetal testing"]}, {"name": "Type 2 diabetes later in life", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["History of gestational diabetes", "Obesity", "Family history of diabetes", "Abnormal postpartum glucose testing"]}], "special_populations": [{"population": "pregnancy", "differences": "This is the defining population; insulin resistance rises through the second and third trimesters, so medication needs increase until near term and then fall sharply after delivery."}, {"population": "obesity", "differences": "Higher baseline insulin resistance means glucose rises earlier and higher, and more women need medication rather than diet alone."}, {"population": "diabetes", "differences": "Women with pre-existing type 1 or type 2 diabetes need pre-conception planning, tighter targets and monitoring for retinopathy, nephropathy and hypoglycemia."}, {"population": "older_adults", "differences": "Pregnancy over age 35 carries higher baseline risk of gestational diabetes and hypertensive complications."}, {"population": "renal_impairment", "differences": "Pre-existing nephropathy increases the risk of preeclampsia and fetal growth restriction, and creatinine must be interpreted against the lower pregnancy reference range."}, {"population": "children", "differences": "Pregnancy in adolescents with diabetes is uncommon but carries higher risks of preterm birth and poor glycemic control because of social and care-access barriers."}]}, "teaching": {"key_questions": [{"question": "When was your last menstrual period, and how far along are you?", "category": "obstetric", "importance": "essential", "looking_for": "Gestational age, which determines whether screening at 24–28 weeks is due and how insulin resistance is expected to change"}, {"question": "Did you have diabetes before this pregnancy, or was it first found during pregnancy?", "category": "pmh", "importance": "essential", "looking_for": "Pre-existing type 1 or type 2 diabetes versus gestational diabetes; changes the whole management plan"}, {"question": "What was your blood sugar control like before you became pregnant?", "category": "hpi", "importance": "essential", "looking_for": "Pre-conception A1c and glucose levels; poor early control raises the risk of birth defects"}, {"question": "Have you been thirstier than usual or urinating more often?", "category": "hpi", "importance": "important", "looking_for": "Mild hyperglycemic symptoms; often absent in gestational diabetes"}, {"question": "Have you had blurred vision, floaters, or any change in your eyesight?", "category": "associated", "importance": "important", "looking_for": "Diabetic retinopathy, which can worsen during pregnancy"}, {"question": "Have you had swelling of your face or hands, headaches, or visual spots?", "category": "red_flag", "importance": "essential", "looking_for": "Preeclampsia, which is more common with diabetes in pregnancy"}, {"question": "Have you had any right upper quadrant or severe stomach pain, nausea, or vomiting?", "category": "red_flag", "importance": "essential", "looking_for": "HELLP syndrome, acute fatty liver of pregnancy, or diabetic ketoacidosis"}, {"question": "Have you felt the baby move normally?", "category": "obstetric", "importance": "essential", "looking_for": "Decreased fetal movement, which requires urgent evaluation"}, {"question": "Have you had any vaginal bleeding, fluid leakage, or regular contractions?", "category": "obstetric", "importance": "essential", "looking_for": "Placental abruption, preterm labor, or rupture of membranes"}, {"question": "What diabetes medicines are you taking, and have you needed to change the doses?", "category": "medications", "importance": "essential", "looking_for": "Insulin regimen and dose changes; some oral agents are not used in pregnancy"}, {"question": "Have you had gestational diabetes, a large baby, or preeclampsia in a past pregnancy?", "category": "obstetric", "importance": "important", "looking_for": "Strong risk factors for gestational diabetes and recurrence"}, {"question": "Does anyone in your family have diabetes?", "category": "family", "importance": "important", "looking_for": "First-degree relative with type 2 diabetes, a major risk factor"}, {"question": "Have you had frequent vaginal or urinary infections?", "category": "associated", "importance": "optional", "looking_for": "Recurrent candidal or urinary infections associated with hyperglycemia"}, {"question": "Do you have any numbness, tingling, or sores on your feet?", "category": "ros", "importance": "optional", "looking_for": "Diabetic neuropathy or foot ulcers in pre-existing diabetes"}], "accepted_names": ["Diabetes and pregnancy", "Gestational diabetes", "Gestational diabetes mellitus", "GDM", "Pregestational diabetes", "Pre-existing diabetes in pregnancy", "Diabetes in pregnancy", "Pregnancy in diabetics"], "reasoning_points": ["Pregnancy with hyperglycemia, either pre-existing diabetes or glucose intolerance first recognized in pregnancy", "Gestational diabetes is usually asymptomatic and found on routine screening at 24–28 weeks, or earlier if high risk", "Diagnosis rests on a 75 g 2-hour oral glucose tolerance test using IADPSG/ADA thresholds: fasting ≥92, 1-hour ≥180, or 2-hour ≥153 mg/dL", "Overt or pre-existing diabetes is suggested by fasting glucose ≥126 mg/dL, A1c ≥6.5%, or random glucose ≥200 mg/dL with symptoms", "Insulin resistance rises through the second and third trimesters, so glucose levels and medication needs increase until near term", "Maternal risks include preeclampsia, cesarean delivery, worsening retinopathy and nephropathy, and later type 2 diabetes", "Fetal and neonatal risks include macrosomia, congenital birth defects with poor early control, neonatal hypoglycemia, and stillbirth", "Preeclampsia, diabetic ketoacidosis, and fetal compromise must be excluded because they change management urgently"], "difficulty": {"easy": ["Routine prenatal visit at 24–28 weeks with an abnormal 50 g glucose challenge test", "No symptoms, normal examination, normal fetal growth", "Classic risk factors such as obesity and a family history of diabetes", "Diagnosis confirmed on a 75 g oral glucose tolerance test"], "medium": ["Pre-existing type 1 or type 2 diabetes with changing insulin requirements through pregnancy", "Fundal height greater than dates suggesting macrosomia or polyhydramnios", "Mild hyperglycemic symptoms attributed to normal pregnancy", "Coexisting chronic hypertension raising concern for preeclampsia"], "hard": ["Nausea, vomiting and abdominal pain in a woman with type 1 diabetes suggesting diabetic ketoacidosis", "New hypertension with headache or visual changes suggesting preeclampsia with severe features", "Decreased fetal movement or an abnormal fetal heart tracing requiring urgent obstetric evaluation", "Pregnancy in an adolescent or a woman with limited prenatal care and poor glycemic control", "Pre-existing nephropathy with a creatinine that looks normal but is elevated for pregnancy"]}}}$rounds_kb$::jsonb)
