insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$diabetes-type-1$rounds_kb$, $rounds_kb$Diabetes Type 1$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, array[$rounds_kb$pediatrics$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$endocrine$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "diabetes-type-1", "triage": {"name": "Diabetes Type 1", "case_suitable": true, "reason": "Classic presentation with polyuria, polydipsia, weight loss and possible DKA; diagnosis reachable by history, labs and ketone assessment.", "kind": "disease", "category": "endocrine/metabolic", "organ_systems": ["endocrine"], "primary_clerkship": "pediatrics", "secondary_clerkships": ["internalMedicine", "emergency", "familyMedicine"], "commonness": "common", "settings": ["emergency", "inpatient", "pediatric_clinic", "clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:59Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:41Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:47Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:49:59Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:08Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:14Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'ct' to 'CT