insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$diabetes-type-2$rounds_kb$, $rounds_kb$Diabetes Type 2$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$endocrine$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "diabetes-type-2", "triage": {"name": "Diabetes Type 2", "case_suitable": true, "reason": "Very common clinic presentation with subtle symptoms, screening labs and a broad complication differential; strong teaching case.", "kind": "disease", "category": "endocrine/metabolic", "organ_systems": ["endocrine"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["familyMedicine", "emergency"], "commonness": "very_common", "settings": ["clinic", "inpatient", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:59Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:05Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:12Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:23Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:41Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:47Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'a1c' was in ['initial', 'confirmatory'], kept ['initial']", "auto-repaired: workup: