insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$diabetic-eye-problems$rounds_kb$, $rounds_kb$Diabetic Eye Problems$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$endocrine$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "diabetic-eye-problems", "triage": {"name": "Diabetic Eye Problems", "case_suitable": true, "reason": "Vision changes in a diabetic patient with a clear screening and exam-based diagnosis; limited but real interview findings.", "kind": "disease", "category": "microvascular complication", "organ_systems": ["endocrine"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["familyMedicine"], "commonness": "common", "settings": ["clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:59Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:22Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:29Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:38Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:48Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:50:54Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["differential retinal-detachment: no profile yet", "differential acute-angle-closure-glaucoma: no profile yet", "differential hypertensive-retinopathy: no profile yet", "differential central-retinal-vein-occlusion: no profile yet", "differential vitreous-hemorrhage: no profile yet", "differential age-related-macular-degeneration: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 30, "typical_max": 75, "peak": "40–65", "possible_min": 5, "possible_max": 90}, "sex": "either", "demographics": ["More common in people with longer duration of diabetes; prevalence rises with years since diagnosis", "More common in racial and ethnic minority groups with higher diabetes prevalence and less access to eye screening", "More common in people with type 1 diabetes, who often develop retinopathy earlier in life"], "risk_factors": [{"text": "Long duration of diabetes (especially more than 10 years)", "strength": "strong"}, {"text": "Poor glycemic control (high HbA1c)", "strength": "strong"}, {"text": "High blood pressure", "strength": "strong"}, {"text": "High blood cholesterol", "strength": "moderate"}, {"text": "Pregnancy in a person with diabetes", "strength": "moderate"}, {"text": "Tobacco smoking", "strength": "moderate"}, {"text": "Type 1 diabetes", "strength": "moderate"}, {"text": "Male sex", "strength": "weak"}], "comorbidities": ["Type 1 or type 2 diabetes mellitus", "Hypertension", "Hyperlipidemia", "Chronic kidney disease", "Obesity"], "family_history": ["Diabetes in a first-degree relative"], "social_history": ["Tobacco use", "Limited access to regular eye care"], "exposures": [], "risk_medications": []}, "presentation": {"chief_complaints": [{"text": "My vision has gotten blurry", "frequency": "common"}, {"text": "I see spots or dark wavy strings floating in my vision", "frequency": "common"}, {"text": "I have trouble seeing at night or in dim light", "frequency": "sometimes"}, {"text": "My vision changes a lot from day to day", "frequency": "sometimes"}, {"text": "I have a dark shadow over part of my vision, like a curtain", "frequency": "sometimes"}, {"text": "I see flashes of light", "frequency": "sometimes"}, {"text": "My eyes hurt and look red", "frequency": "rare"}], "hpi": {"onset": "Usually gradual and painless; often no symptoms at all until the disease is advanced. Sudden onset suggests a complication such as vitreous hemorrhage or retinal detachment.", "duration": "Develops over years of diabetes; symptoms may be present for weeks to months before presentation, or noticed only on a routine eye exam.", "progression": "Slowly progressive blurring and floaters as retinal blood vessels leak and new vessels grow; can suddenly worsen with bleeding into the eye or macular swelling.", "location": "Both eyes, though one eye may be worse than the other", "radiation": "Not applicable", "quality": "Blurred or wavy vision, floaters, missing patches, or a curtain-like shadow", "severity": "Mild to severe; can progress to significant vision loss if untreated", "timing": "Often constant once present; floaters and flashes may come and go early on", "aggravating": ["High blood sugar", "High blood pressure", "Straining or heavy lifting (can trigger bleeding)"], "relieving": ["Better blood sugar control", "Resting the eyes"], "associated_symptoms": [{"text": "Blurred or wavy vision", "frequency": "common"}, {"text": "Floaters (spots or dark wavy strings)", "frequency": "common"}, {"text": "Difficulty seeing colors", "frequency": "sometimes"}, {"text": "Flashes of light", "frequency": "sometimes"}, {"text": "Dark shadow or curtain over part of vision", "frequency": "sometimes"}, {"text": "Eye pain or redness", "frequency": "rare"}], "pertinent_negatives": ["Eye pain", "Redness of the eye", "Sudden complete vision loss", "Headache with nausea and vomiting", "Halos around lights", "Recent eye trauma", "Contact lens use"]}, "ros": [{"system": "eyes", "positives": [{"text": "Blurred vision", "frequency": "common"}, {"text": "Floaters", "frequency": "common"}, {"text": "Flashes of light", "frequency": "sometimes"}, {"text": "Curtain-like shadow", "frequency": "sometimes"}], "negatives": ["Eye pain", "Redness", "Double vision", "Sudden complete vision loss"], "argues_against": ["Acute angle-closure glaucoma", "Retinal detachment"]}, {"system": "endocrine", "positives": [{"text": "Long-standing diabetes", "frequency": "almost_always"}, {"text": "High blood sugar levels", "frequency": "common"}], "negatives": ["Weight loss", "Heat intolerance"]}, {"system": "neurologic", "positives": [], "negatives": ["Focal weakness", "Numbness", "Headache"], "argues_against": ["Stroke", "Brain tumor"]}, {"system": "constitutional", "positives": [], "negatives": ["Fever", "Weight loss", "Malaise"]}], "atypical": [{"population": "pregnancy", "how_it_differs": "Diabetic retinopathy can worsen rapidly during pregnancy, and symptoms may appear earlier than expected; close monitoring is needed.", "missing_classic_features": ["Long duration of diabetes"]}, {"population": "older_adults", "how_it_differs": "Symptoms may be attributed to aging or cataracts, and diabetic eye disease may be discovered only on routine exam.", "missing_classic_features": ["Acute vision changes"]}, {"population": "children", "how_it_differs": "Children with type 1 diabetes rarely have retinopathy before puberty or within the first few years of diagnosis, but it can occur if diabetes is long-standing and poorly controlled.", "missing_classic_features": ["Long duration of diabetes"]}]}, "exam": {"general": {"mild": "Well-appearing, no distress; may have no visual complaints at all", "moderate": "Well-appearing but reports or shows reduced central vision; no eye redness or pain", "severe": "Reduced vision affecting function; may squint or hold objects closer; no acute distress", "critical": "Marked vision loss or a new curtain-like visual field defect; may be anxious but not toxic"}, "findings": [{"id": "reduced-visual-acuity", "region": "heent", "maneuver": "Check visual acuity in each eye separately with a Snellen chart (with correction)", "finding": "Reduced best-corrected visual acuity, worse in one eye or both", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "essential"}, {"id": "normal-visual-acuity", "region": "heent", "maneuver": "Check visual acuity in each eye separately with a Snellen chart", "finding": "Normal visual acuity, which does not exclude early retinopathy", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "dilated-fundus-microaneurysms", "region": "heent", "maneuver": "Perform a dilated fundoscopic exam and look at the retinal periphery and posterior pole", "finding": "Dot-and-blot hemorrhages, microaneurysms, hard exudates, or cotton-wool spots", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "macular-edema", "region": "heent", "maneuver": "On dilated fundoscopy, inspect the macula for thickening, exudates, or loss of the foveal light reflex", "finding": "Retinal thickening or hard exudates at the macula, suggesting diabetic macular edema", "frequency": "common", "min_severity": "moderate", "significance": "strongly_supports", "importance": "essential"}, {"id": "neovascularization", "region": "heent", "maneuver": "On dilated fundoscopy, examine the optic disc, retinal vessels, and iris for new vessel growth", "finding": "New vessels on the disc, elsewhere on the retina, or at the iris (rubeosis iridis)", "frequency": "sometimes", "min_severity": "severe", "significance": "strongly_supports", "importance": "essential"}, {"id": "vitreous-hemorrhage", "region": "heent", "maneuver": "On dilated fundoscopy, look for blood obscuring the retina; assess for a relative afferent pupillary defect", "finding": "Blood in the vitreous obscuring retinal details, or a relative afferent pupillary defect", "frequency": "sometimes", "min_severity": "severe", "significance": "strongly_supports", "importance": "important"}, {"id": "elevated-intraocular-pressure", "region": "heent", "maneuver": "Measure