_medications": ["amlodipine", "nifedipine", "pregabalin", "gabapentin", "prednisone", "ibuprofen", "naproxen", "pioglitazone", "insulin"]}, "presentation": {"chief_complaints": [{"text": "My legs and ankles are swollen", "frequency": "almost_always"}, {"text": "My shoes feel tight by the end of the day", "frequency": "common"}, {"text": "My rings don't fit anymore", "frequency": "sometimes"}, {"text": "I've gained weight and my whole body feels puffy", "frequency": "sometimes"}], "hpi": {"onset": "Gradual over days to weeks; sometimes noticed after a period of standing or a salty meal", "duration": "Usually weeks to months by the time it is evaluated", "progression": "Slowly worsens through the day and over weeks; may improve overnight and with leg elevation", "location": "Both lower legs and ankles, often symmetric; can involve the hands, face, abdomen or whole body depending on the cause", "radiation": "Not applicable", "quality": "Puffy, doughy fullness of the skin that leaves a dent when pressed", "severity": "Mild to moderate; tightness and heaviness rather than pain", "timing": "Worse in the evening and after standing; better after a night in bed or with legs raised", "aggravating": ["Standing or sitting for long periods", "Hot weather", "Salty meals", "Tight shoes or socks"], "relieving": ["Lying down", "Raising the legs", "Support stockings", "Diuretic pills"], "associated_symptoms": [{"text": "Shortness of breath with activity", "frequency": "common"}, {"text": "Weight gain over the same period", "frequency": "common"}, {"text": "Legs feel heavy or tight", "frequency": "common"}, {"text": "Waking up short of breath at night", "frequency": "sometimes"}, {"text": "Needing more pillows to sleep", "frequency": "sometimes"}, {"text": "Swelling of the belly", "frequency": "sometimes"}, {"text": "Foamy urine", "frequency": "sometimes"}, {"text": "Decreased urination", "frequency": "sometimes"}, {"text": "Fatigue", "frequency": "common"}], "pertinent_negatives": ["Swelling in only one leg", "Chest pain", "Coughing up blood", "Fever", "Painful red warm leg", "Recent long travel or immobility with one-sided swelling", "Known cancer with new focal swelling"]}, "ros": [{"system": "cardiovascular", "positives": [{"text": "Swelling of both ankles and legs", "frequency": "almost_always"}, {"text": "Shortness of breath when active", "frequency": "common"}, {"text": "Needing extra pillows to breathe at night", "frequency": "sometimes"}], "negatives": ["Chest pain", "Palpitations", "Fainting"], "argues_against": ["One-sided calf pain and swelling suggesting deep vein thrombosis"]}, {"system": "respiratory", "positives": [{"text": "Shortness of breath with exertion", "frequency": "common"}, {"text": "Waking at night short of breath", "frequency": "sometimes"}], "negatives": ["Coughing up blood", "Pleuritic chest pain"], "argues_against": ["Sudden severe shortness of breath with chest pain"]}, {"system": "gastrointestinal", "positives": [{"text": "Bloating or belly swelling", "frequency": "sometimes"}, {"text": "Poor appetite", "frequency": "sometimes"}], "negatives": ["Vomiting blood", "Black stools", "Jaundice"], "argues_against": ["Hematemesis or melena pointing to variceal bleeding"]}, {"system": "genitourinary", "positives": [{"text": "Foamy urine", "frequency": "sometimes"}, {"text": "Passing less urine", "frequency": "sometimes"}], "negatives": ["Burning with urination", "Blood in urine", "Flank pain"], "argues_against": ["Dysuria and fever suggesting urinary infection"]}, {"system": "skin", "positives": [{"text": "Skin feels tight and shiny over the swollen area", "frequency": "common"}, {"text": "Socks leave deep marks", "frequency": "common"}], "negatives": ["Open sores", "Rash", "Redness or warmth of the leg"], "argues_against": ["Cellulitis or stasis ulcer with infection"]}, {"system": "musculoskeletal", "positives": [{"text": "Legs feel heavy", "frequency": "common"}], "negatives": ["Joint swelling and morning stiffness", "Muscle pain"], "argues_against": ["Inflammatory arthritis with joint swelling"]}, {"system": "constitutional", "positives": [{"text": "Feeling tired", "frequency": "common"}, {"text": "Weight gain", "frequency": "common"}], "negatives": ["Fever", "Night sweats", "Unintentional weight loss"], "argues_against": ["Systemic illness with fever and weight loss"]}], "atypical": [{"population": "older_adults", "how_it_differs": "Swelling may be attributed to aging or arthritis; heart failure and kidney disease are more likely and medications contribute more often.", "missing_classic_features": ["Clear temporal pattern of evening worsening"]}, {"population": "pregnancy", "how_it_differs": "Mild symmetric leg swelling is expected in the third trimester; new facial or hand swelling with headache or visual changes suggests preeclampsia and needs urgent evaluation.", "missing_classic_features": ["Swelling limited to the legs"]}, {"population": "renal_impairment", "how_it_differs": "Edema is often generalized with facial and periorbital puffiness, foamy urine and reduced urine output rather than isolated leg swelling.", "missing_classic_features": ["Isolated dependent leg swelling"]}, {"population": "hepatic_impairment", "how_it_differs": "Swelling comes with abdominal distension from ascites, easy bruising and jaundice rather than pure leg edema.", "missing_classic_features": ["Legs as the only swollen area"]}, {"population": "children", "how_it_differs": "Edema is more often from nephrotic syndrome or allergic reactions; periorbital swelling in the morning is a common clue.", "missing_classic_features": ["Evening-predominant leg swelling"]}]}, "exam": {"general": {"mild": "Comfortable, well-appearing; swelling noticed mainly by tight shoes or socks", "moderate": "Well-appearing but uncomfortable; legs feel heavy and tight by evening", "severe": "Ill-appearing with tense, shiny skin; may be short of breath on minimal exertion", "critical": "Toxic or lethargic; respiratory distress at rest, anasarca, or an infected/ulcerated leg"}, "findings": [{"id": "pitting-edema", "region": "extremities", "maneuver": "Press a fingertip firmly over the dorsum of the foot or the medial malleolus for several seconds, then release", "finding": "A persistent dent (pitting) that slowly refills", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "bilateral-symmetric", "region": "extremities", "maneuver": "Compare both lower legs and ankles side by side", "finding": "Symmetric bilateral swelling", "frequency": "almost_always", "significance": "supports", "importance": "essential"}, {"id": "dependent-distribution", "region": "extremities", "maneuver": "Inspect the feet, ankles and legs with the patient seated or standing", "finding": "Swelling is greatest in the most dependent areas and improves with elevation", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "skin-tight-shiny", "region": "skin", "maneuver": "Inspect the skin over the swollen legs", "finding": "Skin is stretched, shiny and taut", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "sock-marks", "region": "skin", "maneuver": "Inspect the lower legs for indentations from socks or shoes", "finding": "Deep sock or shoe marks", "frequency": "common", "significance": "supports", "importance": "optional"}, {"id": "stasis-changes", "region": "skin", "maneuver": "Inspect the lower legs for brown discoloration, varicosities or ulcers", "finding": "Hemosiderin staining, varicose veins or a medial malleolar ulcer suggesting chronic venous disease", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "jvd", "region": "neck", "maneuver": "Inspect the internal jugular vein with the patient at 30–45 degrees", "finding": "Elevated jugular venous pressure", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "essential"}, {"id": "s3-gallop", "region": "cardiac", "maneuver": "Auscultate the heart at the apex with the bell", "finding": "Third heart sound (S3 gallop)", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "crackles", "region": "lung", "maneuver": "Auscultate the lung bases", "finding": "Bibasilar crackles", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "ascites", "region": "abdomen", "maneuver": "Percuss the flanks and test for shifting dullness", "finding": "Ascites with abdominal distension", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "periorbital-edema", "region": "heent", "maneuver": "Inspect the face and around the eyes in the morning", "finding": "Periorbital or facial puffiness suggesting renal causes", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "unilateral-swelling", "region": "extremities", "maneuver": "Compare calf size and palpate the calf on the more swollen side", "finding": "One-sided calf swelling and tenderness suggesting deep vein thrombosis", "frequency": "rare", "significance": "argues_against", "importance": "essential"}, {"id": "calf-pain-warmth", "region": "extremities", "maneuver": "Palpate the calf and check for warmth and erythema", "finding": "Unilateral warmth, redness and tenderness suggesting cellulitis or DVT", "frequency": "rare", "significance": "argues_against", "importance": "essential"}, {"id": "nonpitting-edema", "region": "extremities", "maneuver": "Press firmly over the swollen area and observe whether a dent remains", "finding": "Firm, non-pitting swelling suggesting lymphedema or myxedema", "frequency": "rare", "significance": "argues_against", "importance": "important"}, {"id": "no-joint-swelling", "region": "musculoskeletal", "maneuver": "Palpate the knees and ankles for warmth, effusion and synovitis", "finding": "No joint effusion or synovitis", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-lung-exam", "region": "lung", "maneuver": "Auscultate all lung fields", "finding": "Clear lungs without crackles or wheeze", "frequency": "sometimes", "significance": "neutral", "importance": "important"}]}, "vitals": {"temp": {"mild": {"min": 97.8, "max": 99.1}, "moderate": {"min": 97.8, "max": 99.5}, "severe": {"min": 97.5, "max": 100.0}, "critical": {"min": 96.5, "max": 102.0}}, "hr": {"mild": {"min": 60, "max": 95}, "moderate": {"min": 70, "max": 105}, "severe": {"min": 85, "max": 120}, "critical": {"min": 100, "max": 140}}, "rr": {"mild": {"min": 12, "max": 20}, "moderate": {"min": 14, "max": 22}, "severe": {"min": 18, "max": 28}, "critical": {"min": 22, "max": 34}}, "sbp": {"mild": {"min": 100, "max": 140}, "moderate": {"min": 95, "max": 150}, "severe": {"min": 85, "max": 160}, "critical": {"min": 70, "max": 180}}, "dbp": {"mild": {"min": 60, "max": 85}, "moderate": {"min": 55, "max": 90}, "severe": {"min": 50, "max": 100}, "critical": {"min": 40, "max": 110}}, "spo2": {"mild": {"min": 95, "max": 100}, "moderate": {"min": 92, "max": 98}, "severe": {"min": 88, "max": 95}, "critical": {"min": 80, "max": 92}}}, "labs": [{"test_id": "bnp", "ranges": {"moderate": {"min": 150, "max": 600}, "severe": {"min": 400, "max": 2000}, "critical": {"min": 900, "max": 5000}}, "frequency": "common", "importance": "essential", "caveat": "A low value makes heart failure unlikely as the cause of the swelling; higher values track with worse heart failure but are also raised in kidney disease and with age."}, {"test_id": "nt_probnp", "ranges": {"moderate": {"min": 300, "max": 1500}, "severe": {"min": 1000, "max": 6000}, "critical": {"min": 3000, "max": 15000}}, "frequency": "common", "importance": "important", "caveat": "Interpret with age and kidney function; values rise as GFR falls."}, {"test_id": "cr", "ranges": {"mild": {"min": 1.2, "max": 1.6}, "moderate": {"min": 1.5, "max": 2.5}, "severe": {"min": 2.2, "max": 4.5}, "critical": {"min": 3.5, "max": 8.0}}, "frequency": "common", "importance": "essential", "caveat": "A rising creatinine points to a renal cause or to over-diuresis; a normal value does not exclude nephrotic syndrome."}, {"test_id": "bun", "ranges": {"moderate": {"min": 22, "max": 40}, "severe": {"min": 35, "max": 70}, "critical": {"min": 50, "max": 100}}, "frequency": "common", "importance": "important", "caveat": "Rises with reduced kidney perfusion, heart failure and diuresis."}, {"test_id": "albumin", "ranges": {"mild": {"min": 3.0, "max": 3.4}, "moderate": {"min": 2.4, "max": 3.0}, "severe": {"min": 1.8, "max": 2.4}, "critical": {"min": 1.2, "max": 1.8}}, "frequency": "common", "importance": "essential", "caveat": "Low albumin suggests nephrotic syndrome, cirrhosis or protein-losing states and lowers the effective response to diuretics."}, {"test_id": "protein", "ranges": {"mild": {"min": 5.5, "max": 6.0}, "moderate": {"min": 4.8, "max": 5.5}, "severe": {"min": 4.0, "max": 4.8}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "tbili", "ranges": {"mild": {"min": 1.3, "max": 2.0}, "moderate": {"min": 1.8, "max": 3.5}, "severe": {"min": 3.0, "max": 8.0}, "critical": {"min": 6.0, "max": 15.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Raised in hepatic causes of edema and ascites."}, {"test_id": "ast", "ranges": {"mild": {"min": 45, "max": 90}, "moderate": {"min": 80, "max": 200}, "severe": {"min": 150, "max": 500}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "alt", "ranges": {"mild": {"min": 60, "max": 120}, "moderate": {"min": 100, "max": 250}, "severe": {"min": 200, "max": 600}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "alp", "ranges": {"mild": {"min": 150, "max": 250}, "moderate": {"min": 220, "max": 400}, "severe": {"min": 350, "max": 700}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "plt", "ranges": {"mild": {"min": 110, "max": 149}, "moderate": {"min": 70, "max": 110}, "severe": {"min": 40, "max": 70}, "critical": {"min": 20, "max": 40}}, "frequency": "sometimes", "importance": "important", "caveat": "Thrombocytopenia with edema suggests cirrhosis with portal hypertension."}, {"test_id": "inr", "ranges": {"mild": {"min": 1.2, "max": 1.5}, "moderate": {"min": 1.4, "max": 2.0}, "severe": {"min": 1.8, "max": 3.0}, "critical": {"min": 2.5, "max": 4.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Prolonged in hepatic synthetic dysfunction; also raised by warfarin."}, {"test_id": "na", "ranges": {"mild": {"min": 131, "max": 134}, "moderate": {"min": 127, "max": 131}, "severe": {"min": 122, "max": 127}, "critical": {"min": 115, "max": 122}}, "frequency": "common", "importance": "essential", "caveat": "Hyponatremia is common in heart failure, cirrhosis and over-diuresis; it limits how aggressively diuretics can be pushed."}, {"test_id": "k", "ranges": {"mild": {"min": 3.2, "max": 3.5}, "moderate": {"min": 2.8, "max": 3.2}, "severe": {"min": 2.4, "max": 2.8}, "critical": {"min": 2.0, "max": 2.4}}, "frequency": "common", "importance": "essential", "caveat": "Loop and thiazide diuretics cause hypokalemia; kidney disease and potassium-sparing diuretics cause hyperkalemia."}, {"test_id": "hco3", "ranges": {"mild": {"min": 20, "max": 21}, "moderate": {"min": 16, "max": 20}, "severe": {"min": 12, "max": 16}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "glucose", "ranges": {"mild": {"min": 100, "max": 140}, "moderate": {"min": 140, "max": 250}, "severe": {"min": 200, "max": 400}}, "frequency": "sometimes", "importance": "optional", "caveat": "Diabetes is a common driver of kidney disease and edema."}, {"test_id": "tsh", "ranges": {"mild": {"min": 4.5, "max": 8.0}, "moderate": {"min": 8.0, "max": 15.0}, "severe": {"min": 15.0, "max": 40.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Severe hypothyroidism causes non-pitting myxedema; it is a treatable cause of swelling."}, {"test_id": "ua_protein", "qualitative": {"mild": "Trace", "moderate": "1+", "severe": "3+"}, "frequency": "common", "importance": "essential", "caveat": "Protein on dipstick points to a renal cause; quantify with a urine protein-to-creatinine ratio."}, {"test_id": "ua_blood", "qualitative": {"moderate": "1+", "severe": "2+"}, "frequency": "sometimes", "importance": "important", "caveat": "Blood with protein suggests glomerulonephritis rather than nephrotic syndrome."}, {"test_id": "ua_casts", "qualitative": {"moderate": "RBC casts", "severe": "RBC casts"}, "frequency": "rare", "importance": "important", "caveat": "RBC casts are specific for glomerulonephritis."}, {"test_id": "hgb", "ranges": {"mild": {"min": 10.5, "max": 11.9}, "moderate": {"min": 8.5, "max": 10.5}, "severe": {"min": 7.0, "max": 8.5}, "critical": {"min": 5.5, "max": 7.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Anemia with edema suggests chronic kidney disease or cirrhosis."}, {"test_id": "hs_tnt", "ranges": {"moderate": {"min": 25, "max": 100}, "severe": {"min": 80, "max": 400}, "critical": {"min": 200, "max": 2000}}, "frequency": "sometimes", "importance": "important", "caveat": "Ordered when edema comes with chest pain or acute decompensated heart failure; a rise suggests an acute coronary syndrome or demand ischemia."}, {"test_id": "hcg", "frequency": "almost_always", "importance": "essential", "caveat": "Negative. Required in anyone who could be pregnant before imaging and before starting diuretics or renin-angiotensin blockade; new swelling with headache or visual change in pregnancy suggests preeclampsia."}], "ecg": {"findings": [{"feature": "rhythm", "finding": "Atrial fibrillation", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "rate", "finding": "Sinus tachycardia", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "qrs", "finding": "Low voltage in the limb leads", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "other", "finding": "Left ventricular hypertrophy with repolarization changes", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "st", "finding": "Diffuse ST depression and T-wave flattening suggesting strain", "frequency": "rare", "min_severity": "severe"}, {"feature": "other", "finding": "Electrical alternans with low voltage suggesting a large pericardial effusion", "frequency": "rare", "min_severity": "severe"}]}, "imaging": [{"study": "Transthoracic echocardiogram", "modality": "echo", "findings": [{"text": "Reduced left ventricular ejection fraction with dilated chambers", "frequency": "common"}, {"text": "Left ventricular hypertrophy with preserved or mildly reduced ejection fraction", "frequency": "common"}, {"text": "Moderate or greater diastolic dysfunction", "frequency": "common"}, {"text": "Dilated inferior vena cava that does not collapse with inspiration", "frequency": "common"}, {"text": "Moderate or larger pericardial effusion", "frequency": "rare"}, {"text": "Severe tricuspid regurgitation with right ventricular dilation suggesting right heart failure", "frequency": "sometimes"}, {"text": "Normal study", "frequency": "sometimes"}]}, {"study": "Chest x-ray", "modality": "xray", "findings": [{"text": "Cardiomegaly", "frequency": "common"}, {"text": "Pulmonary vascular congestion or interstitial edema", "frequency": "common"}, {"text": "Bilateral pleural effusions", "frequency": "sometimes"}, {"text": "Normal heart size and clear lungs", "frequency": "sometimes"}]}, {"study": "Ultrasound of the lower extremity veins with compression", "modality": "ultrasound", "preferred_when": "Unilateral or asymmetric leg swelling, or calf pain and warmth", "findings": [{"text": "Noncompressible deep vein with echogenic thrombus", "frequency": "common"}, {"text": "Absent or reduced phasic flow in the deep veins with Valsalva", "frequency": "common"}, {"text": "No deep vein thrombus identified", "frequency": "common"}]}, {"study": "Ultrasound of the abdomen with Doppler of the portal and hepatic veins", "modality": "ultrasound", "findings": [{"text": "Coarse echogenic liver with nodular contour suggesting cirrhosis", "frequency": "common"}, {"text": "Ascites", "frequency": "common"}, {"text": "Splenomegaly", "frequency": "sometimes"}, {"text": "Reversed or reduced portal venous flow", "frequency": "sometimes"}, {"text": "Small, echogenic kidneys suggesting chronic kidney disease", "frequency": "sometimes"}]}, {"study": "CT abdomen and pelvis with IV contrast", "modality": "ct", "preferred_when": "When cirrhosis, portal vein thrombosis or malignancy is suspected and ultrasound is inconclusive", "findings": [{"text": "Nodular liver with ascites and varices", "frequency": "common"}, {"text": "Portal or splenic vein thrombosis", "frequency": "sometimes"}, {"text": "Bilateral enlarged kidneys suggesting nephrotic syndrome", "frequency": "rare"}]}, {"study": "Renal ultrasound", "modality": "ultrasound", "findings": [{"text": "Enlarged echogenic kidneys suggesting nephrotic syndrome", "frequency": "sometimes"}, {"text": "Small echogenic kidneys suggesting chronic kidney disease", "frequency": "common"}, {"text": "Hydronephrosis", "frequency": "rare"}]}], "workup": {"initial": [{"test": "cbc", "why": "Anemia, thrombocytopenia or leukocytosis point to kidney disease, cirrhosis or infection"}, {"test": "bmp", "why": "Assesses kidney function, sodium and potassium before and during diuresis"}, {"test": "cmp_extra", "why": "Albumin, bilirubin and transaminases screen for hepatic and nephrotic causes"}, {"test": "ua", "why": "Protein, blood and casts separate renal causes from cardiac and venous ones"}, {"test": "bnp", "why": "Supports or argues against heart failure as the cause of the swelling"}, {"test": "tsh", "why": "Hypothyroidism is a treatable cause of non-pitting edema"}, {"test": "hcg", "why": "Rules out pregnancy before imaging and before starting diuretics or renin-angiotensin blockade"}, {"test": "Transthoracic echocardiogram", "why": "Defines cardiac structure and function when heart failure is suspected"}, {"test": "Chest x-ray", "why": "Looks for cardiomegaly, congestion and pleural effusions", "only_if": "dyspnea, orthopnea or crackles are present"}, {"test": "Ultrasound of the lower extremity veins with compression", "why": "Rules out deep vein thrombosis", "only_if": "swelling is unilateral or asymmetric, or the calf is painful and warm"}], "confirmatory": [{"test": "Urine protein-to-creatinine ratio", "why": "Quantifies proteinuria and confirms nephrotic-range protein loss when the dipstick is positive"}], "supporting": [{"test": "nt_probnp", "why": "Alternative natriuretic peptide when BNP is unavailable"}, {"test": "hs_tnt", "why": "Looks for myocardial injury when edema comes with chest pain or acute decompensation"}, {"test": "crp", "why": "Supports an inflammatory or infectious process such as cellulitis"}, {"test": "Ultrasound of the abdomen with Doppler of the portal and hepatic veins", "why": "Confirms cirrhosis and portal hypertension", "only_if": "ascites, thrombocytopenia or abnormal liver tests are present"}, {"test": "Renal ultrasound", "why": "Assesses kidney size and echogenicity", "only_if": "proteinuria or reduced kidney function is found"}], "not_indicated": [{"test": "d_dimer", "why": "Low specificity in edema; a negative result may help only when DVT is unlikely and imaging is not readily available"}, {"test": "ct abdomen and pelvis with IV contrast", "why": "Not a routine test for edema; reserved for suspected portal vein thrombosis or malignancy", "only_if": "cirrhosis or malignancy is suspected and ultrasound is inconclusive"}, {"test": "lipase", "why": "No role unless abdominal pain suggests pancreatitis"}, {"test": "abg", "why": "Not needed unless there is respiratory distress or a suspected acid-base disorder"}, {"test": "csf", "why": "No role in peripheral edema"}, {"test": "procalcitonin", "why": "Not needed unless infection such as cellulitis is suspected"}], "decision_points": ["Decide first whether the swelling is localized or generalized: unilateral swelling needs venous ultrasound, generalized swelling needs a cardiac, renal and hepatic workup", "Check a pregnancy test before imaging and before starting diuretics or renin-angiotensin blockade in anyone who could be pregnant", "A low BNP makes heart failure unlikely; a high BNP can also come from kidney disease, so interpret with creatinine and age", "Dipstick protein should be quantified with a urine protein-to-creatinine ratio before labeling nephrotic syndrome", "Weigh the patient daily during diuresis; a rapid creatinine rise or hypotension means the diuretic dose is too high"], "criteria": [], "scores": []}, "differential": [{"name": "Deep vein thrombosis", "slug": "deep-vein-thrombosis", "why_considered": "Unilateral or asymmetric leg swelling is the classic presentation and can be mistaken for dependent edema", "must_not_miss": true, "trigger": "Swelling that is unilateral, asymmetric, or accompanied by calf pain, warmth or recent immobility", "discriminators": {"history": ["Recent surgery, hospitalization, long travel or immobilization", "Active cancer or prior VTE", "Calf pain or tightness on the affected side"], "exam": ["Calf circumference difference of 3 cm or more", "Unilateral warmth, erythema and tenderness along the deep veins"], "labs": ["D-dimer negative makes DVT unlikely in low-risk patients"], "imaging": ["Noncompressible deep vein with echogenic thrombus on compression ultrasound"]}}, {"name": "Cellulitis", "slug": "cellulitis", "why_considered": "A swollen, red, warm leg can look like edema with skin changes", "must_not_miss": true, "trigger": "Fever, rapidly spreading erythema, or focal pain out of proportion to the swelling", "discriminators": {"history": ["Fever and chills", "Rapid onset over hours to a day", "Skin break, insect bite or prior episode"], "exam": ["Unilateral, sharply demarcated erythema with warmth and tenderness", "Lymphangitic streaking or regional lymphadenopathy"], "labs": ["Leukocytosis", "Elevated inflammatory markers"]}}, {"name": "Heart failure", "slug": "heart-failure", "why_considered": "The most common systemic cause of bilateral pitting leg edema", "must_not_miss": false, "discriminators": {"history": ["Exertional dyspnea, orthopnea, paroxysmal nocturnal dyspnea", "Rapid weight gain over days"], "exam": ["Elevated jugular venous pressure", "S3 gallop, bibasilar crackles", "Edema improves overnight with elevation"], "labs": ["Elevated BNP or NT-proBNP"], "imaging": ["Reduced ejection fraction or diastolic dysfunction on echocardiogram", "Cardiomegaly and pulmonary congestion on chest x-ray"]}}, {"name": "Nephrotic syndrome", "slug": "nephrotic-syndrome", "why_considered": "Generalized edema with periorbital and facial puffiness, especially in younger patients", "must_not_miss": false, "discriminators": {"history": ["Foamy urine", "Recent weight gain and generalized swelling", "Periorbital puffiness worse in the morning"], "exam": ["Periorbital or facial edema", "Anasarca in severe cases"], "labs": ["Proteinuria 3+ or more on dipstick", "Low serum albumin", "Urine protein-to-creatinine ratio in the nephrotic range"], "imaging": ["Enlarged echogenic kidneys on renal ultrasound"]}}, {"name": "Cirrhosis with portal hypertension", "slug": "cirrhosis", "why_considered": "Ascites and peripheral edema from low albumin and portal hypertension", "must_not_miss": false, "discriminators": {"history": ["Heavy alcohol use or chronic hepatitis", "Abdominal distension, easy bruising", "Jaundice"], "exam": ["Ascites with shifting dullness", "Spider angiomata, palmar erythema, caput medusae", "Splenomegaly"], "labs": ["Thrombocytopenia", "Low albumin", "Prolonged INR", "Elevated bilirubin"], "imaging": ["Coarse nodular liver with ascites and splenomegaly on ultrasound"]}}, {"name": "Chronic venous insufficiency", "slug": "chronic-venous-insufficiency", "why_considered": "Long-standing bilateral leg swelling that worsens through the day and improves with elevation", "must_not_miss": false, "discriminators": {"history": ["Years of swelling worse in the evening and in warm weather", "Improves with leg elevation and compression", "Often worse after prolonged standing"], "exam": ["Hemosiderin staining, varicose veins, medial malleolar ulcers", "Pitting edema without tenderness or warmth"], "imaging": ["Venous reflux or obstruction on duplex ultrasound"]}}, {"name": "Lymphedema", "slug": "lymphedema", "why_considered": "Non-pitting, firm swelling that does not improve overnight", "must_not_miss": false, "discriminators": {"history": ["Prior lymph node dissection, radiation or recurrent cellulitis", "Swelling is progressive and does not improve with elevation or diuretics"], "exam": ["Non-pitting, firm, thickened skin", "Positive Stemmer sign (unable to pinch the dorsal skin fold of the toe)"], "imaging": ["Lymphoscintigraphy showing impaired lymphatic drainage"]}}, {"name": "Hypothyroidism with myxedema", "slug": "hypothyroidism", "why_considered": "Non-pitting edema with fatigue and weight gain", "must_not_miss": false, "discriminators": {"history": ["Cold intolerance, constipation, dry skin, hair loss", "Weight gain despite poor appetite"], "exam": ["Non-pitting, doughy swelling of the face, hands and legs", "Delayed relaxation of deep tendon reflexes", "Bradycardia"], "labs": ["Elevated TSH with low free T4"]}}, {"name": "Medication-related edema", "slug": "medication-related-edema", "why_considered": "Common cause of bilateral dependent edema with no other systemic findings", "must_not_miss": false, "discriminators": {"history": ["Started amlodipine, nifedipine, gabapentin, pregabalin, pioglitazone or a NSAID weeks before the swelling", "Swelling improves when the drug is stopped"], "exam": ["Bilateral pitting edema without jugular venous distension, crackles or ascites"], "labs": ["Normal BNP, creatinine and albumin"]}}], "course": {"severity": {"mild": "Swelling noticed mainly by tight shoes or socks; no dyspnea, no weight change, normal vitals and oxygen saturation", "moderate": "Visible bilateral pitting edema with heaviness and evening worsening; mild exertional dyspnea or modest weight gain; may have elevated jugular venous pressure or crackles", "severe": "Tense, shiny legs with marked pitting, orthopnea, dyspnea on minimal exertion, ascites or anasarca; hypoxemia or hypotension may be present", "critical": "Respiratory distress at rest, anasarca with hemodynamic compromise, or an infected or ulcerated leg with sepsis; also flash pulmonary edema or cardiogenic shock"}, "red_flags": [{"finding": "Unilateral leg swelling with calf pain or warmth", "meaning": "Deep vein thrombosis until proven otherwise; needs compression ultrasound"}, {"finding": "Fever, spreading erythema or focal tenderness", "meaning": "Cellulitis or necrotizing infection; needs urgent antibiotics and possibly surgical evaluation"}, {"finding": "Dyspnea at rest, orthopnea or new hypoxemia", "meaning": "Acute decompensated heart failure or pulmonary edema; needs urgent treatment"}, {"finding": "Rapid weight gain over days with worsening edema", "meaning": "Volume overload from heart failure or renal disease; diuresis may be needed"}, {"finding": "New facial or hand swelling with headache or visual changes in pregnancy", "meaning": "Preeclampsia; needs urgent blood pressure and laboratory evaluation"}, {"finding": "Hypotension or tachycardia with edema", "meaning": "Cardiogenic shock, sepsis or over-diuresis; reassess volume status and diuretic dose"}], "complications": [{"name": "Skin breakdown and stasis ulceration", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Long-standing edema with hemosiderin staining", "Medial malleolar ulcer", "Non-healing wound"]}, {"name": "Cellulitis of the swollen leg", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Fever", "Unilateral warmth and erythema", "Leukocytosis"]}, {"name": "Acute kidney injury from over-diuresis", "timing": "early", "seriousness": "serious", "frequency": "sometimes", "clues": ["Rising creatinine", "Hypotension", "Reduced urine output"]}, {"name": "Electrolyte abnormalities from diuretics", "timing": "early", "seriousness": "serious", "frequency": "common", "clues": ["Hypokalemia or hyponatremia", "Arrhythmia", "Muscle cramps or weakness"]}, {"name": "Pulmonary edema and respiratory failure", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Orthopnea", "Bibasilar crackles", "Hypoxemia"]}, {"name": "Sepsis from infected edematous tissue", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Hypotension", "High fever", "Altered mental status"]}], "special_populations": [{"population": "older_adults", "differences": "Heart failure, kidney disease and medication effects are more common; swelling may be attributed to aging or arthritis, and diuresis must be cautious because of reduced renal reserve."}, {"population": "pregnancy", "differences": "Mild symmetric leg swelling is expected in the third trimester; new facial or hand swelling with headache or visual changes suggests preeclampsia and needs urgent evaluation. Avoid diuretics and renin-angiotensin blockade."}, {"population": "renal_impairment", "differences": "Edema is often generalized with periorbital puffiness, foamy urine and reduced urine output; diuretic response is blunted by low albumin and reduced GFR, and electrolytes need close monitoring."}, {"population": "hepatic_impairment", "differences": "Swelling comes with ascites, easy bruising and jaundice; albumin is low, INR is prolonged and thrombocytopenia is common. Avoid NSAIDs and large-volume paracentesis without albumin."}, {"population": "children", "differences": "Edema is more often from nephrotic syndrome or allergic reactions; periorbital swelling in the morning is a common clue and blood pressure should be checked."}, {"population": "obesity", "differences": "Swelling may be attributed to weight alone; obesity-related lymphedema and venous insufficiency are common, and BNP interpretation is less reliable."}]}, "teaching": {"key_questions": [{"question": "Is the swelling in one leg or both?", "category": "hpi", "importance": "essential", "looking_for": "Bilateral and symmetric suggests a systemic cause; unilateral or asymmetric raises concern for deep vein thrombosis or cellulitis"}, {"question": "When did it start, and has it been getting worse?", "category": "hpi", "importance": "essential", "looking_for": "Gradual over days to weeks suggests a systemic cause; sudden onset over hours suggests thrombosis or infection"}, {"question": "Is it worse at the end of the day and better after a night in bed with your legs up?", "category": "hpi", "importance": "important", "looking_for": "Evening worsening that improves with elevation fits dependent edema from heart, kidney or venous disease"}, {"question": "Does pressing on the swollen area leave a dent?", "category": "hpi", "importance": "important", "looking_for": "Pitting suggests cardiac, renal, hepatic or venous causes; firm non-pitting swelling suggests lymphedema or myxedema"}, {"question": "Where else are you swollen — face, hands, belly?", "category": "hpi", "importance": "important", "looking_for": "Periorbital or facial puffiness suggests a renal cause; abdominal distension suggests ascites from cirrhosis or heart failure"}, {"question": "Have you gained weight recently, and over how long?", "category": "associated", "importance": "important", "looking_for": "Rapid weight gain over days suggests volume overload from heart failure or renal disease"}, {"question": "Are you short of breath with activity, or do you wake up short of breath at night?", "category": "associated", "importance": "essential", "looking_for": "Exertional dyspnea, orthopnea and paroxysmal nocturnal dyspnea point to heart failure"}, {"question": "Do you need more pillows to sleep comfortably?", "category": "associated", "importance": "important", "looking_for": "Orthopnea suggests pulmonary congestion from heart failure"}, {"question": "Is your urine foamy, bloody or reduced in amount?", "category": "associated", "importance": "important", "looking_for": "Foamy urine suggests proteinuria; blood suggests glomerulonephritis; reduced output suggests kidney failure"}, {"question": "Do your legs feel painful, warm or red on one side?", "category": "red_flag", "importance": "essential", "looking_for": "Unilateral pain, warmth and redness suggest deep vein thrombosis or cellulitis and need urgent evaluation"}, {"question": "Any fever or chills?", "category": "red_flag", "importance": "essential", "looking_for": "Fever with a swollen red leg suggests cellulitis or another infection"}, {"question": "Have you had recent surgery, a hospitalization, long travel, or been off your feet?", "category": "pmh", "importance": "important", "looking_for": "Recent immobility or surgery raises the risk of deep vein thrombosis"}, {"question": "Have you been told you have heart failure, kidney disease or liver problems?", "category": "pmh", "importance": "essential", "looking_for": "Established cardiac, renal or hepatic disease makes that cause much more likely"}, {"question": "Have you had cancer treatment, lymph node surgery or radiation?", "category": "pmh", "importance": "important", "looking_for": "Prior lymph node dissection or radiation suggests lymphedema"}, {"question": "What medications do you take, including anything new in the last few weeks?", "category": "medications", "importance": "essential", "looking_for": "Amlodipine, nifedipine, gabapentin, pregabalin, pioglitazone, prednisone or NSAIDs can cause edema"}, {"question": "Do you take water pills, and have you missed any doses?", "category": "medications", "importance": "important", "looking_for": "Missed diuretics explain worsening swelling; over-diuresis explains hypotension and rising creatinine"}, {"question": "How much salt do you eat, and do you add salt at the table?", "category": "social", "importance": "important", "looking_for": "High sodium intake worsens edema and blunts diuretic response"}, {"question": "Do you stand or sit for long periods at work?", "category": "social", "importance": "optional", "looking_for": "Prolonged standing supports dependent or venous edema"}, {"question": "Could you be pregnant? When was your last period?", "category": "obstetric", "importance": "essential", "looking_for": "Pregnancy changes the workup; new facial or hand swelling with headache or visual changes suggests preeclampsia"}, {"question": "Any chest pain, palpitations or fainting?", "category": "ros", "importance": "important", "looking_for": "Cardiac symptoms raise concern for heart failure or an acute coronary syndrome"}, {"question": "Any vomiting blood, black stools or yellowing of the eyes or skin?", "category": "ros", "importance": "important", "looking_for": "Suggests cirrhosis with portal hypertension and varices"}, {"question": "Any joint swelling or morning stiffness?", "category": "ros", "importance": "optional", "looking_for": "Joint involvement suggests an inflammatory arthritis rather than edema"}, {"question": "Any cold intolerance, constipation or dry skin?", "category": "ros", "importance": "optional", "looking_for": "Hypothyroidism is a treatable cause of non-pitting edema"}], "accepted_names": ["Edema", "Peripheral edema", "Pedal edema", "Lower extremity edema", "Leg swelling", "Dependent edema", "Anasarca", "Generalized edema", "Swelling", "Dropsy"], "reasoning_points": ["Bilateral symmetric pitting edema that worsens through the day and improves with elevation", "Distribution and associated symptoms point to a cardiac, renal, hepatic or venous cause rather than a local one", "Exertional dyspnea, orthopnea or paroxysmal nocturnal dyspnea with elevated jugular venous pressure or crackles supports heart failure", "Foamy urine, periorbital puffiness or reduced urine output with proteinuria and low albumin supports a renal cause", "Ascites, thrombocytopenia, low albumin and prolonged INR support cirrhosis with portal hypertension", "A new medication such as amlodipine, gabapentin or an NSAID is a common and reversible cause", "Unilateral swelling with calf pain or warmth must be evaluated for deep vein thrombosis or cellulitis before assuming systemic edema", "Pregnancy must be excluded before imaging and before starting diuretics or renin-angiotensin blockade", "A low BNP makes heart failure unlikely, while a high BNP can also come from kidney disease and must be interpreted with creatinine and age"], "difficulty": {"easy": ["Older adult with known heart failure and classic evening-worsening bilateral pitting leg edema", "Orthopnea, elevated jugular venous pressure, bibasilar crackles and an elevated BNP", "Echocardiogram shows reduced ejection fraction"], "medium": ["New amlodipine started weeks before the swelling, with a normal cardiac, renal and hepatic workup", "Nephrotic syndrome with periorbital puffiness, foamy urine and low albumin", "Cirrhosis with ascites, thrombocytopenia and prolonged INR", "Chronic venous insufficiency with years of evening swelling, hemosiderin staining and varicose veins"], "hard": ["Unilateral leg swelling with calf pain in a patient who also has chronic bilateral edema", "Non-pitting firm swelling after lymph node dissection that does not improve with elevation or diuretics", "Hypothyroidism with doughy non-pitting swelling, fatigue and weight gain", "Pregnant patient with new facial and hand swelling and headache suggesting preeclampsia", "Older adult on multiple medications with edema attributed to aging, where a drug cause is the real explanation"]}}}$rounds_kb$::jsonb)
