ion": "Generalized, whole-body; not localized", "radiation": "Not applicable", "quality": "A pervasive sense of weariness, low energy and reduced capacity to do usual activities; distinct from sleepiness or muscle weakness", "severity": "Mild to moderate; interferes with work, household tasks and social activities", "timing": "Present most of the day; often worse later in the day and after exertion", "aggravating": ["Physical exertion", "Stress", "Poor sleep", "Long work hours"], "relieving": ["Rest or a good night's sleep (partial, if at all)", "Caffeine (temporary)"], "associated_symptoms": [{"text": "Feeling sleepy during the day", "frequency": "common"}, {"text": "Difficulty concentrating or remembering", "frequency": "common"}, {"text": "Low mood or loss of interest", "frequency": "common"}, {"text": "Poor sleep, unrefreshing sleep or waking frequently", "frequency": "common"}, {"text": "Muscle aches or generalized soreness", "frequency": "sometimes"}, {"text": "Shortness of breath with activity", "frequency": "sometimes"}, {"text": "Headache", "frequency": "sometimes"}, {"text": "Weight change", "frequency": "sometimes"}, {"text": "Feeling cold or heat intolerance", "frequency": "sometimes"}, {"text": "Dizziness or lightheadedness on standing", "frequency": "sometimes"}, {"text": "Loss of appetite", "frequency": "sometimes"}], "pertinent_negatives": ["Chest pain or pressure", "Fainting or loss of consciousness", "Focal weakness, numbness or trouble speaking", "Unintentional weight loss", "Fever or night sweats", "Blood in stool or black stools", "Heavy or abnormal vaginal bleeding", "New severe headache", "Suicidal thoughts", "Substance withdrawal"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Tiredness and low energy", "frequency": "almost_always"}, {"text": "Feeling run down", "frequency": "common"}, {"text": "Unintentional weight change", "frequency": "sometimes"}], "negatives": ["Fever", "Night sweats", "Unintentional weight loss"], "argues_against": ["Occult malignancy or chronic infection"]}, {"system": "cardiovascular", "positives": [{"text": "Shortness of breath with activity", "frequency": "sometimes"}, {"text": "Palpitations", "frequency": "sometimes"}, {"text": "Lightheadedness on standing", "frequency": "sometimes"}], "negatives": ["Chest pain", "Fainting", "Swelling of the legs"], "argues_against": ["Decompensated heart failure or acute coronary syndrome"]}, {"system": "respiratory", "positives": [{"text": "Shortness of breath on exertion", "frequency": "sometimes"}], "negatives": ["Chronic cough", "Wheezing", "Coughing up blood"], "argues_against": ["Uncontrolled COPD or lung disease"]}, {"system": "gastrointestinal", "positives": [{"text": "Poor appetite", "frequency": "sometimes"}, {"text": "Nausea", "frequency": "sometimes"}], "negatives": ["Blood in stool", "Black stools", "Vomiting blood", "Jaundice"], "argues_against": ["GI bleeding or liver disease"]}, {"system": "genitourinary", "positives": [], "negatives": ["Blood in urine", "Flank pain", "Urinary frequency or urgency"], "argues_against": ["Urinary tract infection or renal disease"]}, {"system": "musculoskeletal", "positives": [{"text": "Generalized muscle aches", "frequency": "sometimes"}, {"text": "Joint pain", "frequency": "sometimes"}], "negatives": ["Joint swelling", "Morning stiffness lasting more than an hour", "Muscle weakness"], "argues_against": ["Inflammatory arthritis or myositis"]}, {"system": "neurologic", "positives": [{"text": "Trouble concentrating", "frequency": "common"}, {"text": "Headache", "frequency": "sometimes"}, {"text": "Dizziness", "frequency": "sometimes"}], "negatives": ["Focal weakness or numbness", "Trouble speaking", "Vision changes", "Seizures"], "argues_against": ["Stroke or neurologic disease"]}, {"system": "psychiatric", "positives": [{"text": "Low mood or sadness", "frequency": "common"}, {"text": "Loss of interest in activities", "frequency": "common"}, {"text": "Anxiety or worry", "frequency": "common"}, {"text": "Trouble sleeping", "frequency": "common"}], "negatives": ["Suicidal thoughts", "Hallucinations"], "argues_against": ["Primary psychotic disorder"]}, {"system": "endocrine", "positives": [{"text": "Feeling cold", "frequency": "sometimes"}, {"text": "Heat intolerance", "frequency": "sometimes"}, {"text": "Weight change", "frequency": "sometimes"}], "negatives": ["Excessive thirst", "Frequent urination"], "argues_against": ["Uncontrolled diabetes"]}, {"system": "hematologic", "positives": [{"text": "Pale skin", "frequency": "sometimes"}, {"text": "Easy bruising or bleeding", "frequency": "rare"}], "negatives": ["Blood clots", "Lymph node swelling"], "argues_against": ["Blood dyscrasia or lymphoma"]}, {"system": "skin", "positives": [{"text": "Dry skin", "frequency": "sometimes"}], "negatives": ["Rash", "Jaundice", "Hair loss"], "argues_against": ["Systemic skin or liver disease"]}], "atypical": [{"population": "older_adults", "how_it_differs": "Fatigue may be the only sign of serious illness such as infection, heart failure, anemia or malignancy; patients may underreport it as 'just getting older'.", "missing_classic_features": ["Clear description of low mood or sleep problems", "Fever or focal symptoms"]}, {"population": "pregnancy", "how_it_differs": "Fatigue is common and expected, especially in the first and third trimesters; it can also mask anemia, thyroid disease or depression.", "missing_classic_features": ["Pathologic cause is not always present"]}, {"population": "children", "how_it_differs": "Children may present with irritability, poor school performance, falling asleep in class or refusal to play rather than saying they are tired.", "missing_classic_features": ["Direct report of fatigue"]}, {"population": "diabetes", "how_it_differs": "Fatigue may reflect poor glycemic control, hypoglycemia or associated kidney or thyroid disease rather than a primary sleep or mood cause.", "missing_classic_features": ["Normal glucose and metabolic