insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$headache$rounds_kb$, $rounds_kb$Headache$rounds_kb$, $rounds_kb$neurology$rounds_kb$, array[$rounds_kb$neurology$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$]::text[], array[$rounds_kb$nervous$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "headache", "triage": {"name": "Headache", "case_suitable": true, "reason": "Extremely common symptom with a critical differential from tension and migraine to subarachnoid hemorrhage; reachable by history and exam.", "kind": "symptom", "category": "neurologic symptom", "organ_systems": ["nervous"], "primary_clerkship": "neurology", "secondary_clerkships": ["emergency", "familyMedicine", "internalMedicine"], "commonness": "very_common", "settings": ["clinic", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:17:44Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T06:47:45Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T06:47:54Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T06:48:06Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T06:48:21Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T06:48:29Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'ct head without iv contrast' was in ['initial', 'not_indicated'], kept ['not_indicated', 'initial']", "auto-repaired: workup: 'lumbar puncture' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'mri brain with and without iv contrast' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'ct head without iv contrast' was in ['initial', 'not_indicated'], kept ['not_indicated', 'initial']", "auto-repaired: workup: 'lumbar puncture' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'mri brain with and without iv contrast' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "labs tsh: both high and low across severities", "differential subarachnoid-hemorrhage: no profile yet", "differential bacterial-meningitis: no profile yet", "differential migraine: no profile yet", "differential tension-type-headache: no profile yet", "differential cluster-headache: no profile yet", "differential giant-cell-arteritis: no profile yet", "differential idiopathic-intracranial-hypertension: no profile yet", "differential acute-angle-closure-glaucoma: no profile yet", "differential acute-sinusitis: no profile yet", "differential medication-overuse-headache: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 18, "typical_max": 65, "peak": "25–55", "possible_min": 3, "possible_max": 100}, "sex": "female_predominant", "demographics": ["Tension-type headache is the most common primary headache and affects both sexes fairly equally", "Migraine is about three times more common in women than men", "Cluster headache is more common in men", "Primary headache disorders often begin before age 40"], "risk_factors": [{"text": "Female sex (for migraine)", "strength": "strong"}, {"text": "Family history of migraine or other primary headache", "strength": "strong"}, {"text": "Stress, anxiety or depression", "strength": "moderate"}, {"text": "Poor sleep, skipped meals, dehydration", "strength": "moderate"}, {"text": "Caffeine use or withdrawal", "strength": "moderate"}, {"text": "Alcohol use", "strength": "weak"}, {"text": "Sustained neck or jaw strain (screen work, clenching)", "strength": "weak"}], "comorbidities": ["Anxiety or depression", "Sleep disorders", "Obesity", "Chronic pain syndromes"], "family_history": ["Migraine in a first-degree relative", "Tension-type headache in a first-degree relative"], "social_history": ["High work or school stress", "Irregular sleep schedule", "Skipping meals", "Heavy caffeine use"], "exposures": ["Screen or computer work", "Poor ergonomics", "Secondhand smoke or strong odors (migraine triggers)"], "risk_medications": ["acetaminophen", "ibuprofen", "sumatriptan", "oral contraceptive pills", "nitroglycerin"]}, "presentation": {"chief_complaints": [{"text": "My head hurts", "frequency": "almost_always"}, {"text": "I get these headaches again and again", "frequency": "common"}, {"text": "The pain is on one side and makes me sick to my stomach", "frequency": "sometimes"}], "hpi": {"onset": "Usually gradual over 30 minutes to a few hours; migraine may build up, tension headache is often gradual, and a thunderclap onset is not typical of primary headache", "duration": "Episodes last 30 minutes to several hours for tension-type and 4–72 hours for migraine; cluster attacks last 15–180 minutes", "progression": "Recurrent episodes with a stable pattern over months to years; individual attacks build, plateau and then resolve", "location": "Tension-type: bilateral, band-like across the forehead, temples or back of the head; migraine: often unilateral, frontotemporal; cluster: strictly one-sided around the eye or temple", "radiation": "May spread from the neck and shoulders up into the head; migraine pain can spread across the whole head", "quality": "Tension-type: pressing or tightening, non-pulsating; migraine: throbbing or pulsating; cluster: sharp, boring, stabbing", "severity": "Mild to moderate for tension-type; moderate to severe for migraine; severe for cluster", "timing": "Tension-type is often constant through the day; migraine attacks are episodic; cluster attacks occur in bouts, often at the same time each day and at night", "aggravating": ["Stress", "Lack of sleep", "Skipping meals", "Bright lights or loud noise (migraine)", "Physical activity (migraine)", "Alcohol (cluster and migraine)"], "relieving": ["Resting in a dark, quiet room", "Over-the-counter pain relievers", "Sleep", "Relaxation or massage", "Caffeine (sometimes helps migraine)"], "associated_symptoms": [{"text": "Neck or shoulder tightness", "frequency": "common"}, {"text": "Nausea", "frequency": "common"}, {"text": "Light sensitivity", "frequency": "common"}, {"text": "Sound sensitivity", "frequency": "common"}, {"text": "Vomiting", "frequency": "sometimes"}, {"text": "Visual aura (flashing lights, zigzag lines, blind spots)", "frequency": "sometimes"}, {"text": "Tearing, red eye, runny nose or eyelid droop on one side (cluster)", "frequency": "sometimes"}, {"text": "Restlessness or pacing during the attack (cluster)", "frequency": "sometimes"}], "pertinent_negatives": ["Sudden severe headache reaching maximum in under a minute (thunderclap)", "Fever or stiff neck", "Headache after a head injury", "New confusion, weakness, numbness or trouble speaking", "New headache after age 50", "Headache that is worse when lying down or wakes from sleep", "Painful red eye or vision loss", "Weight loss, night sweats or known cancer", "Progressive worsening over weeks"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Feeling tired during attacks", "frequency": "sometimes"}], "negatives": ["Fever", "Weight loss", "Night sweats"], "argues_against": ["Infection or malignancy as the cause"]}, {"system": "neurologic", "positives": [{"text": "Light or sound sensitivity", "frequency": "common"}, {"text": "Visual aura", "frequency": "sometimes"}], "negatives": ["Weakness", "Numbn