laints": [{"text": "I'm bleeding down there and I'm pregnant", "frequency": "almost_always"}, {"text": "I've been having bad cramps in my belly", "frequency": "common"}, {"text": "I passed some tissue in the toilet", "frequency": "sometimes"}, {"text": "My pregnancy symptoms just stopped", "frequency": "sometimes"}], "hpi": {"onset": "Gradual, over hours to days; bleeding is usually the first sign", "duration": "Symptoms typically present within days of onset; most miscarriages occur before 12 weeks", "progression": "Spotting or light bleeding progresses to heavier bleeding with clots and cramping; tissue may pass; symptoms may resolve or continue depending on whether the pregnancy has fully passed", "location": "Lower abdomen and pelvis, often with low back pain", "radiation": "Cramping may radiate to the lower back or sacrum", "quality": "Crampy, period-like pelvic pain with vaginal bleeding", "severity": "Mild to moderate; can become severe if heavy bleeding or incomplete passage occurs", "timing": "Intermittent cramping that comes in waves; bleeding may be continuous", "aggravating": ["Physical activity", "Standing up"], "relieving": ["Rest", "Lying down", "Heat to the lower abdomen"], "associated_symptoms": [{"text": "Vaginal bleeding or spotting", "frequency": "almost_always"}, {"text": "Passage of blood clots", "frequency": "common"}, {"text": "Cramping lower abdominal pain", "frequency": "common"}, {"text": "Low back pain", "frequency": "common"}, {"text": "Passage of grayish or pinkish tissue", "frequency": "sometimes"}, {"text": "Gush of clear or pink fluid from the vagina", "frequency": "sometimes"}, {"text": "Loss of pregnancy symptoms such as breast tenderness or nausea", "frequency": "sometimes"}, {"text": "Dizziness or lightheadedness with heavy bleeding", "frequency": "rare"}], "pertinent_negatives": ["Fever or chills", "Foul-smelling vaginal discharge", "Severe one-sided pelvic pain", "Shoulder tip pain", "Syncope or collapse", "Known ectopic pregna