ession": "Slowly progressive; symptoms may fluctuate with fluid intake, caffeine, and stress", "location": "Lower abdomen and pelvis", "radiation": "None", "quality": "Sudden, strong urge to urinate that is hard to postpone", "severity": "Bothersome and disruptive to daily activities, sleep, and social life; severity varies", "timing": "Daytime frequency and nocturia; urgency episodes occur throughout the day", "aggravating": ["Caffeine", "Alcohol", "Large fluid intake", "Cold weather", "Running water or hand washing", "Stress or anxiety"], "relieving": ["Urinating", "Reducing caffeine and alcohol", "Timed voiding or bladder training"], "associated_symptoms": [{"text": "Urinary frequency (eight or more times a day)", "frequency": "almost_always"}, {"text": "Urgency", "frequency": "almost_always"}, {"text": "Nocturia (two or more times a night)", "frequency": "common"}, {"text": "Urge incontinence", "frequency": "common"}, {"text": "Feeling of incomplete bladder emptying", "frequency": "sometimes"}, {"text": "Pelvic or lower abdominal pressure", "frequency": "sometimes"}], "pertinent_negatives": ["Pain or burning with urination", "Blood in urine", "Fever or chills", "Flank pain", "Sudden severe pain", "Symptoms of urinary retention", "New neurologic deficits", "Weight loss"]}, "ros": [{"system": "genitourinary", "positives": [{"text": "Urinary frequency", "frequency": "almost_always"}, {"text": "Urgency", "frequency": "almost_always"}, {"text": "Nocturia", "frequency": "common"}, {"text": "Urge incontinence", "frequency": "common"}], "negatives": ["Dysuria", "Hematuria", "Flank pain", "Difficulty starting urination", "Weak urinary stream", "Sense of incomplete emptying"], "argues_against": ["Urinary tract infection", "Bladder cancer", "Bladder outlet obstruction"]}, {"system": "gastrointestinal", "positives": [], "negatives": ["Constipation", "Abdominal pain", "Blood in stool"], "argues_against": ["Constipation as a contributor", "Pelvic mass"]}, {"system": "neurologic", "positives": [], "negatives": ["Numbness", "Weakness", "Difficulty walking", "Tremor", "Vision changes"], "argues_against": ["Multiple sclerosis", "Parkinson disease", "Spinal cord lesion"]}, {"system": "psychiatric", "positives": [], "negatives": ["Depressed mood", "Anxiety", "Symptoms of post-traumatic stress"], "argues_against": ["Primary psychiatric cause of urinary symptoms"]}], "atypical": [{"population": "older_adults", "how_it_differs": "Symptoms may be attributed to normal aging or coexisting conditions; nocturia and falls may be the main concerns rather than urgency.", "missing_classic_features": ["Clear description of urgency", "Bothersome daytime frequency"]}, {"population": "pregnancy", "how_it_differs": "Frequency and urgency are common in pregnancy due to uterine pressure and increased fluid volume; symptoms often resolve postpartum.", "missing_classic_features": ["Chronic duration", "Nocturia as a prominent symptom"]}, {"population": "diabetes", "how_it_differs": "Polyuria from hyperglycemia can mimic frequency; urgency may be less prominent than large-volume urination.", "missing_classic_features": ["Small-volume voids", "Predominant urgency"]}, {"population": "obesity", "how_it_differs": "Increased intra-abdominal pressure can worsen urgency and incontinence; weight loss may improve symptoms.", "missing_classic_features": ["Symptoms independent of body weight"]}]}, "exam": {"general": {"mild": "Comfortable, well-appearing, no distress", "moderate": "Comfortable at rest but visibly anxious about access to a toilet; may excuse themselves during the visit", "severe": "Restless or embarrassed, may wear protective padding; otherwise well-appearing", "critical": "Not applicable; overactive bladder is not a critical illness"}, "findings": [{"id": "normal-abdominal-exam", "region": "abdomen", "maneuver": "Inspect and palpate the abdomen, including suprapubic percussion for a distended bladder", "finding": "Soft, non-tender abdomen with no suprapubic fullness or palpable bladder", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-genitalia-exam", "region": "genitourinary", "maneuver": "Inspect the external genitalia and, in men, palpate the testes and penis", "finding": "Normal external genitalia without lesions, discharge, or mass", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-prostate-exam", "region": "rectal", "maneuver": "Perform a digital rectal exam in men to assess prostate size, nodularity, and sphincter tone", "finding": "Smooth, non-nodular prostate; normal anal sphincter tone", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-pelvic-exam", "region": "pelvic", "maneuver": "Perform a pelvic exam in women to inspect for atrophy, prolapse, or mass and to assess for pelvic floor weakness", "finding": "Normal vaginal mucosa without atrophy or mass; no significant prolapse; no pelvic floor tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-neurologic-exam", "region": "neuro", "maneuver": "Test lower extremity strength, sensation, deep tendon reflexes, and gait; assess perineal sensation and anal wink if neurologic disease is suspected", "finding": "Normal strength, sensation, reflexes, and gait; intact perineal sensation and anal wink", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-mental-status", "region": "mental_status", "maneuver": "Assess orientation, attention, and cognition", "finding": "Alert and oriented with normal cognition", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "no-costovertebral-tenderness", "region": "abdomen", "maneuver": "Percuss the costovertebral angles", "finding": "No costovertebral angle tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "no-suprapubic-tenderness", "region": "abdomen", "maneuver": "Palpate the suprapubic region", "finding": "No suprapubic tenderness or palpable bladder", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {}, "labs": [{"test_id": "ua_le", "qualitative": {"mild": "Trace", "moderate": "1+"}, "frequency": "sometimes", "importance": "optional", "caveat": "Mild sterile pyuria can occur without infection; a positive leukocyte esterase with nitrite or bacteria points to urinary tract infection instead."}, {"test_id": "ua_nitrite", "qualitative": {"moderate": "Positive"}, "frequency": "rare", "importance": "optional", "caveat": "A positive nitrite suggests a urinary tract infection rather than overactive bladder and should prompt treatment and reassessment."}, {"test_id": "ua_blood", "qualitative": {"mild": "Trace", "moderate": "1+"}, "frequency": "rare", "importance": "optional", "caveat": "Microscopic hematuria in a patient with irritative voiding symptoms warrants evaluation for bladder cancer or stone."}, {"test_id": "ua_bacteria", "qualitative": {"moderate": "Few", "severe": "Moderate"}, "frequency": "rare", "importance": "optional", "caveat": "Bacteria in the urine suggest infection, not overactive bladder."}, {"test_id": "ua_wbc", "ranges": {"mild": {"min": 6, "max": 15}, "moderate": {"min": 10, "max": 30}}, "frequency": "rare", "importance": "optional", "caveat": "Pyuria is not a feature of uncomplicated overactive bladder; consider infection, stone, or malignancy."}, {"test_id": "glucose", "ranges": {"mild": {"min": 100, "max": 125}, "moderate": {"min": 126, "max": 200}, "severe": {"min": 180, "max": 300}}, "frequency": "sometimes", "importance": "important", "caveat": "Hyperglycemia causes osmotic polyuria that mimics frequency; screen because diabetes is a common contributor."}, {"test_id": "a1c", "ranges": {"mild": {"min": 5.7, "max": 6.4}, "moderate": {"min": 6.5, "max": 9.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Identifies undiagnosed diabetes as a cause of polyuria and frequency."}, {"test_id": "cr", "ranges": {"mild": {"min": 1.2, "max": 1.6}, "moderate": {"min": 1.5, "max": 2.5}}, "frequency": "rare", "importance": "optional", "caveat": "Elevated creatinine suggests chronic kidney disease or obstruction and should be evaluated before attributing symptoms to overactive bladder."}, {"test_id": "hcg", "frequency": "sometimes", "importance": "important", "caveat": "Negative. Pregnancy causes frequency and urgency and must be excluded in anyone who could be pregnant before imaging or treatment."}], "imaging": [{"study": "Bladder ultrasound with post-void residual", "modality": "ultrasound", "preferred_when": "When incomplete emptying or retention is suspected", "findings": [{"text": "Normal bladder wall thickness and no significant post-void residual", "frequency": "common"}, {"text": "Elevated post-void residual suggesting incomplete emptying or outlet obstruction", "frequency": "sometimes"}, {"text": "Bladder wall thickening or trabeculation suggesting chronic obstruction", "frequency": "rare"}]}, {"study": "Renal and bladder ultrasound", "modality": "ultrasound", "preferred_when": "Suspected obstruction, stone, or upper tract disease", "findings": [{"text": "Normal kidneys and bladder without hydronephrosis or stone", "frequency": "common"}, {"text": "Hydronephrosis suggesting obstruction", "frequency": "rare"}, {"text": "Renal or bladder stone", "frequency": "rare"}]}, {"study": "CT urography", "modality": "ct", "preferred_when": "Gross or persistent microscopic hematuria, or suspicion of malignancy or stone", "findings": [{"text": "No mass, stone, or urothelial thickening", "frequency": "common"}, {"text": "Bladder mass or urothelial thickening suggesting malignancy", "frequency": "rare"}, {"text": "Urinary tract stone", "frequency": "rare"}]}, {"study": "Cystoscopy", "modality": "endoscopy", "preferred_when": "Hematuria, suspected bladder cancer, or refractory symptoms", "findings": [{"text": "Normal bladder mucosa without tumor or lesion", "frequency": "common"}, {"text": "Bladder tumor or suspicious mucosal lesion", "frequency": "rare"}]}], "workup": {"initial": [{"test": "ua", "why": "Screens for infection, hematuria, glucosuria, and other causes of irritative voiding symptoms"}, {"test": "glucose", "why": "Excludes diabetes as a cause of polyuria and frequency"}, {"test": "Bladder ultrasound with post-void residual", "why": "Assesses incomplete emptying and bladder wall changes", "only_if": "incomplete emptying, retention, or obstruction is suspected"}], "confirmatory": [], "supporting": [{"test": "a1c", "why": "Confirms or excludes diabetes when glucose is borderline or elevated"}, {"test": "cr", "why": "Assesses kidney function when obstruction or chronic kidney disease is a concern"}, {"test": "hcg", "why": "Excludes pregnancy as a cause of frequency and urgency", "only_if": "the patient could be pregnant"}, {"test": "Renal and bladder ultrasound", "why": "Evaluates for obstruction, stone, or upper tract disease", "only_if": "obstruction, stone, or upper tract disease is suspected"}], "not_indicated": [{"test": "cbc", "why": "Not routinely needed unless infection, anemia, or malignancy is suspected"}, {"test": "bmp", "why": "Not routinely needed in uncomplicated overactive bladder"}, {"test": "crp", "why": "No role in the evaluation of overactive bladder"}, {"test": "esr", "why": "No role in the evaluation of overactive bladder"}, {"test": "CT urography", "why": "Reserved for hematuria or suspected malignancy or stone", "only_if": "gross or persistent microscopic hematuria, or malignancy or stone is suspected"}, {"test": "Cystoscopy", "why": "Reserved for hematuria, suspected bladder cancer, or refractory symptoms", "only_if": "hematuria, suspected bladder cancer, or refractory symptoms are present"}], "decision_points": ["Exclude urinary tract infection with urinalysis before attributing symptoms to overactive bladder", "Check post-void residual when incomplete emptying or retention is suspected", "Evaluate hematuria for malignancy or stone rather than assuming overactive bladder", "Exclude pregnancy in anyone who could be pregnant before imaging or treatment"], "criteria": [{"name": "Overactive bladder syndrome", "summary": "Urgency with or without urge incontinence, usually with daytime frequency and nocturia, in the absence of urinary tract infection or other obvious pathology.", "items": ["Urgency: a sudden, compelling desire to urinate that is difficult to defer", "Frequency: usually eight or more voids per day", "Nocturia: waking two or more times at night to urinate", "Urge incontinence may or may not be present", "No infection or other identifiable cause"]}], "scores": []}, "differential": [{"name": "Urinary tract infection", "slug": "urinary-tract-infection", "why_considered": "Frequency, urgency and nocturia are classic irritative voiding symptoms of cystitis", "must_not_miss": true, "trigger": "Dysuria, cloudy or malodorous urine, or acute onset over days", "discriminators": {"history": ["Acute onset over days rather than months", "Dysuria and burning with urination", "Suprapubic pain", "Fever or chills if upper tract involved"], "exam": ["Suprapubic tenderness", "Fever", "Costovertebral angle tenderness if pyelonephritis"], "labs": ["Positive leukocyte esterase and nitrite", "Pyuria and bacteriuria on urinalysis", "Positive urine culture"], "imaging": ["Not routinely needed; renal ultrasound or CT if pyelonephritis with obstruction is suspected"]}}, {"name": "Bladder cancer", "slug": "bladder-cancer", "why_considered": "Irritative voiding symptoms including frequency and urgency can be the presenting complaint, especially with carcinoma in situ", "must_not_miss": true, "trigger": "Gross or persistent microscopic hematuria, or refractory irritative symptoms in a smoker", "discriminators": {"history": ["Painless visible blood in u