insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$sepsis$rounds_kb$, $rounds_kb$Sepsis$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$surgery$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$]::text[], array[$rounds_kb$blood$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "sepsis", "triage": {"name": "Sepsis", "case_suitable": true, "reason": "Life-threatening syndrome with a clear presentation, source hunt and time-critical management; core emergency and inpatient topic.", "kind": "disease", "category": "systemic infection", "organ_systems": ["blood"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["emergency", "surgery", "pediatrics"], "commonness": "very_common", "settings": ["emergency", "inpatient", "icu"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:20:02Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:12:07Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:12:15Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:12:38Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:12:52Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:13:00Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'blood_cultures' to 'Blood cultures'", "auto-repaired: workup: renamed 'blood_cultures' to 'Blood cultures'", "auto-repaired: workup: 'lactate' was in ['initial', 'confirmatory'], kept ['initial']", "auto-repaired: workup: 'blood cultures' was in ['initial', 'confirmatory'], kept ['initial']", "auto-repaired: workup: 'ct head without contrast' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'transthoracic echocardiogram' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'ct head without contrast' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'transthoracic echocardiogram' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential cardiogenic-shock: no profile yet", "differential hypovolemic-shock: no profile yet", "differential pulmonary-embolism: no profile yet", "differential acute-pancreatitis: no profile yet", "differential diabetic-ketoacidosis: no profile yet", "differential adrenal-crisis: no profile yet", "differential anaphylaxis: no profile yet", "differential toxic-shock-syndrome: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 18, "typical_max": 90, "peak": "older adults, especially 65+", "possible_min": 0, "possible_max": 110}, "sex": "either", "demographics": ["More common in adults 65 and older", "Most people who develop sepsis have at least one underlying chronic condition or a recent hospitalization", "Children younger than 1 year are at higher risk"], "risk_factors": [{"text": "Age 65 or older", "strength": "strong"}, {"text": "Recent hospitalization or surgery", "strength": "strong"}, {"text": "Indwelling lines, catheters or other medical devices", "strength": "strong"}, {"text": "Weakened immune system (immunosuppression, chemotherapy, steroids)", "strength": "strong"}, {"text": "Chronic conditions such as diabetes, lung disease, cancer or kidney disease", "strength": "moderate"}, {"text": "Pregnancy", "strength": "moderate"}, {"text": "Age younger than 1 year", "strength": "moderate"}, {"text": "Known active infection (pneumonia, urinary tract infection, intra-abdominal infection, skin or wound infection)", "strength": "strong"}, {"text": "Recent influenza or other severe viral illness", "strength": "weak"}], "comorbidities": ["Diabetes mellitus", "Chronic obstructive pulmonary disease or other chronic lung disease", "Chronic kidney disease", "Cancer", "Heart failure", "Cirrhosis", "Immunosuppression or asplenia"], "family_history": [], "social_history": ["Residence in a long-term care facility", "Recent hospitalization or intensive care stay", "Intravenous drug use"], "exposures": ["Recent surgery or invasive procedure", "Indwelling urinary catheter, central line or other device", "Recent antibiotic use"], "risk_medications": ["prednisone", "dexamethasone", "cyclophosphamide", "methotrexate", "tacrolimus", "infliximab"]}, "presentation": {"chief_complaints": [{"text": "I feel terrible all over and I can't stop shaking", "frequency": "common"}, {"text": "I'm burning up and then freezing cold", "frequency": "common"}, {"text": "I'm short of breath and my heart is racing", "frequency": "common"}, {"text": "I feel confused and not myself", "frequency": "sometimes"}, {"text": "I hurt everywhere", "frequency": "sometimes"}], "hpi": {"onset": "Often over hours to a day or two, sometimes faster; may follow a known infection that is getting worse", "duration": "Usually 1–3 days at presentation, but can be less than 24 hours in rapidly progressive cases", "progression": "Worsens steadily; fever and chills give way to weakness, confusion, low blood pressure and difficulty breathing if untreated", "location": "Generalized; may be localized to the source of infection (lungs, abdomen, urinary tract, skin or wound)", "radiation": "Not applicable", "quality": "Feeling of extreme illness with shaking chills, body aches and profound weakness", "severity": "Severe; patients often describe it as the worst they have ever felt", "timing": "Continuous, often worse at night or with any activity", "aggravating": ["Any movement or exertion", "Trying to stand up (lightheadedness)"], "relieving": ["Lying still", "Acetaminophen or ibuprofen for fever (partial and temporary)"], "associated_symptoms": [{"text": "Fever or feeling very hot", "frequency": "common"}, {"text": "Shaking chills", "frequency": "common"}, {"text": "Rapid heart rate or pounding heartbeat", "frequency": "common"}, {"text": "Rapid breathing or shortness of breath", "frequency": "common"}, {"text": "Feeling very weak or tired", "frequency": "common"}, {"text": "Confusion or trouble concentrating", "frequency": "sometimes"}, {"text": "Feeling very cold or clammy", "frequency": "sometimes"}, {"text": "Nausea, vomiting or diarrhea", "frequency": "sometimes"}, {"text": "Decreased urination", "frequency": "sometimes"}, {"text": "Lightheadedness or fainting when standing", "frequency": "sometimes"}, {"text": "Pain at the site of infection (cough, flank pain, abdominal pain, wound pain)", "frequency": "sometimes"}], "pertinent_negatives": ["No new focal neurologic deficit or headache that would suggest stroke or meningitis", "No chest pain typical of cardiac ischemia", "No recent tick bite or rash suggesting rickettsial illness", "No known exposure to a contagious contact with the same illness", "No recent travel to an area with endemic malaria or dengue"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fever", "frequency": "common"}, {"text": "Shaking chills", "frequency": "common"}, {"text": "Severe weakness and fatigue", "frequency": "common"}, {"text": "Feeling very cold", "frequency": "sometimes"}], "negatives": ["Weight loss", "Night sweats lasting weeks"], "argues_against": ["Chronic wasting illness rather than acute infection"]}, {"system": "cardiovascular", "positives": [{"text": "Racing or pounding heart", "frequency": "common"}, {"text": "Lightheadedness on standing", "frequency": "sometimes"}], "negatives": ["Chest pain with exertion", "Swelling of the legs"], "argues_against": ["Acute coronary syndrome", "Heart failure"]}, {"system": "respiratory", "positives": [{"text": "Shortness of breath", "frequency": "common"}, {"text": "Cough producing sputum", "frequency": "sometimes"}], "negatives": ["Pleuritic chest pain", "Coughing up blood"], "argues_against": ["Pulmonary embolism", "Pneumothorax"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea or vomiting", "frequency": "sometimes"}, {"text": "Diarrhea", "frequency": "sometimes"}, {"text": "Abdominal pain", "frequency": "sometimes"}], "negatives": ["Blood in stool", "Jaundice"], "argues_against": ["Acute surgical abdomen requiring immediate operation without infection", "Liver failure"]}, {"system": "genitourinary", "positives": [{"text": "Burning with urination", "frequency": "sometimes"}, {"text": "Flank pain", "frequency": "sometimes"}, {"text": "Decreased urination", "frequency": "sometimes"}], "negatives": ["Blood in urine", "Vaginal discharge"], "argues_against": ["Kidney stone", "Sexually transmitted infection"]}, {"system": "skin", "positives": [{"text": "Clammy or sweaty skin", "frequency": "common"}, {"text": "Redness, warmth or drainage at a wound or line site", "frequency": "sometimes"}, {"text": "New rash", "frequency": "rare"}], "negatives": ["Widespread peeling rash", "Petechiae or purpura"], "argues_against": ["Toxic shock syndrome", "Meningococcemia"]}, {"system": "neurologic", "positives": [{"text": "Confusion or disorientation", "frequency": "sometimes"}, {"text": "Trouble concentrating", "frequency": "sometimes"}], "negatives": ["New weakness on one side", "Severe headache with stiff neck"], "argues_against": ["Stroke", "Meningitis"]}, {"system": "hematologic", "positives": [{"text": "Easy bruising or bleeding", "frequency": "rare"}], "negatives": ["Swollen lymph nodes", "Blood clots in the legs"], "argues_against": ["Lymphoma", "Deep vein thrombosis"]}], "atypical": [{"population": "older_adults", "how_it_differs": "May have little or no fever and present mainly with confusion, falls, weakness or a decline in function; the infection can be far advanced before it is recognized.", "missing_classic_features": ["Fever", "Shaking chills", "Obvious source of infection"]}, {"population": "infants", "how_it_differs": "Present with poor feeding, irritability, lethargy, temperature instability (low or high), vomiting or difficulty breathing rather than localizing complaints.", "missing_classic_features": ["Fever", "Localizing symptoms", "Clear description of feeling unwell"]}, {"population": "children", "how_it_differs": "May have fever, fast breathing, poor perfusion, lethargy or irritability; younger children cannot describe pain or confusion.", "missing_classic_features": ["Confusion", "Body aches"]}, {"population": "immunocompromised", "how_it_differs": "May not mount a fever or a high white count; can present with subtle symptoms and rapid deterioration.", "missing_classic_features": ["Fever", "Marked leukocytosis"]}, {"population": "pregnancy", "how_it_differs": "May present with fever, abdominal pain, uterine tenderness or preterm contractions; normal pregnancy changes in heart rate and blood pressure can mask early sepsis.", "missing_classic_features": ["Marked tachycardia", "Hypotension"]}, {"population": "renal_impairment", "how_it_differs": "May have less fever and more fluid overload or electrolyte disturbance; decreased urine output is harder to interpret against baseline kidney disease.", "missing_classic_features": ["Fever", "Clear change in urine output"]}, {"population": "diabetes", "how_it_differs": "May have blunted fever and present with hyperglycemia, dehydration or a foot or soft tissue infection as the source.", "missing_classic_features": ["Fever", "Shaking chills"]}, {"population": "obesity", "how_it_differs": "May have less reliable temperature elevation and more difficulty with breathing and positioning; skin folds and line sites are common sources.", "missing_classic_features": ["Fever", "Obvious source on routine exam"]}]}, "exam": {"general": {"mild": "Looks unwell but alert and interactive; may be flushed or shivering", "moderate": "Ill-appearing, diaphoretic, tachypneic; prefers to lie still but remains oriented", "severe": "Toxic-appearing, pale or mottled, lethargic or agitated, working hard to breathe", "critical": "Profoundly ill, obtunded or agitated, cold and clammy extremities, barely responsive"}, "findings": [{"id": "altered-mental-status", "region": "mental_status", "maneuver": "Assess orientation to person, place and time; ask about the day and recent events", "finding": "Confusion, disorientation, inattention or reduced alertness", "frequency": "common", "min_severity": "moderate", "significance": "strongly_supports", "importance": "essential"}, {"id": "tachypnea", "region": "lung", "maneuver": "Observe the respiratory rate and pattern at rest", "finding": "Rapid, shallow breathing", "frequency": "common", "min_severity": "mild", "significance": "supports", "importance": "essential"}, {"id": "tachycardia", "region": "cardiac", "maneuver": "Palpate the radial pulse and auscultate the heart rate", "finding": "Tachycardia with a bounding or weak pulse", "frequency": "common", "min_severity": "mild", "significance": "supports", "importance": "essential"}, {"id": "hypotension", "region": "general", "maneuver": "Measure blood pressure supine and after standing if the patient can tolerate it", "finding": "Low blood pressure, or a drop on standing, that does not correct with fluids", "frequency": "common", "min_severity": "severe", "significance": "strongly_supports", "importance": "essential"}, {"id": "delayed-capillary-refill", "region": "extremities", "maneuver": "Press the fingertip or nail bed for 5 seconds and time the color return", "finding": "Capillary refill longer than 3 seconds", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "mottled-skin", "region": "skin", "maneuver": "Inspect the knees, elbows and extremities for color and temperature", "finding": "Mottled, cool or dusky skin with a demarcation line", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "warm-flushed-skin", "region": "skin", "maneuver": "Feel the skin temperature and inspect for flushing", "finding": "Warm, flushed, dry or clammy skin early in the illness", "frequency": "common", "min_severity": "mild", "significance": "supports", "importance": "important"}, {"id": "shaking-chills", "region": "general", "maneuver": "Observe the patient during the interview for rigors", "finding": "Shaking chills or rigors", "frequency": "common", "min_severity": "mild", "significance": "supports", "importance": "important"}, {"id": "dry-mucous-membranes", "region": "heent", "maneuver": "Inspect the oral mucosa and tongue for moisture", "finding": "Dry mucous membranes and reduced skin turgor", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "crackles", "region": "lung", "maneuver": "Auscultate all lung fields during quiet breathing", "finding": "Focal crackles, bronchial breath sounds or dullness suggesting pneumonia", "frequency": "sometimes", "min_severity": "mild", "significance": "supports", "importance": "important"}, {"id": "abdominal-tenderness", "region": "abdomen", "maneuver": "Palpate all four quadrants and check for guarding or rebound", "finding": "Focal tenderness, guarding or rebound suggesting an intra-abdominal source", "frequency": "sometimes", "min_severity": "mild", "significance": "supports", "importance": "important"}, {"id": "costovertebral-tenderness", "region": "abdomen", "maneuver": "Percuss each costovertebral angle", "finding": "Costovertebral angle tenderness suggesting pyelonephritis", "frequency": "sometimes", "min_severity": "mild", "significance": "supports", "importance": "important"}, {"id": "wound-or-line-infection", "region": "skin", "maneuver": "Inspect all surgical wounds, intravenous sites and indwelling devices", "finding": "Erythema, warmth, purulent drainage or tenderness at a wound, line or device site", "frequency": "sometimes", "min_severity": "mild", "significance": "supports", "importance": "essential"}, {"id": "no-meningismus", "region": "neck", "maneuver": "Check for neck stiffness and perform a brief neurologic screen", "finding": "No neck stiffness, no focal neurologic deficit", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-petechiae-purpura", "region": "skin", "maneuver": "Inspect the entire skin surface, including the trunk and extremities", "finding": "No petechiae, purpura or diffuse erythroderma", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-peritoneal-signs", "region": "abdomen", "maneuver": "Palpate gently and check for rebound tenderness", "finding": "No diffuse rigidity or peritoneal signs", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {"temp": {"mild": {"min": 100.4, "max": 102.2}, "moderate": {"min": 101.0, "max": 103.1}, "severe": {"min": 101.5, "max": 104.0}, "critical": {"min": 96.0, "max": 104.5}}, "hr": {"mild": {"min": 90, "max": 110}, "moderate": {"min": 100, "max": 120}, "severe": {"min": 110, "max": 140}, "critical": {"min": 120, "max": 160}}, "rr": {"mild": {"min": 20, "max": 24}, "moderate": {"min": 22, "max": 28}, "severe": {"min": 24, "max": 34}, "critical": {"min": 28, "max": 40}}, "sbp": {"mild": {"min": 100, "max": 130}, "moderate": {"min": 90, "max": 110}, "severe": {"min": 80, "max": 100}, "critical": {"min": 60, "max": 90}}, "dbp": {"mild": {"min": 60, "max": 80}, "moderate": {"min": 50, "max": 70}, "severe": {"min": 40, "max": 60}, "critical": {"min": 30, "max": 50}}, "spo2": {"moderate": {"min": 90, "max": 95}, "severe": {"min": 85, "max": 92}, "critical": {"min": 75, "max": 88}}}, "labs": [{"test_id": "wbc", "ranges": {"mild": {"min": 11.0, "max": 15.0}, "moderate": {"min": 14.0, "max": 20.0}, "severe": {"min": 16.0, "max": 26.0}, "critical": {"min": 2.0, "max": 30.0}}, "frequency": "common", "importance": "essential", "caveat": "Leukocytosis with a left shift is typical, but leukopenia or a normal white count can occur, especially in overwhelming sepsis, older adults and immunocompromised patients."}, {"test_id": "bands_pct", "ranges": {"mild": {"min": 5, "max": 10}, "moderate": {"min": 8, "max": 15}, "severe": {"min": 12, "max": 25}, "critical": {"min": 15, "max": 35}}, "frequency": "common", "importance": "important", "caveat": "A left shift with immature forms supports bacterial infection and can be present even when the total white count is normal."}, {"test_id": "neut_pct", "ranges": {"mild": {"min": 70, "max": 80}, "moderate": {"min": 75, "max": 88}, "severe": {"min": 80, "max": 92}, "critical": {"min": 80, "max": 95}}, "frequency": "common", "importance": "important"}, {"test_id": "lymph_pct", "ranges": {"moderate": {"min": 5, "max": 15}, "severe": {"min": 3, "max": 12}, "critical": {"min": 2, "max": 10}}, "frequency": "sometimes", "importance": "optional", "caveat": "Relative lymphopenia often accompanies the neutrophilia of acute bacterial sepsis."}, {"test_id": "plt", "ranges": {"moderate": {"min": 100, "max": 150}, "severe": {"min": 50, "max": 100}, "critical": {"min": 10, "max": 50}}, "frequency": "common", "importance": "essential", "caveat": "Thrombocytopenia is a marker of organ dysfunction and worsening sepsis; a falling platelet count suggests disseminated intravascular coagulation."}, {"test_id": "lactate", "ranges": {"mild": {"min": 2.0, "max": 2.5}, "moderate": {"min": 2.5, "max": 4.0}, "severe": {"min": 4.0, "max": 8.0}, "critical": {"min": 6.0, "max": 15.0}}, "frequency": "common", "importance": "essential", "caveat": "A lactate of 2 mmol/L or higher supports sepsis and tissue hypoperfusion; repeat to follow response to fluids. Elevated lactate is not specific and can occur with seizures, liver disease or certain medications."}, {"test_id": "cr", "ranges": {"mild": {"min": 1.2, "max": 1.6}, "moderate": {"min": 1.5, "max": 2.5}, "severe": {"min": 2.0, "max": 4.0}, "critical": {"min": 3.0, "max": 8.0}}, "frequency": "common", "importance": "essential", "caveat": "A rise in creatinine from baseline indicates acute kidney injury from hypoperfusion; interpret against the patient's baseline kidney function."}, {"test_id": "bun", "ranges": {"mild": {"min": 20, "max": 30}, "moderate": {"min": 25, "max": 45}, "severe": {"min": 35, "max": 70}, "critical": {"min": 50, "max": 120}}, "frequency": "common", "importance": "important", "caveat": "Rises with dehydration and poor intake as well as kidney injury."}, {"test_id": "hco3", "ranges": {"moderate": {"min": 18, "max": 22}, "severe": {"min": 14, "max": 20}, "critical": {"min": 8, "max": 16}}, "frequency": "common", "importance": "important", "caveat": "Low bicarbonate reflects metabolic acidosis from hypoperfusion and lactic acid."}, {"test_id": "ph", "ranges": {"moderate": {"min": 7.3, "max": 7.35}, "severe": {"min": 7.2, "max": 7.32}, "critical": {"min": 6.9, "max": 7.25}}, "frequency": "sometimes", "importance": "important", "caveat": "Acidemia on arterial blood gas reflects severe hypoperfusion; a respiratory alkalosis may be seen earlier."}, {"test_id": "paco2", "ranges": {"moderate": {"min": 28, "max": 35}, "severe": {"min": 25, "max": 34}, "critical": {"min": 30, "max": 60}}, "frequency": "sometimes", "importance": "optional", "caveat": "Early tachypnea causes a low PaCO2; a rising PaCO2 in a tiring patient signals impending respiratory failure."}, {"test_id": "pao2", "ranges": {"moderate": {"min": 60, "max": 80}, "severe": {"min": 50, "max": 70}, "critical": {"min": 40, "max": 60}}, "frequency": "sometimes", "importance": "important", "caveat": "Hypoxemia suggests pneumonia, acute respiratory distress syndrome or poor perfusion."}, {"test_id": "inr", "ranges": {"moderate": {"min": 1.2, "max": 1.5}, "severe": {"min": 1.5, "max": 2.5}, "critical": {"min": 2.0, "max": 5.0}}, "frequency": "common", "importance": "important", "caveat": "Prolongation supports coagulopathy of sepsis or disseminated intravascular coagulation."}, {"test_id": "aptt", "ranges": {"moderate": {"min": 35, "max": 45}, "severe": {"min": 45, "max": 70}, "critical": {"min": 60, "max": 120}}, "frequency": "sometimes", "importance": "important"}, {"test_id": "fibrinogen", "ranges": {"moderate": {"min": 150, "max": 200}, "severe": {"min": 100, "max": 180}, "critical": {"min": 50, "max": 150}}, "frequency": "sometimes", "importance": "optional", "caveat": "Fibrinogen falls late in disseminated intravascular coagulation; it is often normal or high early as an acute-phase reactant."}, {"test_id": "tbili", "ranges": {"moderate": {"min": 1.2, "max": 2.0}, "severe": {"min": 2.0, "max": 4.0}, "critical": {"min": 3.0, "max": 8.0}}, "frequency": "sometimes", "importance": "important", "caveat": "A rising bilirubin is part of sepsis-related organ dysfunction, especially with a biliary or intra-abdominal source."}, {"test_id": "ast", "ranges": {"moderate": {"min": 40, "max": 100}, "severe": {"min": 80, "max": 300}, "critical": {"min": 200, "max": 1000}}, "frequency": "sometimes", "importance": "optional", "caveat": "Transaminitis can reflect hypoperfusion (shock liver) or a hepatobiliary source."}, {"test_id": "alt", "ranges": {"moderate": {"min": 56, "max": 120}, "severe": {"min": 100, "max": 300}, "critical": {"min": 200, "max": 1000}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "albumin", "ranges": {"moderate": {"min": 2.8, "max": 3.5}, "severe": {"min": 2.0, "max": 3.0}, "critical": {"min": 1.5, "max": 2.5}}, "frequency": "sometimes", "importance": "optional", "caveat": "Falls with acute illness and capillary leak; a low value worsens fluid shifts."}, {"test_id": "glucose", "ranges": {"mild": {"min": 100, "max": 140}, "moderate": {"min": 120, "max": 180}, "severe": {"min": 140, "max": 250}, "critical": {"min": 40, "max": 300}}, "frequency": "common", "importance": "important", "caveat": "Stress hyperglycemia is common; hypoglycemia in a septic patient is a poor sign and can occur with liver failure or adrenal insufficiency."}, {"test_id": "procalcitonin", "ranges": {"mild": {"min": 0.5, "max": 2.0}, "moderate": {"min": 2.0, "max": 10.0}, "severe": {"min": 10.0, "max": 30.0}, "critical": {"min": 20.0, "max": 100.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Supports a bacterial cause and can guide antibiotic duration, but it is not required to diagnose sepsis and may be normal in early or localized infection."}, {"test_id": "crp", "ranges": {"mild": {"min": 1.0, "max": 5.0}, "moderate": {"min": 5.0, "max": 15.0}, "severe": {"min": 10.0, "max": 30.0}, "critical": {"min": 20.0, "max": 50.0}}, "frequency": "common", "importance": "optional", "caveat": "Nonspecific acute-phase reactant; useful for trending but not for diagnosis."}, {"test_id": "ua_le", "qualitative": {"mild": "Trace", "moderate": "1+", "severe": "2+", "critical": "3+"}, "frequency": "sometimes", "importance": "important", "caveat": "Positive leukocyte esterase supports a urinary source; a negative urinalysis does not exclude sepsis from another site."}, {"test_id": "ua_nitrite", "qualitative": {"moderate": "Positive", "severe": "Positive", "critical": "Positive"}, "frequency": "sometimes", "importance": "important", "caveat": "Positive nitrite suggests a gram-negative urinary infection."}, {"test_id": "ua_wbc", "ranges": {"moderate": {"min": 5, "max": 20}, "severe": {"min": 10, "max": 50}, "critical": {"min": 20, "max": 100}}, "frequency": "sometimes", "importance": "important"}, {"test_id": "ua_bacteria", "qualitative": {"moderate": "Few", "severe": "Moderate", "critical": "Many"}, "frequency": "sometimes", "importance": "important"}, {"test_id": "csf_wbc", "ranges": {"moderate": {"min": 10, "max": 100}, "severe": {"min": 100, "max": 1000}, "critical": {"min": 500, "max": 5000}}, "frequency": "rare", "importance": "optional", "caveat": "Only relevant when meningitis is the suspected source; a normal CSF cell count makes bacterial meningitis unlikely."}, {"test_id": "csf_protein", "ranges": {"moderate": {"min": 50, "max": 100}, "severe": {"min": 100, "max": 200}, "critical": {"min": 150, "max": 400}}, "frequency": "rare", "importance": "optional"}, {"test_id": "csf_glucose", "ranges": {"moderate": {"min": 30, "max": 40}, "severe": {"min": 20, "max": 35}, "critical": {"min": 10, "max": 30}}, "frequency": "rare", "importance": "optional", "caveat": "Low CSF glucose relative to serum supports bacterial meningitis."}], "ecg": {"findings": [{"feature": "rate", "finding": "Sinus tachycardia, often marked", "frequency": "common", "min_severity": "mild"}, {"feature": "rhythm", "finding": "New atrial fibrillation with rapid ventricular response", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "other", "finding": "Nonspecific ST-T wave changes", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "st", "finding": "ST elevation in a coronary territory suggesting acute myocardial infarction as an alternative or concurrent diagnosis", "frequency": "rare", "min_severity": "moderate"}, {"feature": "conduction", "finding": "Prolonged QRS or new bundle branch block", "frequency": "rare", "min_severity": "severe"}]}, "imaging": [{"study": "Chest x-ray, portable anteroposterior", "modality": "xray", "preferred_when": "First-line when a pulmonary source is suspected", "findings": [{"text": "Lobar or patchy consolidation consistent with pneumonia", "frequency": "common"}, {"text": "Diffuse bilateral opacities consistent with acute respiratory distress syndrome or pulmonary edema", "frequency": "sometimes"}, {"text": "Pleural