}], "comorbidities": ["Asthma", "Immunodeficiency", "Cystic fibrosis", "Dental infection"], "family_history": ["Atopy or allergic rhinitis"], "social_history": ["Smoking", "Daycare or school exposure to viral infections"], "exposures": ["Recent cold or flu-like illness", "Allergens (dust, pollen, pet dander)", "Irritants (smoke, pollution)"], "risk_medications": ["Nasal decongestant sprays (rebound congestion)", "Immunosuppressants"]}, "presentation": {"chief_complaints": [{"text": "My face hurts and feels pressure", "frequency": "almost_always"}, {"text": "My nose is stuffed up and I have thick yellow-green drainage", "frequency": "common"}, {"text": "I have a cough that won't go away, especially at night", "frequency": "common"}, {"text": "I have a headache and feel pressure around my eyes and cheeks", "frequency": "common"}], "hpi": {"onset": "Gradual, often following a cold that seemed to improve then worsened", "duration": "Acute sinusitis lasts up to 4 weeks; symptoms often present for 10 days or more", "progression": "Starts as a typical cold with clear runny nose, then after 5–7 days develops thicker purulent discharge, facial pain, and worsening congestion", "location": "Face: maxillary (cheeks), frontal (forehead), ethmoid (between eyes), or sphenoid (behind eyes)", "radiation": "Pain may radiate to the upper teeth or behind the eyes", "quality": "Dull, pressure-like, or throbbing pain; worse when bending forward", "severity": "Mild to moderate; often 4–6/10", "timing": "Constant, worse in the morning and with position changes", "aggravating": ["Bending forward", "Lying down", "Straining", "Flying or diving"], "relieving": ["Decongestants", "Saline nasal rinses", "Warm compresses", "Analgesics"], "associated_symptoms": [{"text": "Nasal congestion", "frequency": "almost_always"}, {"text": "Purulent nasal discharge (yellow or green)", "frequency": "common"}, {"text": "Postnasal drip", "frequency": "common"}, {"text": "Facial pain or pressure", "frequency": "common"}, {"text": "Headache", "frequency": "common"}, {"text": "Cough (often worse at night)", "frequency": "common"}, {"text": "Hyposmia or anosmia", "frequency": "sometimes"}, {"text": "Fever", "frequency": "sometimes"}, {"text": "Fatigue", "frequency": "sometimes"}, {"text": "Ear fullness or pressure", "frequency": "sometimes"}, {"text": "Sore throat", "frequency": "sometimes"}, {"text": "Bad breath", "frequency": "sometimes"}], "pertinent_negatives": ["Tooth pain localized to a single tooth", "Vision changes or double vision", "Severe headache with neck stiffness", "Confusion or altered mental status", "Swelling around the eyes", "Shortness of breath or wheezing", "Chest pain", "Blood in sputum", "Night sweats or weight loss"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "sometimes"}, {"text": "Low-grade fever", "frequency": "sometimes"}], "negatives": ["High fever (>102°F)", "Chills", "Night sweats", "Weight loss"]}, {"system": "ent", "positives": [{"text": "Nasal congestion", "frequency": "almost_always"}, {"text": "Purulent nasal discharge", "frequency": "common"}, {"text": "Postnasal drip", "frequency": "common"}, {"text": "Facial pain or pressure", "frequency": "common"}, {"text": "Hyposmia", "frequency": "sometimes"}, {"text": "Ear fullness", "frequency": "sometimes"}, {"text": "Sore throat", "frequency": "sometimes"}], "negatives": ["Epistaxis", "Hearing loss", "Severe dental pain"], "argues_against": ["Unilateral severe headache with vision changes", "Proptosis or periorbital swelling"]}, {"system": "respiratory", "positives": [{"text": "Cough", "frequency": "common"}], "negatives": ["Shortness of breath", "Wheezing", "Hemoptysis", "Pleuritic chest pain"], "argues_against": ["Productive cough with rust-colored sputum", "Tachypnea or hypoxemia"]}, {"system": "neurologic", "positives": [{"text": "Headache", "frequency": "common"}], "negatives": ["Vision changes", "Diplopia", "Neck stiffness", "Confusion", "Focal weakness"], "argues_against": ["Meningismus", "Altered mental status"]}], "atypical": [{"population": "children", "how_it_differs": "Young children may not localize facial pain; they present with persistent nasal discharge, cough, irritability, and poor feeding. Fever may be more prominent.", "missing_classic_features": ["Facial pain or pressure", "Headache"]}, {"population": "older_adults", "how_it_differs": "Symptoms may be milder and fever blunted; they may present with confusion or general malaise without prominent facial pain.", "missing_classic_features": ["Fever", "Severe facial pain"]}, {"population": "immunocompromised", "how_it_differs": "Can progress rapidly to severe or invasive fungal sinusitis; symptoms may be atypical and include severe headache, visual changes, or orbital swelling.", "missing_classic_features": ["Typical gradual onset", "Mild symptoms"]}, {"population": "pregnancy", "how_it_differs": "Physiologic nasal congestion of pregnancy can mimic or worsen sinusitis; symptoms may be attributed to pregnancy rhinitis.", "missing_classic_features": ["Clear distinction from pregnancy-related congestion"]}]}, "exam": {"general": {"mild": "Alert, comfortable, speaking in full sentences; no distress", "moderate": "Mildly uncomfortable, mouth breathing, frequent sniffing or throat clearing", "severe": "Ill-appearing, febrile, splinting face with movement, prefers to sit upright", "critical": "Toxic-appearing with periorbital swelling, proptosis, or altered mental status suggesting orbital or intracranial spread"}, "findings": [{"id": "facial-sinus-tenderness", "region": "heent", "maneuver": "Palpate or percuss over the frontal and maxillary sinuses (forehead and cheeks)", "finding": "Focal tenderness over the frontal or maxillary sinus", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "purulent-nasal-discharge", "region": "heent", "maneuver": "Inspect the nasal cavity with a light and anterior rhinoscopy", "finding": "Purulent (yellow-green) nasal discharge", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "nasal-mucosal-edema", "region": "heent", "maneuver": "Inspect the nasal mucosa and turbinates", "finding": "Erythematous, edematous nasal mucosa with turbinate swelling", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "postnasal-drip", "region": "heent", "maneuver": "Examine the posterior pharynx with a tongue blade and light", "finding": "Posterior pharyngeal drainage or cobblestoning", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "transillumination-abnormal", "region": "heent", "maneuver": "Transilluminate the maxillary and frontal sinuses in a darkened room", "finding": "Reduced or absent transillumination on the affected side", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "facial-edema", "region": "heent", "maneuver": "Inspect the face and periorbital area", "finding": "Facial or periorbital swelling", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "proptosis", "region": "heent", "maneuver": "Inspect and palpate the orbits, assess extraocular movements", "finding": "Proptosis, ophthalmoplegia, or decreased visual acuity suggesting orbital cellulitis or cavernous sinus thrombosis", "frequency": "rare", "min_severity": "critical", "significance": "strongly_supports", "importance": "essential"}, {"id": "normal-lung-exam", "region": "lung", "maneuver": "Auscultate all lung fields", "finding": "Clear breath sounds without crackles, wheezes, or focal consolidation", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-oropharynx", "region": "heent", "maneuver": "Inspect the oropharynx with a tongue blade", "finding": "No tonsillar exudate, uvular deviation, or trismus", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "no-meningismus", "region": "neuro", "maneuver": "Assess neck stiffness and perform a brief neurologic screen", "finding": "No nuchal rigidity, no focal deficits, normal mental status", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-cva-tenderness", "region": "abdomen", "maneuver": "Percuss the costovertebral angles", "finding": "No costovertebral angle tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {"temp": {"mild": {"min": 98.6, "max": 99.5}, "moderate": {"min": 99.5, "max": 100.9}, "severe": {"min": 100.4, "max": 102.2}, "critical": {"min": 101.0, "max": 103.5}}, "hr": {"moderate": {"min": 80, "max": 100}, "severe": {"min": 95, "max": 115}, "critical": {"min": 110, "max": 135}}, "rr": {"severe": {"min": 16, "max": 22}, "critical": {"min": 20, "max": 28}}, "spo2": {"critical": {"min": 88, "max": 94}}}, "labs": [{"test_id": "wbc", "ranges": {"moderate": {"min": 11.0, "max": 15.0}, "severe": {"min": 13.0, "max": 18.0}, "critical": {"min": 15.0, "max": 22.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Acute bacterial sinusitis is a clinical diagnosis; a normal white count does not exclude it and routine CBC is not required."}, {"test_id": "crp", "ranges": {"moderate": {"min": 1.0, "max": 4.0}, "severe": {"min": 3.0, "max": 10.0}, "critical": {"min": 8.0, "max": 20.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Not needed for typical acute sinusitis; marked elevation should raise concern for orbital or intracranial spread."}, {"test_id": "esr", "ranges": {"moderate": {"min": 20, "max": 40}, "severe": {"min": 35, "max": 70}, "critical": {"min": 60, "max": 100}}, "frequency": "sometimes", "importance": "optional"}, {"test_id": "procalcitonin", "ranges": {"moderate": {"min": 0.1, "max": 0.5}, "severe": {"min": 0.5, "max": 2.0}, "critical": {"min": 2.0, "max": 10.0}}, "frequency": "rare", "importance": "optional", "caveat": "Low values support a viral cause and can help avoid antibiotics, but it is not part of routine sinusitis workup."}], "imaging": [{"study": "CT of the paranasal sinuses without IV contrast", "modality": "ct", "preferred_when": "Complications suspected, or when surgery is being planned", "findings": [{"text": "Mucosal thickening and opacification of one or more paranasal sinuses", "frequency": "almost_always"}, {"text": "Air-fluid level within an affected sinus", "frequency": "common"}, {"text": "Osteomeatal complex obstruction", "frequency": "common"}, {"text": "Nasal septal deviation or concha bullosa", "frequency": "sometimes"}, {"text": "Nasal polyps", "frequency": "sometimes"}, {"text": "Orbital or intracranial extension (subperiosteal abscess, epidural or subdural empyema)", "frequency": "rare"}]}, {"study": "MRI of the brain and orbits with and without IV contrast", "modality": "mri", "preferred_when": "Suspected orbital or intracranial complication, or invasive fungal sinusitis", "findings": [{"text": "Enhancement and inflammation extending into the orbit or cavernous sinus", "frequency": "common"}, {"text": "Extra-axial fluid collection or abscess", "frequency": "sometimes"}, {"text": "Cavernous sinus thrombosis", "frequency": "rare"}]}, {"study": "Plain radiographs of the paranasal sinuses (Waters, Caldwell, lateral views)", "modality": "xray", "findings": [{"text": "Sinus opacification or air-fluid level", "frequency": "sometimes"}, {"text": "Findings are nonspecific and correlate poorly with symptoms", "frequency": "common"}]}, {"study": "CT of the paranasal sinuses with IV contrast", "modality": "ct", "preferred_when": "Suspected orbital or intracranial complication when MRI is unavailable", "findings": [{"text": "Enhancing soft tissue extending beyond the sinus wall", "frequency": "common"}, {"text": "Subperiosteal or intracranial abscess", "frequency": "sometimes"}]}], "workup": {"initial": [{"test": "CT of the paranasal sinuses without IV contrast", "why": "Defines extent of disease and anatomy when a complication is suspected or surgery is planned", "only_if": "orbital or intracranial complication is suspected, or surgery is being considered"}, {"test": "MRI of the brain and orbits with and without IV contrast", "why": "Best study for orbital or intracranial spread and for invasive fungal disease", "only_if": "proptosis, ophthalmoplegia, vision loss, severe headache, or altered mental status"}], "confirmatory": [], "supporting": [{"test": "cbc", "why": "Supports a bacterial process when fever or systemic illness is prominent", "only_if": "fever, severe illness, or concern for a complication"}, {"test": "crp", "why": "Adds objective evidence of bacterial inflammation when the diagnosis is uncertain", "only_if": "diagnosis is unclear or a complication is suspected"}], "not_indicated": [{"test": "CT of the paranasal sinuses without IV contrast", "why": "Not needed for uncomplicated acute sinusitis, which is a clinical diagnosis"}, {"test": "Plain radiographs of the paranasal sinuses (Waters, Caldwell, lateral views)", "why": "Poor sensitivity and specificity; does not change management"}, {"test": "MRI of the brain and orbits with and without IV contrast", "why": "Reserved for suspected orbital or intracranial complications"}, {"test": "cbc", "why": "Routine blood work does not change management of uncomplicated sinusitis"}, {"test": "crp", "why": "Not required for typical acute sinusitis"}, {"test": "esr", "why": "Nonspecific and not part of routine workup"}, {"test": "procalcitonin", "why": "Not established for sinusitis management"}, {"test": "d_dimer", "why": "No role in sinusitis"}, {"test": "lactate", "why": "No role unless sepsis is suspected"}], "decision_points": ["Acute bacterial sinusitis is diagnosed clinically: symptoms lasting 10 days or more without improvement, severe symptoms with fever over 102°F and purulent discharge for 3–4 days, or a cold that improves then worsens (double worsening).", "Imaging is not needed for uncomplicated acute sinusitis; reserve CT for suspected complications or surgical planning.", "Suspect orbital or intracranial extension with periorbital swelling, proptosis, vision changes, severe headache, or altered mental status; obtain urgent MRI or contrast CT.", "Consider invasive fungal sinusitis in immunocompromised or poorly controlled diabetic patients with severe symptoms; this is a surgical emergency."], "criteria": [{"name": "Clinical diagnosis of acute bacterial rhinosinusitis", "summary": "Diagnosed when symptoms persist 10 days or more without improvement, or when severe symptoms (fever 102°F or higher, purulent discharge, facial pain) are present for at least 3–4 consecutive days, or when symptoms worsen after initial improvement (double worsening).", "items": ["Symptoms 10 days or more without improvement", "Severe symptoms with fever 102°F or higher and purulent discharge for 3–4 days", "Worsening after initial improvement (double worsening)"]}], "scores": []}, "differential": [{"name": "Viral upper respiratory infection (common cold)", "slug": "common-cold", "why_considered": "Most acute sinusitis begins as a viral URI, and the two share congestion, clear-to-mucoid discharge, and mild facial pressure.", "must_not_miss": false, "discriminators": {"history": ["Symptoms peak in 3–5 days and improve within 7–10 days", "Discharge starts clear and thins over time", "No double worsening after initial improvement", "Low-grade or no fever"], "exam": ["Nasal mucosa erythematous but without focal sinus tenderness", "No purulent discharge in the middle meatus", "Oropharynx may show mild erythema without exudate"], "labs": ["Not routinely indicated; viral testing (e.g., influenza, SARS-CoV-2) may identify a specific cause"], "imaging": ["Not indicated; sinus imaging is nonspecific and may show mucosal thickening even in uncomplicated viral illness"]}}, {"name": "Allergic rhinitis", "slug": "allergic-rhinitis", "why_considered": "Nasal congestion, clear rhinorrhea, and facial pressure that can mimic sinusitis, especially with seasonal or perennial triggers.", "must_not_miss": false, "discriminators": {"history": ["Itchy eyes, nose, and throat", "Sneezing and watery rhinorrhea", "Seasonal or allergen exposure pattern", "No purulent discharge or fever"], "exam": ["Pale, boggy nasal turbinates", "Allergic shiners or transverse nasal crease", "Cobblestoning of the posterior pharynx", "No focal sinus tenderness"], "labs": ["Allergen-specific IgE or skin testing may confirm sensitization if diagnosis is unclear"], "imaging": ["Not indicated; sinus CT may show incidental mucosal thickening"]}}, {"name": "Influenza", "slug": "influenza", "why_considered": "Fever, myalgias, headache, and respiratory congestion can overlap with acute sinusitis, especially early in the illness.", "must_not_miss": false, "discriminators": {"history": ["Abrupt onset of high fever, chills, and severe myalgias", "Prominent systemic symptoms out of proportion to nasal complaints", "Community outbreak or known exposure"], "exam": ["High fever (often >102°F)", "Diffuse pharyngeal erythema without focal sinus tenderness", "Clear or mucoid nasal discharge early"], "labs": ["Positive rapid influenza antigen or molecular test"], "imaging": ["Not indicated unless pneumonia is suspected"]}}, {"name": "Acute bacterial rhinosinusitis", "slug": "acute-bacterial-rhinosinusitis", "why_considered": "The condition being evaluated; must be distinguished from viral and non-infectious causes to guide antibiotic use.", "must_not_miss": false, "discriminators": {"history": ["Symptoms 10 days or more without improvement", "Severe symptoms with fever 102°F or higher and purulent discharge for 3–4 days", "Double worsening after initial improvement"], "exam": ["Focal tenderness over maxillary or frontal sinuses", "Purulent discharge in the middle meatus", "Nasal mucosal edema"], "labs": ["Not required; CBC and CRP may support bacterial process if systemic illness is prominent"], "imaging": ["Not indicated for uncomplicated disease; CT reserved for complications or surgical planning"]}}, {"name": "Dental infection (odontogenic sinusitis)", "slug": "dental-abscess", "why_considered": "Maxillary tooth root infection can spread to the maxillary sinus and cause unilateral facial pain and purulent nasal discharge.", "must_not_miss": true, "trigger": "Unilateral maxillary pain with dental tenderness or poor dentition", "discriminators": {"history": ["Localized tooth pain or sensitivity to chewing", "Recent dental work or known caries", "Unilateral symptoms"], "exam": ["Dental tenderness or percussion pain over a specific tooth", "Focal maxillary tenderness", "Possible gingival swelling or sinus tract"], "labs": ["Not specific; CBC may show leukocytosis if abscess is present"], "imaging": ["Dental radiographs or panoramic X-ray showing periapical abscess", "CT of sinuses may show unilateral maxillary sinus opacification with a dental source"]}}, {"name": "Orbital cellulitis", "slug": "orbital-cellulitis", "why_considered": "Sinusitis can spread to the orbit, and orbital cellulitis can present with facial pain, fever, and periorbital swelling that may be mistaken for severe sinusitis.", "must_not_miss": true, "trigger": "Periorbital swelling, proptosis, or vision changes in a patient with sinus symptoms", "discriminators": {"history": ["Rapidly progressive periorbital swelling and redness", "Pain with eye movement", "Blurred or double vision", "Recent sinusitis or upper respiratory infection"], "exam": ["Proptosis, chemosis, and ophthalmoplegia", "Decreased visual acuity", "Fever and toxic appearance"], "labs": ["CBC with leukocytosis", "Blood cultures if systemic signs are present"], "imaging": ["Contrast-enhanced CT or MRI of orbits and brain showing orbital fat stranding, subperiosteal abscess, or cavernous sinus thrombosis"]}}, {"name": "Cavernous sinus thrombosis", "