oderate"}, {"text": "Physical inactivity", "strength": "moderate"}, {"text": "Family history of stroke or TIA", "strength": "moderate"}, {"text": "Black or Hispanic race/ethnicity", "strength": "moderate"}, {"text": "Illicit drug use (cocaine, amphetamines)", "strength": "weak"}, {"text": "Obstructive sleep apnea", "strength": "weak"}], "comorbidities": ["Hypertension", "Atrial fibrillation or other cardiac disease", "Diabetes mellitus", "Hyperlipidemia", "Coronary artery disease", "Heart failure", "Chronic kidney disease", "Prior TIA or stroke", "Carotid artery disease", "Sickle cell disease"], "family_history": ["Stroke or TIA in a first-degree relative", "Premature cardiovascular disease in a first-degree relative"], "social_history": ["Current or former smoking", "Heavy alcohol use", "Sedentary lifestyle", "Illicit stimulant use"], "exposures": [], "risk_medications": ["Oral contraceptives", "Hormone replacement therapy", "Anticoagulants (may increase hemorrhagic stroke risk)", "Cocaine", "Amphetamines"]}, "presentation": {"chief_complaints": [{"text": "My face feels droopy on one side", "frequency": "common"}, {"text": "My arm went weak all of a sudden", "frequency": "common"}, {"text": "My speech is slurred and I can't get my words out", "frequency": "common"}, {"text": "I suddenly can't see out of one eye", "frequency": "sometimes"}, {"text": "I feel dizzy and can't keep my balance", "frequency": "sometimes"}, {"text": "I have the worst headache of my life", "frequency": "sometimes"}], "hpi": {"onset": "Sudden, maximal or near-maximal within seconds to minutes; patients often can name the exact moment", "duration": "Symptoms present at the time of presentation; deficits that resolve within minutes to an hour suggest TIA", "progression": "Typically fixed or improving slightly after onset; stepwise worsening can occur with large-vessel occlusion or hemorrhagic expansion", "location": "Focal, corresponding to the affected vascular territory; commonly one side of the face, arm and/or leg, or one visual field", "radiation": "Not applicable; symptoms are focal and do not radiate", "quality": "Loss of function rather than pain: weakness, numbness, slurred or absent speech, visual loss, imbalance", "severity": "Variable; can be mild (minor hand clumsiness) to severe (complete hemiplegia, inability to speak or walk)", "timing": "Abrupt onset, non-fluctuating; may be worse on waking if stroke occurred during sleep", "aggravating": [], "relieving": [], "associated_symptoms": [{"text": "Facial droop on one side", "frequency": "common"}, {"text": "Weakness or clumsiness of one arm or leg", "frequency": "common"}, {"text": "Slurred speech or trouble finding words", "frequency": "common"}, {"text": "Numbness or tingling on one side", "frequency": "common"}, {"text": "Trouble understanding what others are saying", "frequency": "sometimes"}, {"text": "Sudden visual loss or double vision", "frequency": "sometimes"}, {"text": "Dizziness, unsteadiness or trouble walking", "frequency": "sometimes"}, {"text": "Severe headache with no known cause", "frequency": "sometimes"}, {"text": "Confusion or trouble concentrating", "frequency": "sometimes"}, {"text": "Loss of consciousness or fainting", "frequency": "rare"}], "pertinent_negatives": ["Gradual onset over hours to days", "Symptoms that spread (march) from one body part to another", "Recent head trauma", "Fever or neck stiffness", "Known seizure disorder with a typical postictal pattern", "Hypoglycemia or recent insulin dose change", "Drug overdose or alcohol withdrawal", "Prior similar episodes that fully resolved (suggests TIA rather than completed stroke)"]}, "ros": [{"system": "neurologic", "positives": [{"text": "Sudden weakness or numbness on one side of the body", "frequency": "almost_always"}, {"text": "Slurred speech or difficulty speaking", "frequency": "common"}, {"text": "Trouble understanding speech", "frequency": "sometimes"}, {"text": "Visual loss in one eye or one visual field", "frequency": "sometimes"}, {"text": "Dizziness or loss of balance", "frequency": "sometimes"}, {"text": "Severe headache", "frequency": "sometimes"}, {"text": "Confusion", "frequency": "sometimes"}], "negatives": ["Gradual progressive weakness over days", "Symptoms that migrate from one limb to another", "Loss of consciousness at onset", "Recent seizure activity"], "argues_against": ["Gradual onset over hours to days", "Marching sensory symptoms", "Prominent fever and meningismus"]}, {"system": "cardiovascular", "positives": [{"text": "Irregular or racing heartbeat", "frequency": "sometimes"}, {"text": "Chest pain or pressure", "frequency": "rare"}], "negatives": ["Exertional chest pain", "Orthopnea", "Leg swelling"], "argues_against": ["Syncope as the only symptom"]}, {"system": "constitutional", "positives": [{"text": "Feeling tired or unwell", "frequency": "sometimes"}], "negatives": ["Fever", "Weight loss", "Night sweats"], "argues_against": ["Fever with focal deficit (suggests infection)"]}, {"system": "eyes", "positives": [{"text": "Sudden loss of vision in one eye", "frequency": "sometimes"}, {"text": "Double vision", "frequency": "sometimes"}], "negatives": ["Eye pain", "Redness of the eye", "Gradual visual decline over months"], "argues_against": ["Painful red eye with visual change"]}, {"system": "musculoskeletal", "positives": [], "negatives": ["Joint pain", "Muscle tenderness", "Recent trauma"], "argues_against": ["Focal limb pain with preserved strength"]}], "atypical": [{"population": "older_adults", "how_it_differs": "May present with confusion, falls, or generalized weakness rather than clear focal deficits; aphasia may be mistaken for dementia.", "missing_classic_features": ["Clear one-sided weakness", "Obvious facial droop"]}, {"population": "children", "how_it_differs": "Stroke is rare but can present with seizures, altered mental status, or isolated hemiparesis; risk factors include sickle cell disease, congenital heart disease, and vasculop