insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$tinea-infections$rounds_kb$, $rounds_kb$Tinea Infections$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, array[$rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$]::text[], array[$rounds_kb$musculoskeletal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "tinea-infections", "triage": {"name": "Tinea Infections", "case_suitable": true, "reason": "Common dermatophyte infection with classic rash patterns; diagnosis is made by history and exam with KOH confirmation, and mimics eczema and psoriasis.", "kind": "disease", "category": "superficial fungal infection", "organ_systems": ["musculoskeletal"], "primary_clerkship": "familyMedicine", "secondary_clerkships": ["pediatrics", "internalMedicine"], "commonness": "very_common", "settings": ["clinic", "pediatric_clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:20:40Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:16:56Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:17:02Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:17:05Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:17:17Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "9", "generated_at": "2026-10-05T07:17:24Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'fungal culture of skin, hair, or nail' was