derate": "Cystitis with more marked symptoms or early pyelonephritis: fever, chills, flank pain and costovertebral angle tenderness, with mild leukocytosis", "severe": "Pyelonephritis with systemic illness: high fever, rigors, vomiting, tachycardia, dehydration and acute kidney injury", "critical": "Urosepsis with hemodynamic instability, altered mental status, respiratory distress or organ dysfunction"}, "red_flags": [{"finding": "High fever with rigors and flank pain", "meaning": "Upper tract infection (pyelonephritis); needs longer treatment and urine culture"}, {"finding": "Hypotension, tachycardia or confusion", "meaning": "Sepsis from urosepsis; needs urgent fluids, cultures and broad-spectrum antibiotics"}, {"finding": "Vomiting and inability to keep fluids or oral antibiotics down", "meaning": "Dehydration and failure of oral therapy; consider admission and IV antibiotics"}, {"finding": "Rising creatinine or decreased urine output", "meaning": "Kidney involvement or obstruction; image the urinary tract"}, {"finding": "Symptoms persisting or worsening after 48–72 hours of appropriate antibiotics", "meaning": "Resistant organism, obstruction, abscess or an alternative diagnosis; image and reculture"}, {"finding": "Pregnancy with urinary symptoms or positive urine culture", "meaning": "Risk of pyelonephritis and preterm labor; treat and follow up closely"}, {"finding": "Male sex with febrile UTI", "meaning": "Complicated infection; evaluate for obstruction or prostatic involvement"}], "complications": [{"name": "Acute pyelonephritis", "timing": "early", "seriousness": "serious", "frequency": "sometimes", "clues": ["Fever and chills", "Flank pain", "Costovertebral angle tenderness", "Nausea and vomiting"]}, {"name": "Renal or perinephric abscess", "timing": "early", "seriousness": "serious", "frequency": "rare", "clues": ["Persistent fever after 48–72 hours of antibiotics", "Flank mass or severe localized pain", "CT showing a fluid collection"]}, {"name": "Emphysematous pyelonephritis", "timing": "early", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Diabetes mellitus", "Severe systemic illness", "Gas within the renal parenchyma on CT"]}, {"name": "Urosepsis and septic shock", "timing": "early", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Hypotension", "Tachycardia", "Altered mental status", "Elevated lactate"]}, {"name": "Acute kidney injury", "timing": "early", "seriousness": "serious", "frequency": "sometimes", "clues": ["Rising creatinine", "Decreased urine output", "Dehydration or obstruction"]}, {"name": "Recurrent UTI", "timing": "late", "seriousness": "minor", "frequency": "sometimes", "clues": ["Two or more infections in six months or three or more in a year", "Repeated positive urine cultures"]}, {"name": "Preterm labor and low birth weight", "timing": "late", "seriousness": "serious", "frequency": "rare", "clues": ["Pregnancy with untreated bacteriuria or pyelonephritis", "Uterine contractions or cervical change"]}], "special_populations": [{"population": "children", "differences": "Infants and young children may present only with fever, irritability, poor feeding or vomiting; obtain a urine culture before antibiotics and consider ultrasound after a first febrile UTI."}, {"population": "infants", "differences": "Fever without a source is the usual presentation; bagged urine specimens are unreliable and catheterization or suprapubic aspiration is preferred for culture."}, {"population": "older_adults", "differences": "May present with confusion, falls, weakness or decreased appetite rather than dysuria; fever may be absent, and asymptomatic bacteriuria is common so symptoms must be confirmed before treating."}, {"population": "pregnancy", "differences": "Screen and treat asymptomatic bacteriuria; avoid fluoroquinolones and tetracyclines; untreated infection risks pyelonephritis, preterm labor and low birth weight."}, {"population": "immunocompromised", "differences": "Symptoms may be blunted and fever may be the only sign; higher risk of rapid progression to sepsis and unusual organisms."}, {"population": "diabetes", "differences": "More likely to have asymptomatic bacteriuria and complicated upper tract infection, including emphysematous pyelonephritis; symptoms may be milder than expected."}, {"population": "renal_impairment", "differences": "May have fewer urinary symptoms and more systemic signs; adjust antibiotic doses and follow kidney function closely."}]}, "teaching": {"key_questions": [{"question": "What urinary symptoms are you having — burning, going more often, or a sudden urge to go?", "category": "hpi", "importance": "essential", "looking_for": "Dysuria, frequency and urgency — the core symptoms of lower urinary tract infection"}, {"question": "When did these symptoms start, and are they getting better or worse?", "category": "hpi", "importance": "important", "looking_for": "Abrupt onset over hours to a day or two, worsening without treatment"}, {"question": "Do you have any fever, chills or shaking?", "category": "associated", "importance": "essential", "looking_for": "Fever and rigors suggest upper tract infection (pyelonephritis) rather than simple cystitis"}, {"question": "Do you have pain in your back or side below the ribs?", "category": "associated", "importance": "essential", "looking_for": "Flank pain suggests pyelonephritis; its absence supports cystitis"}, {"question": "Have you felt nauseated or vomited?", "category": "associated", "importance": "important", "looking_for": "Nausea and vomiting suggest systemic illness or upper tract involvement"}, {"question": "Have you noticed blood in your urine, or that it looks cloudy or smells bad?", "category": "hpi", "importance": "important", "looking_for": "Hematuria, cloudy or malodorous urine support UTI but are nonspecific"}, {"question": "Have you had a urinary tract infection before, and how was it treated?", "category": "pmh", "importance": "important", "looking_for": "Prior UTIs, recent antibiotics and any resistant organisms"}, {"question": "Do you have diabetes, kidney stones, a spinal cord injury, or any trouble emptying your bladder?", "category": "pmh", "importance": "important", "looking_for": "Conditions that make the infection complicated or predispose to recurrence"}, {"question": "Do you have a urinary catheter or have you had any recent urinary procedures?", "category": "pmh", "importance": "important", "looking_for": "Catheter-associated or instrumented infection, which is often complicated"}, {"question": "Are you sexually active, and do you use spermicides or a diaphragm?", "category": "sexual", "importance": "important", "looking_for": "Sexual activity and spermicide use are strong risk factors; also raises the question of urethritis or vaginitis"}, {"question": "Have you had any vaginal discharge, itching or sores?", "category": "ros", "importance": "important", "looking_for": "Present suggests vaginitis or a sexually transmitted infection rather than UTI"}, {"question": "Could you be pregnant? When was your last menstrual period?", "category": "obstetric", "importance": "essential", "looking_for": "Pregnancy changes treatment and follow-up; also excludes ectopic pregnancy in a woman with pelvic pain"}, {"question": "Are you taking any medications, especially SGLT2 inhibitors, steroids or immunosuppressants?", "category": "medications", "importance": "important", "looking_for": "Medications that increase UTI risk or affect antibiotic choice"}, {"question": "Do you have any allergies to antibiotics, especially penicillins or sulfa drugs?", "category": "allergies", "importance": "important", "looking_for": "Allergies that limit antibiotic selection"}, {"question": "Have you been confused, very weak, or had any falls recently?", "category": "red_flag", "importance": "important", "looking_for": "In older adults, confusion or falls may be the presenting sign of UTI or sepsis"}], "accepted_names": ["Urinary tract infection", "UTI", "Cystitis", "Acute cystitis", "Lower urinary tract infection", "Bladder infection", "Acute pyelonephritis", "Pyelonephritis", "Upper urinary tract infection", "Complicated urinary tract infection", "Urosepsis"], "reasoning_points": ["Dysuria, urinary frequency and urgency with suprapubic discomfort point to a lower urinary tract infection", "Fever, chills, flank pain and costovertebral angle tenderness indicate upper tract involvement (pyelonephritis)", "Urinalysis showing leukocyte esterase, nitrite, pyuria and bacteriuria supports the diagnosis", "Urine culture confirms the organism and guides therapy, especially in complicated, recurrent or upper tract infection", "Pregnancy must be excluded before imaging or choosing antibiotics", "Look-alikes such as urethritis, vaginitis, pelvic inflammatory disease, nephrolithiasis and interstitial cystitis are considered and excluded by history, exam and urinalysis", "Red flags such as hypotension, confusion, vomiting or rising creatinine suggest sepsis or a complicated infection requiring urgent care"], "difficulty": {"easy": ["Sexually active young woman with classic dysuria, frequency and urgency", "No fever or flank pain, suprapubic tenderness only", "Urinalysis positive for leukocyte esterase, nitrite and pyuria", "Clear response to a short course of antibiotics"], "medium": ["Older adult with confusion or falls but no dysuria", "Man with dysuria and frequency suggesting prostatitis or obstruction", "Pregnant patient with asymptomatic bacteriuria or mild symptoms", "Patient with diabetes and a more complicated or upper tract infection", "Symptoms overlap with vaginitis or a sexually transmitted infection"], "hard": ["Afebrile older adult with nonspecific weakness and a normal white count", "Recurrent UTI with a resistant organism or anatomic abnormality", "Pyelonephritis with obstruction, abscess or failure to improve after 48–72 hours", "Urosepsis with hypotension, tachycardia and elevated lactate", "Catheterized or spinal cord injury patient with blunted symptoms"]}}}$rounds_kb$::jsonb)
