discriminators": {"history": ["Diabetes or hypertension", "Edema", "Nocturia", "Known kidney disease"], "exam": ["Hypertension", "Edema", "Pallor"], "labs": ["Elevated creatinine and BUN", "Low eGFR", "Elevated PTH", "Low 25-hydroxyvitamin D", "Low or normal calcium", "High phosphorus"], "imaging": ["Small echogenic kidneys on ultrasound"]}}], "course": {"severity": {"mild": "25-hydroxyvitamin D 10–19 ng/mL; no symptoms or only mild fatigue; normal calcium, phosphorus, and alkaline phosphatase", "moderate": "25-hydroxyvitamin D 5–9 ng/mL; bone pain, proximal muscle weakness, fatigue; alkaline phosphatase may be elevated; calcium usually normal", "severe": "25-hydroxyvitamin D less than 5 ng/mL; marked bone pain, waddling gait, difficulty rising from a chair, fractures; hypocalcemia and hypophosphatemia may be present; rickets or osteomalacia on imaging", "critical": "Severe deficiency with symptomatic hypocalcemia (tetany, seizures, laryngospasm, prolonged QT) or life-threatening complications such as cardiomyopathy in infants or severe respiratory muscle weakness"}, "red_flags": [{"finding": "Seizures, tetany, or laryngospasm", "meaning": "Severe hypocalcemia from prolonged vitamin D deficiency; needs urgent calcium and vitamin D replacement"}, {"finding": "Prolonged QT interval on ECG", "meaning": "Hypocalcemia; risk of arrhythmia"}, {"finding": "New focal bone pain or pathologic fracture", "meaning": "Osteomalacia with insufficiency fracture or another bone lesion; needs imaging"}, {"finding": "Inability to bear weight or stand from a chair", "meaning": "Severe proximal myopathy; high fall and fracture risk"}, {"finding": "Infant with poor feeding, irritability, or breathing difficulty", "meaning": "Possible hypocalcemic cardiomyopathy or rickets; urgent evaluation"}], "complications": [{"name": "Osteomalacia", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Diffuse bone pain", "Proximal muscle weakness", "Waddling gait", "Looser zones on x-ray"]}, {"name": "Rickets", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Bowing of the legs", "Widened wrists and ankles", "Rachitic rosary", "Delayed walking"]}, {"name": "Osteoporosis and fragility fractures", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Low bone mineral density on DXA", "Fracture with minimal trauma", "Height loss"]}, {"name": "Symptomatic hypocalcemia", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Perioral numbness", "Carpopedal spasm", "Seizures", "Prolonged QT"]}, {"name": "Dilated cardiomyopathy", "timing": "early", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Heart failure in an infant", "Poor feeding", "Tachypnea", "Hypocalcemia"]}, {"name": "Falls and fall-related injury", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Proximal muscle weakness", "Gait instability", "Older adult"]}], "special_populations": [{"population": "children", "differences": "Can present with rickets: bowing of the legs, delayed walking, widened wrists and ankles, rachitic rosary, and craniotabes. Alkaline phosphatase is often markedly elevated and phosphorus low."}, {"population": "infants", "differences": "Exclusively breastfed infants without supplementation are at high risk. May present with seizures, poor feeding, or breathing difficulty from hypocalcemia rather than bone pain."}, {"population": "older_adults", "differences": "May present with falls, fractures, or confusion rather than reporting bone pain. Skin makes vitamin D less efficiently and kidneys activate it less well. Higher intake (800 IU/day) is recommended."}, {"population": "pregnancy", "differences": "May present with leg cramps, pelvic girdle pain, or fatigue. Routine prenatal vitamins may partially treat it. Deficiency is associated with preeclampsia and gestational diabetes."}, {"population": "obesity", "differences": "Body fat sequesters vitamin D, so higher doses are often needed to reach sufficiency. Symptoms may be mild or absent despite low levels."}, {"population": "renal_impairment", "differences": "Chronic kidney disease impairs activation of vitamin D. May need activated vitamin D analogs (calcitriol) rather than plain cholecalciferol. Monitor calcium and phosphorus closely."}, {"population": "hepatic_impairment", "differences": "Chronic liver disease impairs 25-hydroxylation. May need higher or alternative dosing and monitoring."}, {"population": "immunocompromised", "differences": "Low vitamin D is associated with increased susceptibility to infections; supplementation may be part of supportive care."}]}, "teaching": {"key_questions": [{"question": "How much time do you spend outdoors in the sun, and do you cover your skin or use sunscreen?", "category": "social", "importance": "essential", "looking_for": "Limited sun exposure: housebound, indoor or night-shift work, high latitude, concealing clothing, or heavy sunscreen use"}, {"question": "What do you usually eat and drink in a day? Do you drink milk or eat fatty fish, eggs, or fortified foods?", "category": "hpi", "importance": "important", "looking_for": "Low dietary intake of vitamin D from fatty fish, fortified milk, eggs, or supplements"}, {"question": "Do you take any vitamin D or multivitamin supplements?", "category": "medications", "importance": "important", "looking_for": "No supplementation, or an inadequate dose; breastfed infants without 400 IU daily are at high risk"}, {"question": "Have you had stomach or intestinal surgery, such as gastric bypass?", "category": "pmh", "importance": "important", "looking_for": "Bariatric surgery or small bowel resection, which impairs absorption"}, {"question": "Do you have any conditions that affect absorption, like celiac disease, Crohn's disease, or cystic fibrosis?", "category": "pmh", "importance": "important", "looking_for": "Malabsorption as the underlying cause"}, {"question": "Do you have kidney or liver disease?", "category": "pmh", "importance": "important", "looking_for": "Chronic kidney or liver disease, which impairs activation of vitamin D"}, {"question": "Do you take any seizure medicines, steroids, cholesterol medicines, or weight-loss medicines?", "category": "medications", "importance": "important", "looking_for": "Anticonvulsants, glucocorticoids, cholestyramine, or orlistat that affect vitamin D metabolism"}, {"question": "Have you noticed any bone pain, muscle weakness, or trouble getting up from a chair or climbing stairs?", "category": "hpi", "importance": "essential", "looking_for": "Diffuse bone pain and proximal muscle weakness, especially in the hips and shoulders"}, {"question": "Have you had any falls or broken bones with little or no trauma?", "category": "associated", "importance": "important", "looking_for": "Fragility fractures or falls suggesting osteomalacia or osteoporosis"}, {"question": "Have you had any numbness around the mouth, muscle spasms, or twitching?", "category": "ros", "importance": "important", "looking_for": "Symptoms of hypocalcemia such as perioral numbness, carpopedal spasm, or tetany"}, {"question": "For infants and children: is the child exclusively breastfed, and are they receiving vitamin D drops?", "category": "hpi", "importance": "essential", "looking_for": "Exclusively breastfed infant without 400 IU daily supplementation"}, {"question": "For children: has the child had delayed walking, bowing of the legs, or widened wrists and ankles?", "category": "hpi", "importance": "important", "looking_for": "Signs of rickets such as bowing, delayed motor milestones, or skeletal deformity"}], "accepted_names": ["Vitamin D deficiency", "Hypovitaminosis D", "Low vitamin D", "Vitamin D insufficiency"], "reasoning_points": ["Low 25-hydroxyvitamin D level confirms the diagnosis (deficiency generally below 20 ng/mL)", "Risk factors such as limited sun exposure, dark skin, exclusive breastfeeding 